INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014069', 'AN1558', 'トルフィン・カルルセヴニ', 'Birthyear: 996  Thorfinn is a courageous young man armed with two twin blades he inherited from his deceased father. He''s traveling with Askeladd, who is the leader of a ruthless group of mercenaries who take jobs from whoever they think can offer them a reasonable reward. Besides, Askeladd is the man who killed Thorfinn''s father, Thors, and the only reason Thorfinn is traveling with Askeladd is so he can defeat him in a duel and win back his father''s pride. Thorfinn only wants to win his father', 6, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b10138-zOPrka0ddZOR.png', '2月3日', NULL, '上村祐翔', 100, 10138, 'MAIN', 22375) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014070', 'AN1558', 'エイナル', 'Einar is a man from Northern England that was sold into slavery. He ends up in Denmark, where he meets Thorfinn. Together with him, Einar is working his way out of slavery by harvesting the land his master has lent to him and Thorfinn.', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b28030-APYJLr7FvqtM.jpg', NULL, NULL, '武内駿輔', 184, 28030, 'MAIN', 1372) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014071', 'AN1558', 'スヴェルケル', 'Sverkel is the elderly father of Ketil, living on the ground of his son''s farm in Jutland, Denmark.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255607-jXjRTKh9J8Q6.jpg', NULL, NULL, '麦人', NULL, 255607, 'SUPPORTING', 112) ON CONFLICT DO NOTHING;
