INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014084', 'AN1558', 'アルネイズ', 'One of Ketil''s slaves, serving as his personal maid and concubine. Arnheid is kind, hard-working, honest, and tries her best to get through her slave life without trouble.', 21, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b75590-grddrcysIfPx.jpg', NULL, NULL, '佐古真弓', 155, 75590, 'SUPPORTING', 316) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014085', 'AN1558', 'トルケル', 'Thorkell is a Jomsviking general and brother of the Jomsviking Chief. A giant man who loves combat, Thorkell defected from the Danish army to become a mercenary for the English, believing that fighting his fellow Vikings will give him a better challenge. This same love of war leads him to support Prince Canute''s bid for kingship of the Danes. Before Thors'' defection he works with and highly respects the man, and bears a fondness for his son Thorfinn in the main plot. He duels twice with Thorfinn', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b17440-XvYe5JY862ZT.png', NULL, NULL, '大塚明夫', 230, 17440, 'SUPPORTING', 3850) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014086', 'AN1558', 'アシェラッド', 'Askeladd is the commander of a small but powerful Viking band, which owed its success to Askeladd''s exceptional intelligence. Ten years before the main Vinland Saga storyline, Askeladd accepted a contract to assassinate Thors, father of Thorfinn. During the Viking invasion and war in England, he manipulated Thorfinn''s desire for revenge against him as a way of keeping the gifted young fighter in his service. Askeladd is one of the most skilled fighters in the series, and is particularly adept at', 33, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b13020-ZdiYlNmpRUNS.png', NULL, NULL, '内田直哉', NULL, 13020, 'SUPPORTING', 16760) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014087', 'AN1558', 'ハラルド', 'Eldest son of King Sweyn and brother to Canute and Estrid.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300484-gNsRJaQYvtj0.jpg', NULL, NULL, '佐藤拓也', NULL, 300484, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
