INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014090', 'AN1558', 'ユルヴァ', 'She is Thorfinn''s older sister. After Thorfinn has set on a journey to avenge his father, Thors, she takes care of household and her mother.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b27876-Oji0y5oi88oc.jpg', NULL, NULL, '生天目仁美', NULL, 27876, 'SUPPORTING', 415) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014091', 'AN1558', 'クヌート', 'Birthyear: 996  Canute is the prince of the Danes. He is initially portrayed as timid and womanly, with a bishounen appearance and inability to function without his retainer Ragnar. These traits, along with his strong Christianity, earn him the mockery of the Vikings with whom he works.', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b17438-NwyOSMxycmck.png', '7月12日', NULL, '小野賢章', 170, 17438, 'SUPPORTING', 2972) ON CONFLICT DO NOTHING;
