INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014095', 'AN1558', 'ビョルン', 'Bjorn is Askeladd''s second in command, a burly man who fights for the love of combat. He is a berserker, able to enter powerful rages through the consumption of certain mushrooms.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b19485-GqL2A0NKp3Tf.png', NULL, NULL, '安元洋貴', NULL, 19485, 'SUPPORTING', 436) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014096', 'AN1558', 'トールズ・スノーレソン', 'Thors is the father of Thorfinn, a Jomsviking general whose phenomenal combat prowess earns him the epithet &quot;The Troll of Jom&quot;. Thors grows weary of battle after the birth of his children, fakes his own death, and retires to become a pacifist farmer.  Thors is largely considered the greatest fighter to appear in the series, having defeated the likes of Askeladd and Thorkell in single combat. Such was his strength that Floki was unwilling to engage him directly, even with an entire squa', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b13021-XJAVDHwMWek2.png', NULL, NULL, '松田健一郎', 180, 13021, 'SUPPORTING', 2414) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014097', 'AN1558', 'ラグナル', 'He is the main adviser for Prince Canute. Ragnar is bald apart from very long, black, curly hair on the sides of his head. He has very thick black eyebrows that lie close to his deepset eyes. His wrinkles are also very deep, especially in his cheeks, just above his thick beard.  (Source: Vinland Saga Wiki)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b82533-EN57FGoTIHn3.png', NULL, NULL, '浦山迅', NULL, 82533, 'SUPPORTING', 65) ON CONFLICT DO NOTHING;
