INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014106', 'AN1559', '相沢智', 'Relatives: <a href="https://anilist.co/character/89509/Akemi-Aizawa">Akemi</a> (Mother), <a href="https://anilist.co/character/89510/Gorou-Aizawa">Gorou</a> (Father)  Tomo is a high school student with a tomboyish personality, exceptional skills in combat sports, and an earnest desire to win the heart of her childhood friend <a href="https://anilist.co/character/89182/Junichirou-Kubota">Junichiro</a>. Despite her athletic abilities, she is self-conscious about her masculine traits and seeks to b', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/89181-eo1e0troTZz2.jpg', '7月7日', 'B', '高橋李依', NULL, 89181, 'MAIN', 1914) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014107', 'AN1559', '群堂みすず', 'Relatives: <a href="https://anilist.co/character/187792/Misaki-Gundou">Misaki</a> (Mother)  Misuzu Gundou is the tritagonist of Tomo-chan wa Onnanoko!. She is <a href="https://anilist.co/character/89181/Tomo-Aizawa">Tomo</a> and <a href="https://anilist.co/character/89182/Junichirou-Kubota">Jun</a>''s childhood friend and classmate. She is cunning and sometimes sadistic, often teasing Jun. However, she is also protective of her friend and dislikes the idea of Tomo and Jun progressing their relati', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89183-7rdNPxR2afjA.png', '2月22日', 'AB', '日高里菜', NULL, 89183, 'MAIN', 2781) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014108', 'AN1559', 'キャロル・オールストン', 'Relatives: <a href="https://anilist.co/character/187795/Ferris-Olston">Ferris</a> (Mother), <a href="https://anilist.co/character/89511/Kousuke-Misaki">Kousuke</a> (Distant Cousin)  Carol is a classmate and friend of <a href="https://anilist.co/character/89181/Tomo-Aizawa">Tomo</a>, <a href="https://anilist.co/character/89182/Junichirou-Kubota">Jun</a> and <a href="https://anilist.co/character/89183/Misuzu-Gundou">Misuzu</a>. A beautiful, doll-faced student of British origin with no filter betwe', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n89512-Uxe3M5okQXG7.png', '3月8日', 'O', '天城サリー', NULL, 89512, 'MAIN', 1022) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014109', 'AN1559', '久保田淳一郎', 'Junichirou Kubota is the deuteragonist of Tomo-chan wa Onnanoko!. He is <a href="https://anilist.co/character/89181/Tomo-Aizawa">Tomo</a>''s neighbor, childhood friend, fellow dojo pupil and high school classmate. He is handsome but unaware of Tomo''s affections towards him. He regularly trains with Tomo''s father''s dojo and feels jealous when she gives attention to other guys.  <div rel="spoiler">He does not get along with <a href="https://anilist.co/character/89183/Misuzu-Gundou">Misuzu</a>, havi', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89182-BHYMfg00RGvr.png', '10月31日', 'A', '石川界人', NULL, 89182, 'MAIN', 452) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014110', 'AN1559', '三船直子', 'Mifune starts off as not the nicest person along with her best friend Ogawa, she tried to pick a fight with Tomo Aizawa, which was a bad idea. But since it was a misunderstanding they have since become somewhat friends.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b187798-WAZETCQT83z4.jpg', NULL, NULL, '大地葉', NULL, 187798, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
