INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014112', 'AN1559', 'フェリス・オルストン', 'She is Carol''s mother and wife of Eddie Olston. Ferris is as bubble-headed and airy like her daughter. She even got lost from the front gate of her house trying to get back to the house. She worked at her mother''s café in Britain as a waitress and met Eddie when she was only thirteen.', 28, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b187795-9FDPIzcFgCRV.jpg', NULL, NULL, '大原さやか', NULL, 187795, 'SUPPORTING', 52) ON CONFLICT DO NOTHING;
