INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014121', 'AN1561', '場地圭介', 'Captain of the 1st division and one of the founders of the Tokyo Manji Gang.  Baji has a wild personality. He loves the thrill of adrenaline and Mikey himself says that he would punch someone out on the street for no apparent reason, only because he feels like it. In combat, he is never without his trademark grin.', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145343-vRrkdWEUXwYM.jpg', '11月3日', 'AB', '水中雅章', 175, 145343, 'SUPPORTING', 4427) ON CONFLICT DO NOTHING;
