INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014128', 'AN1561', '黒川イザナ', 'Due to his years alone, Izana became ruthless and cruel. Not only has he become mentally unstable but, he strives for absolute power. Izana is the former leader of the eighth generation Black Dragons as well as the former president of Tenjiku. He is one of the main antagonists of The Tenjiku Arc.', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b170484-HZEUSM7UrtKN.jpg', '8月30日', NULL, '島﨑信長', 165, 170484, 'SUPPORTING', 887) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014129', 'AN1561', '稀咲鉄太', 'Kisaki is the principal antagonist of Tokyo Revengers. He''s especially known for rising to the top of the Toman at full speed.   Kisaki is a ruthless, cunning, and ambitious individual who will stop at nothing to achieve his goals. Although average in stature, his power to rule with fear makes even those stronger than he obey him. The entirety of his actions in the entire story revolves around becoming the most powerful and influential criminal in Tokyo.', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b170483-mXcSRDNqVwCP.png', '1月20日', 'A', '森久保祥太郎', NULL, 170483, 'SUPPORTING', 278) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014130', 'AN1561', '羽宮一虎', 'One of the founders of the Tokyo Manji Gang and former number 3 of Valhalla.  Kazutora is a very broken soul; as a child, he was forced to pick between his mom and dad in a case of domestic violence. As a result of his fundamentally non-existent family life, he scorned upon other happy families. Something as simple as seeing children having tender moments with their parents, triggered a sore spot within Kazutora and irritated him deeply.', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b167846-k6G44c97MOug.jpg', '9月16日', 'AB', '土岐隼一', 174, 167846, 'SUPPORTING', 1826) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014131', 'AN1561', '乾赤音', 'Inupi''s elder sister.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b171919-tB9sI1y9xHXx.png', NULL, NULL, NULL, NULL, 171919, 'SUPPORTING', 39) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014132', 'AN1561', '柴大寿', 'The Black Dragon''s 10th leader and Hakkai''s and Yuzuha''s elder brother.  Taiju is brutal and abusive. He enjoys tormenting his opponents and has little care for others'' wellbeing, even his own siblings''. He doesn''t care who his opponent is regardless of gender. He is Catholic and has a cross tattooed on his back.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b167845-ltNMfgsTIeBV.jpg', '7月24日', NULL, '杉田智和', 198, 167845, 'SUPPORTING', 313) ON CONFLICT DO NOTHING;
