INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014134', 'AN1562', '教育の大樹エニユニエン', 'Species: Spirit Occupation: Teacher  The spirit born from the rumors and lore of the "Great Tree of Education" and acts as the spirit school itself. Eniyunien is a tree so high that there''s no end in sight, it breaks through the clouds and looks like it will pierce the heavens. Inside of Eniyunien, there are classrooms that he can use to teach his students.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b297194-NijnqobUKEwc.jpg', NULL, NULL, '麦人', NULL, 297194, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
