INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014154', 'AN1563', '来栖一騎', 'Instagram  Kazuki lives with his colleague and buddy Rei, who also looks after his personal needs. Contracting, gathering information in advance, and making execution plans are the main areas of work with Rei. He likes women and gambling and he has good communication skills. He is skilled at cooking and cleaning, and he occasionally chastises Rei for his indulgent lifestyle.   He was previously married and had a wife who was pregnant with his child, but he lost her due to his shady work.', 28, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289968-j2C0sN9C5mwg.png', '5月16日', NULL, '豊永利行', NULL, 289968, 'MAIN', 805) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014155', 'AN1563', '諏訪零', 'Rei is a man of few words who doesn''t mind that Kazuki has already moved into his house. He is physically strong, and his fighting abilities and marksmanship are among the best in the industry. He has a clear separation between his professional and personal lives and spends most of his time at home playing video games. His family is a large underworld family, and his parents have been training him as a gifted assassin since he was a child.   He has not been able to escape the family feud and has', 25, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289969-u5TaqUPu78Ka.png', '8月10日', NULL, '内山昂輝', NULL, 289969, 'MAIN', 1387) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014156', 'AN1563', '海坂ミリ', 'Miri is an innocent girl who is just as energetic and fearless. Her father is a mafia boss and a major broker for a human trafficking organization. Her mother is the mistress of the boss. When she arrives at the hotel in search of her father, she becomes involved in a gunfight and is rescued by Kazuki. She is friendly and refers to Kazuki as "Papa Kazuki" and Rei as "Papa Rei".', 4, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289970-yEN4aVIRcHN8.png', '11月8日', NULL, '木野日菜', NULL, 289970, 'MAIN', 522) ON CONFLICT DO NOTHING;
