INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014188', 'AN1565', 'エドガー', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b296965-HIMUFjIQwWrV.jpg', NULL, NULL, '石井康嗣', NULL, 296965, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014189', 'AN1567', '福沢諭吉', 'The president of the Armed Detective Agency, who manages the hooligans. Although he doesn''t often come out, at a critical moment, he triumphantly takes command. Because Yukichi is a man of dignity and status, it seems even the frivolous Ranpo will actually work if he orders it.  (Source: Bungou Stray Dogs wiki)', 45, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89196-E2tIf6nIPKnW.png', '1月10日', 'B', '小山力也', 186, 89196, 'MAIN', 990) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014190', 'AN1567', '中島敦', 'Ability: Beast Beneath the Moonlight  He came to Yokohama after being driven out of a poor orphanage that was attacked by a man-eating tiger. On the verge of starvation, he meets Dazai and gets a job helping at the detective agency. Because he''s never had friends or family and was labeled as "useless," he lacks self-confidence.', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89197-vB5kP72ruckV.png', '5月5日', 'AB', '上村祐翔', 170, 89197, 'MAIN', 3938) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014191', 'AN1567', '江戸川乱歩', 'The great detective of the Armed Detective Agency. He possesses sharp observation skills that are acknowledged by his coworkers, and he settles difficult cases at the request of the police. Because of his self-confidence, his speech is brazen and child-like. His motto is "If you''ll have me, everything will be ok!" He likes logical thinking and fantastic tales.', 26, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89201-K0X5HNq88Oub.png', '10月21日', 'O', '神谷浩史', 168, 89201, 'MAIN', 7790) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014192', 'AN1567', '太宰治', 'Ability: No Longer Human  A member of the Armed Detective Agency. He''s a suicide enthusiast who searches for a place to die. However, he doesn''t like pain, and would prefer a lovers'' suicide with a beautiful woman. He''s aimless, elusive, nonchalant, and jokes around normally, but, when he is serious, it is clear that he is an insightful and intelligent individual. He loves to annoy his fellow Agency member, Kunikida.', 22, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89198-qKmRTw4Y3PRC.png', '6月19日', NULL, '宮野真守', 181, 89198, 'SUPPORTING', 17655) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014193', 'AN1567', 'ニコライ・ゴーゴリ', 'Ability: The Overcoat  Nikolai Gogol is a member of the Decay of Angels. He''s a sadist who enjoys putting on a show with his words. He is freakish, vigorous, unrepentant, and quite enigmatic. However, Gogol suggests that his quirky image could or might not be real. The side of him that has no remorse for murdering others is just as genuine as the one who has guilt and is well aware of the unjust and cruel nature of his acts. He joined the Decay of Angels in order to experience what he had always', 26, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151368-Pvo5eichYNNn.png', '4月1日', NULL, '子安武人', 184, 151368, 'SUPPORTING', 909) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014194', 'AN1567', 'エドガー・アラン・ポオ', 'Ability: Black Cat in the Rue Morgue  A member of The Guild who is rarely seen without his pet raccoon, Karl. Poe''s ability, Black Cat in the Rue Morgue, can transport someone into a story they''re reading. Poe is portrayed as shy but determined. He spent six years on a plot to defeat Ranpo, showing that he will work hard at something he cares about. He often talks too quietly for others to hear.', 28, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127632-Y5Ega9Pvu0OA.jpg', '1月19日', 'AB', '森川智之', 182, 127632, 'SUPPORTING', 984) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014195', 'AN1567', '坂口安吾', 'Ability: Discourse on Decadence   Port Mafia''s former exclusive informant. Works as an assistant counselor at the Special Ability Department at the Ministry of Internal Affairs.  For the most part, Ango is a composed, calm young man, showing more restraint than Osamu Dazai and more discipline than Oda Sakunosuke. Although he values both as genuine friends, he strongly believes that Dazai needs someone to keep him from acting out as much as he does.', 25, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134500-I4bkRhZRWfVs.png', '10月20日', NULL, '福山潤', 178, 134500, 'SUPPORTING', 268) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014196', 'AN1567', '小栗虫太郎', 'A member of the "Rats in the House of the Dead". His ability is "The Perfect Crime."', 26, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b173343-BlouLRHSWkLf.png', '3月14日', 'A', '草尾毅', NULL, 173343, 'SUPPORTING', 129) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014197', 'AN1567', '立原道造', 'Ability: Midwinter Memento  A commander of the Black Lizards, the Port Mafia''s squad of hitmen. Though he puts up a tough and violent front, he cares deeply for his friends. Very skilled gunner, especially when dual wielding.', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136705-qd9sowaD7SKW.png', '7月30日', NULL, '林勇', 176, 136705, 'SUPPORTING', 515) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014198', 'AN1567', '村上時雄', 'The lead actor of the play *The Living World Is a Dream, the Nocturnal Dream is Reality* performed at Theatrum Mundi.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b297027-JUzdhblQ4YJ2.png', NULL, NULL, '下野紘', NULL, 297027, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014199', 'AN1567', '種田山頭火', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138155-AsgzC2ePyhCL.jpg', NULL, NULL, '立木文彦', NULL, 138155, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014200', 'AN1567', '中原中也', 'Chuuya is a Port Mafia member who detests Osamu Dazai for betraying the mafia and joining the Armed Detective Agency. He''s also constantly teased by Dazai what makes him hate Dazai even more. Chuuya is short but he''s quick and uses powerful martial arts.   His ability, "For The Tainted Sorrow," revolves around gravity manipulation, allowing him to manipulate and alter the gravity of anything he touches, keeping it that way until a certain period of time.', 22, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89853-06qMPkrGlgP1.png', '4月29日', 'B', '谷山紀章', 160, 89853, 'SUPPORTING', 7487) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014201', 'AN1567', 'フョードル・ドストエフスキー', 'Ability: Crime and Punishment  Head of the underground organization "Rats in the House of the Dead" and part of the terrorist organization "Decay of Angels". He maintains a calm, confident, and arrogant yet polite personality towards others and has shown to be extremely intelligent, cunning, and sinister. He is highly religious and speaks often of the sin of man, especially ability users. According to him, he is anemic.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b138067-oHmQo5cOSZMN.png', '11月11日', NULL, '石田彰', NULL, 138067, 'SUPPORTING', 2152) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014202', 'AN1567', 'シグマ', 'Sigma is a member of the terrorist organization, "Decay of Angels", and owner of the Sky Casino.  His ability is unknown, but stated by Fyodor to be the weakest of the Angels. It may be more support-oriented than combat-oriented because of this.  He is shown to be very kind to his customers and to have a sense of pride and ownership over his casino.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b138815-Vl5pAb5Ox9aG.jpg', NULL, NULL, '千葉翔也', NULL, 138815, 'SUPPORTING', 818) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014203', 'AN1567', '夏目漱石', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b198706-V9zFlhsG65wp.png', NULL, NULL, '大塚芳忠', NULL, 198706, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014204', 'AN1567', 'ナサニエル・ホーソーン', 'Likes: God, the Bible, faith, purity Dislikes: The Devil, heresy Ability: The Scarlet Letter  He has the ability to convert his own blood into holy words and control them.', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/121165-cfbOLzjZ8PVU.jpg', '7月4日', 'A', '新垣樽助', 188, 121165, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014205', 'AN1567', '泉鏡花', 'A docile young lady who dresses in a kimono, but also a member of Port Mafia. As she holds a killing ability, she was found by the organization and raised as an assassin.', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89856-GB3SOKXTBnrX.jpg', '11月4日', 'B', '諸星すみれ', 148, 89856, 'SUPPORTING', 2092) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014206', 'AN1567', '国木田独歩', 'Ability: The Matchless Poet  A member of the Armed Detective Agency. He carries a notepad with the word "Ideal" written on the cover, and what is written inside are guides for life. He has a straight-laced personality and hates nothing more than schedules going awry. As a partner to the free-spirited Dazai, his troubles never end.', 22, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89200-mZJo7iEwJGzg.png', '8月30日', 'A', '細谷佳正', 189, 89200, 'SUPPORTING', 1995) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014207', 'AN1567', '織田作之助', 'Ability: Flawless  Was a member of the Port Mafia. Oda was a man described as kind, despite working for the mafia, by Dazai. He had an incredibly perceptive side to him that allowed him to come the closest to understanding Dazai, whom he referred to as "his dear friend, who had grown tired of the world and is simply waiting to die."', 23, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b120625-i2xfexhHTwMQ.png', '10月26日', NULL, '上村祐翔', 185, 120625, 'SUPPORTING', 2082) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014208', 'AN1567', '箕浦', 'Member of the Japanese Police Force. Successor of Yasui-san whom Ranpo had worked with previously on cases.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138152-nVRl3fXOukFw.jpg', NULL, NULL, '白熊寛嗣', NULL, 138152, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014209', 'AN1567', '福地桜痴', 'Oochi Fukuchi is the commander of the Hunting Dogs special units and has the ability Mirror Lion.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b189364-w4COyMG4mMMB.png', '5月13日', NULL, '大塚明夫', NULL, 189364, 'SUPPORTING', 119) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014210', 'AN1567', '森鷗外', 'Ability: Vita Sexualis  Ougai Mori is the boss of the Port Mafia. Ougai is analytical and tactical. He often puts on overdramatic acts but rarely breaks his composure internally.   He has been shown to be somewhat ruthless and unfaltering when it comes to violence. He hasn''t, however, shown any particular enjoyment from killing. His ruthlessness comes from his pragmaticism.  Although he can be intimidating at times and emit a scary formal aura, he is often polite to the point of seeming approach', 40, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121168-XkWaYGESyQpZ.png', '2月17日', 'O', '宮本充', 175, 121168, 'SUPPORTING', 597) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014211', 'AN1567', 'カルル', 'Edgar Allan Poe''s pet raccoon.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191682-bKhkDRCxpk2C.jpg', NULL, NULL, NULL, NULL, 191682, 'SUPPORTING', 190) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014212', 'AN1567', '大倉燁子', 'Teruko is vice-commander of the Hunting Dogs special units and has the ability "Gasp of the Soul".', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b167899-E7SJCub2PpTD.png', NULL, NULL, '小市眞琴', NULL, 167899, 'SUPPORTING', 113) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014213', 'AN1567', '谷崎潤一郎', 'Ability: Light Snow  He is a member of the Armed Detective Agency and the older brother of Naomi.', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89205-69AfPXd4QmX3.png', '7月24日', 'A', '豊永利行', 174, 89205, 'SUPPORTING', 736) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014214', 'AN1567', 'エリス', 'Member of Port Mafia, a young girl usually seen with Ougai Mori.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138063-oT7IVCxhKidq.jpg', NULL, NULL, '雨宮天', NULL, 138063, 'SUPPORTING', 71) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014215', 'AN1567', 'ルイーザ・メイ・オルコット', 'Ability: Little Women  The Strategist for The Guild. Her ability allows her to slow down time to 1/8000th of regular speed, however it only works when she is alone in her private room.', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b138062-e8P9Bn7eMa32.jpg', '11月29日', 'O', '植田ひかる', 165, 138062, 'SUPPORTING', 49) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014216', 'AN1567', '末広鉄腸', 'Ability: Plum Blossoms in Snow  Tecchou Suehiro is a Hunting Dogs special unit member with the ability Plum Blossoms in Snow. Tecchou has a considerably more serious demeanor than his companions, yet he still qualifies as an oddball for his strange preferences in food. He takes his duty as a Hunting Dog earnestly and has a deep sense of justice. He despises the notion of torture and is a highly compassionate person.  Tecchou''s ability, Plum Blossoms in Snow, lets him enhance the size, shape, and', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163186-tDRfnLb1YGkH.png', '3月15日', NULL, '阿座上洋平', NULL, 163186, 'SUPPORTING', 510) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014217', 'AN1567', '宮沢賢治', 'Ability: Undefeated by the Rain  A member of the Armed Detective Agency. Before he was scouted, he lived in a rural area without electricity. He knows no suspicion, and will be understanding and considerate no matter who he is talking to. He has a lot of friends who call him "Ken-chan." He likes music, tempura soba, and Mitsuya cider.  (Source: Bungou Stray Dogs Wikia)', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89207-i7pw9zNQqXpZ.png', '8月27日', 'O', '花倉洸幸', 158, 89207, 'SUPPORTING', 1013) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014218', 'AN1567', 'フランシス・スコット・キー・フィッツジェラルド', 'Ability: The Great Fitzgerald  Francis poses as the leader for an american secret society, ''''The Guild''''. Said organization is composed by rich and notorious individuals, who all have some type of powerful influence in the USA. His ability, ''''The Great Fitzgerald'''', allows him to power up his own atributes and traits, according to the money he spent from his countless fortune. A fierce man, who loves his family, and would do pretty much anything to achieve his goals.', 32, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121164-JI5C2eMIQrSG.png', '9月24日', 'O', '櫻井孝宏', 191, 121164, 'SUPPORTING', 327) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014219', 'AN1567', '芥川銀', 'Ryuunosuke''s younger sister and a member of the "Black Lizards" Assault Unit. It seems she is in good terms with Dazai.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b137512-5mJhKeyVdMB5.jpg', '2月4日', NULL, '夏川椎菜', NULL, 137512, 'SUPPORTING', 877) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014220', 'AN1567', '条野採菊', 'Saigiku Jouno is a member of the Hunting Dogs. He possesses the ability "Priceless Tears".', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163187-9qxQQzzWQrMR.png', '9月24日', NULL, '梶裕貴', NULL, 163187, 'SUPPORTING', 312) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014221', 'AN1567', '与謝野晶子', 'Ability: Thou Shalt Not Die  A modern woman with a bob cut who''s a member of the Armed Detective Agency. Although she''s an excellent doctor who is indispensable to the Agency, all members of the the Agency are scared to be placed into her care. It''s recommended that you don''t use outdated misogynistic expressions in front of her.', 25, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89208-Zjsz22lCmrIE.png', '12月7日', 'O', '嶋村侑', 166, 89208, 'SUPPORTING', 2548) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014222', 'AN1567', 'ルーシー・モード・モンゴメリ', 'A member of Ability User Society "Fellowship of The Guild."   Her ability is known as "Anne of Abyssal Red".', 19, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132222-Ue3zZMq9aqMg.jpg', '11月30日', 'AB', '花澤香菜', 165, 132222, 'SUPPORTING', 2930) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014223', 'AN1567', '広津柳浪', 'Ability: Falling Camellia  Member of Port Mafia, "Black Lizards" Assault Unit Captain. His ability, Falling Camellia, cause things that he touches to fly backward with immense force.', 50, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b138066-0cF5m4qGEOpY.jpg', '7月15日', 'A', '斧アツシ', 178, 138066, 'SUPPORTING', 76) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014224', 'AN1568', '長瀞早瀬', 'A high school student that can suddenly pop-up anywhere and anytime. She is always crazy about her Senpai. She seems to be a member of the Swimming Club. Nagatoro is an energetic, athletic, popular and rather sadistic - but deep down very sweet - girl, often referred to as a "sadodere". She is part of a ''cool kids'' clique together with her friends Gamo-chan, Yoshi and Sakura, and is a member of the swimming club, despite also having a liking for martial arts such as muay thai, boxing, capoeira a', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b124696-du2Kszxelh1S.png', '4月1日', NULL, '上坂すみれ', 150, 124696, 'MAIN', 5332) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014225', 'AN1568', '八王子直人', 'As a high schooler and a member of the art club, he enjoys illustrating his own mangas and drawing still images of even his kouhai, Nagatoro, after meeting her. Naoto spends his time after school in the art club with Nagatoro on most days where the crazy antics ensue. He is an introvert, twitchy, loner, nerdy and shy aspiring artist, who tries to avoid social interaction with other people and doesn''t seem to have any friends. He is also referred as closet-perv by Nagatoro.', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b124697-JDDbhuzV6HXN.jpg', '5月10日', NULL, '山下大輝', 176, 124697, 'MAIN', 957) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014226', 'AN1568', '折原', 'An Olympic team candidate for the Judo team, Orihara is Nagatoro''s rival in Judo, originally being talentless.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220340-KuxjDus3PHR2.png', NULL, NULL, '前田佳織里', NULL, 220340, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014227', 'AN1568', '日野', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b326545-9P0MtAk9vf5R.png', NULL, NULL, '天崎滉平', NULL, 326545, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014228', 'AN1568', '八王子', 'She is the mother of Senpai, a caring woman who love her son very much but is often away from home due to her very demanding job.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b222438-KbXmYcLGFdLC.png', NULL, NULL, '小島幸子', NULL, 222438, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014229', 'AN1568', '会長', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b326546-9gUtCVDSzMTp.png', NULL, NULL, '石谷春貴', NULL, 326546, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014230', 'AN1568', '須ノ宮さな', 'The art club president. She has long hair that frames her face with dark-brown eyes. Her personality is stern and serious based on her interactions with Senpai, but she treats him with respect unlike Nagatoro. She also bears a resemblance to a female character in one of the manga Senpai wrote.   Sunomiya is her younger cousin.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145717-xWPkoY8gFYuy.jpg', '6月19日', NULL, '水樹奈々', 171, 145717, 'SUPPORTING', 541) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014231', 'AN1568', 'ネコバ', 'She is a high school student and a classmate of Gamo-chan, Yoshi, Nagatoro and Sakura, the latter two of whom she and her friend Rabi-chan seem to be pretty in confidence to, although they later started to occasionally hang out with the rest of the group as well.  Her full name is currently unknown', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b222436-14qpz9JBPiIL.png', NULL, NULL, '若山詩音', NULL, 222436, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014232', 'AN1568', 'ヨッシー', 'A natural airheaded twintail girl. She is a moron who likes Gamo-chan as she usually repeats or follows her up with something she has just said. Yoshi also seems to like animals as she’s been seen with a gorilla shirt and she has a pet dog. She also seems to be into cute things as she once accepted a “Squiddy” plush from Nagatoro in return for Senpai in a contest.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145718-IKqQxlLIoohE.jpg', '11月23日', NULL, '鈴木愛奈', 160, 145718, 'SUPPORTING', 465) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014233', 'AN1568', '蒲生', 'A character with semi-long hair. She likes to make fun of people.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145715-G5GLMaYmUHyo.jpg', '6月15日', NULL, '小松未可子', 168, 145715, 'SUPPORTING', 491) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014234', 'AN1568', '桜', 'A girl with a tan and soft wavy hair. She actually has a "haraguro" personality.  (Haraguro: a character that is kind or friendly on the outside but uses those traits as a means to manipulate others.)', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145716-HQmY6lFKez9s.jpg', '9月4日', NULL, '井澤詩織', 157, 145716, 'SUPPORTING', 331) ON CONFLICT DO NOTHING;
