INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014238', 'AN1568', '須ノ宮 ハナ', 'She is a high school student who joined the art club during Senpai''s third year as well as an acquaintance of his since middle school and the younger cousin of the former Art Club President, with whom she shares a striking physical resemblance and habit of public nudity. She is a kouhai to all of the other characters.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226964-Wgrua42oV3UA.png', NULL, NULL, '鈴代紗弓', NULL, 226964, 'SUPPORTING', 137) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014239', 'AN1568', '高尾', 'Takao is a high school student as well as a schoolmate and friend of Senpai, with whom he formed a trio alongside Hino. As the story progress - albeit not as consistently as Senpai - he began to occasionally hang-out with Nagatoro''s clique, especially Sakura.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b326544-JRoDEtgTsyyi.png', NULL, NULL, '小林裕介', NULL, 326544, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014240', 'AN1569', 'ベル・クラネル', 'Race: Human  Bell Cranel is the captain of the Hestia Familia. Bell was raised by his grandfather in a rural farming village deep within the mountains near the labyrinth city Orario. He had heard and read many stories about heroes from his grandfather, forming his dream of aspiring to be a mighty one himself. After his grandfather''s death, he took it upon himself to leave the village, traveling to the land of Orario to fulfill his dreams. Upon his arrival in the city, Bell attempted to enter num', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88860-catfcwlvUYst.jpg', NULL, NULL, '松岡禎丞', 165, 88860, 'MAIN', 3835) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014241', 'AN1569', 'リリルカ・アーデ', 'Race: Pallum  Liliruca Arde is a member of the Hestia Familia. Originally a member of the Soma Familia, she converted to the Hestia Familia after securing her freedom after the War Game. Lili was born to Hobbit parents belonging to the Soma Familia, making her a member of the Familia from birth. However, her parents didn''t look after her and ordered her to earn money for them instead. A while later, her parents were killed in the dungeon, leaving her to fend for herself. The Soma Familia didn''t ', 15, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b88897-2xey5UG7Qr2S.png', NULL, NULL, '内田真礼', 110, 88897, 'MAIN', 863) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014242', 'AN1569', 'ヴェルフ・クロッゾ', 'Race: Human  Welf Crozzo is a member of the Hestia Familia and Bell''s personal blacksmith, later becoming one for the entire Hestia Familia after converting from the Hephaestus Familia. Welf was originally born in Rakia, a nation type Familia ruled by Ares. As a member of the Crozzo Family, he lived as a noble due to the successes his predecessors had in creating magic swords. However, his life changed the day his Skill Crozzo Blood appeared, which enabled him to create magic swords again. Despi', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b138250-VOIbyr2PNsZS.png', NULL, NULL, '細谷佳正', 175, 138250, 'MAIN', 599) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014243', 'AN1569', 'ヤマト・命', 'Race: Human Affiliation: Hestia Familia • Takemikazuchi Familia (temporary leave) Level: 2 Skills: Yatanokurogarasu • Yatanoshirogarasu Magic: Futsunomitama Weapon: Kotetsu • Chizan • Shunsan • Shakuya  Yamato Mikoto is a member of the Hestia Familia and the Takemikazuchi Familia, having converted to aid the former during the War Game. Mikoto originally hails from the Far East. Her parents died several years after her birth. Tsukuyomi and Takemikazuchi took the young girl into their orphanage, w', 16, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b142923-3DX8e5beuivx.jpg', NULL, NULL, '赤﨑千夏', 157, 142923, 'MAIN', 620) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014244', 'AN1569', 'サンジョウノ・春姫', 'Race: Renard  Sanjouno Haruhime is a member of the Hestia Familia and a former member of the Ishtar Familia. Haruhime grew up as a dignified young lady of a noble family in the Far East. Living in solitude, her home was like a cage and she had no friends. At some point, children of the Takemikazuchi Familia, with the approval of their God, started taking her outside at night to play with them. Sometime later, someone framed her for eating an offering, which angered her father so much that he dis', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b142551-WyUJ6UW2H5UH.png', NULL, NULL, '千菅春香', 156, 142551, 'MAIN', 879) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014245', 'AN1569', 'リュー・リオン', 'Race: Elf  Ryuu Lion is a waitress at the Hostess of Fertility.  Ryuu was a member of a family that cared for the sacred tree in their home forest of Ryumilua. As time passed, she began to think that beautiful Elves were the ugliest of all people, due to seeing her fellow Elves'' behavior toward those of other races. No matter how much she tried to forget it, once she began thinking about it, the thought firmly planted itself in her mind. Eventually, the thought became enough to make her decide t', 21, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88890-lJFKK5czkH9E.jpg', NULL, NULL, '早見沙織', 165, 88890, 'MAIN', 3015) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014246', 'AN1569', 'ヘスティア', 'Race: God Affiliation: Hestia Familia  Hestia is an energetic, kind goddess who sees potential in Bell. She is a hard worker, and works jobs to support the two while Bell goes off to the dungeon. Hestia tends to be shown as very petty and gets jealous easily when girls, namely Aiz, show interest in Bell, because she is deeply in love with him, or they are the reason for his strength growth. Despite seeming mature and dependable toward Bell, Hestia is in truth, a lazy goddess, as she couldn''t get', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b87654-UmmuLPwSK2Hd.jpg', NULL, NULL, '水瀬いのり', 140, 87654, 'SUPPORTING', 3350) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014247', 'AN1569', 'ダフネ・ラウロス', 'Race: HumanHeight: 164 cm (5''5") Affiliation: Miach Familia (past), Apollo Familia (present) Level: 3 Achieved Floor: 27 Status: • Strength: I0 • Endurance: I0 • Dexterity: I0 • Agility: I0 • Magic: I0 • Abnormal Resistance: I • Escape: ? Skills: Elios Passion • Laurus Wreath Magic: Raumure Equipment: Fencer Laureate  Daphne Lauros is a member of the Miach Familia and a former member of the Apollo Familia. Daphne is a calm and collected person despite her looks. She has mixed feelings for Apollo', 18, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b142535-ckQoYFxf01Sv.png', NULL, NULL, '小若和郁那', 164, 142535, 'SUPPORTING', 55) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014248', 'AN1569', 'カシマ・桜花', 'Race: Human Affiliation: Takemikazuchi Familia Level: 2 Weapon: Kougou  Kashima Ouka is a member and captain of the Takemikazuchi Familia. Ouka is a strong and respected member of his familia. Being the leader, he often decides the course of action for his Familia members during dungeon trips. He is capable of instructing his companions and making harsh decisions in desperate situations. Despite his decisions, he shows deep care for his Familia due to them knowing each other from when they were ', 17, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b143055-MbcPKK91Rc4g.jpg', NULL, NULL, '興津和幸', 190, 143055, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014249', 'AN1569', 'ルノア・ファウスト', 'Race: Human  Lunoire Faust is a waitress at the Hostess of Fertility and a former bounty hunter known as Faust as a member of the Demeter Familia. Lunoire was born to parents that lived in a territory of the empire. However, her parents soon died because of a war, and she was forced to live her life as one of the street children. After living for some time in harsh conditions, she heard about the falna and joined a Familia, but later began traveling on her own a while later once her Goddess was ', 22, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b122203-Ghj2Dau1YeHx.jpg', NULL, NULL, '芳野由奈', 161, 122203, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014250', 'AN1569', 'ボールス・エルダー', 'Bors is a well built muscular man with black hair and teal eyes, with an eyepatch covering his left eye. He wears a sleeveless open jacket that shows his muscular body, arm covers and gloves, blue pants, boots, and a belt with a red monster face carving and fur.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b181352-XZJnWwZr0d2i.png', NULL, NULL, '山口太郎', NULL, 181352, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014251', 'AN1569', 'フレイヤ', 'Race: God Affiliation: Freya Familia   Freya Is the head of the Freya Familia. Long ago, Hera, at the request of Zeus, asked Freya for help in their goal to save the world. Freya made her a challenge, telling her that she would help her if she won. Having lost the challenge, Freya was forced to stay in Orario as part of the deal, in addition to losing several members of her Familia as a result. Some time later, Freya met a girl named Syr. After telling her that she would rescue her, Freya asked ', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b142533-8HA0L1bjmF2P.png', NULL, NULL, '石上静香', 170, 142533, 'SUPPORTING', 757) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014252', 'AN1569', 'ヘファイストス', 'Race: God Affiliation: Hephaestus Familia  Hephaestus is the head of the Hephaestus Familia. Hephaestus shows a strict and hardworking nature compared to her friend, Hestia, who was known as the lazy goddess. She is also known to care very much about her children.  As a Goddess of Smithing, Hephaestus is a master at it. She was able to smith the Hestia Knife, a living weapon with Hestia''s falna, even without her arcanum.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b142544-FXiSUaogBQ9l.png', NULL, NULL, '寺崎裕香', 165, 142544, 'SUPPORTING', 198) ON CONFLICT DO NOTHING;
