INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014254', 'AN1569', 'アーニャ・フローメル', 'Race: Cat People Affiliation: Hostess of Fertility Level: 4  Anya Fromel is a waitress at the Hostess of Fertility. When she was one year old, Anya lost her parents and her home. Because of this, her brother Allen was forced to wander the ruins of a kingdom while protecting her. So it was for two years until they met Freya, who offered them to go with her, which they accepted. Sometime before Ais came to Orario, Mia partially left the Freya Familia to open the Hostess of Fertility, employing Any', 22, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b143047-S8aXD2FNKiPW.jpg', NULL, NULL, '西明日香', 150, 143047, 'SUPPORTING', 90) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014255', 'AN1569', 'ウィーネ', 'Race: Xenos  Affiliation: Xenos • Hestia Familia • Ouranos Level: 2+ (estimate)  Wiene is a mysterious female Vouivre born in the middle floors of the Dungeon. It is later revealed that she is one of the Xenos.   Wiene has the ability to speak even though she is a monster due to her being a Xenos. She is kind, helping a young boy even though people regarded monsters as evil. Wiene grew attached to the Hestia Familia, particularly Bell and Haruhime. Wiene doesn''t like to wear clothes, as she refu', 0, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b146907-h9FMMvnMsv4C.png', NULL, NULL, '日高里菜', 150, 146907, 'SUPPORTING', 469) ON CONFLICT DO NOTHING;
