INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014259', 'AN1569', 'フィア', 'Race: XenosHeight: 158 cm (5''2") Affiliation: Xenos • Ouranos  Fear is a Harpy Xenos. As a Xenos, Fear is far more intelligent and powerful than a normal monster.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b209700-Yi8KTMQnSIqW.png', NULL, NULL, '石見舞菜香', 158, 209700, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
