INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014262', 'AN1569', 'ウラノス', 'Race: God Affiliation: Guild • Xenos  Uranos is the head of the Guild. Uranos follows the philosophy of ruling but not governing, leaving the matters of the Guild to Royman Mardeel, while he himself stays in the Room of Prayer under the Guild to use his divinity to keep monsters from coming out of the dungeon. He is quite stoic, having patiently watched over the dungeon for 1000 years, and is open to new ideas, being the first to believe that the Xenos could peacefully coexist with the people on', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n134228-7ZVG2R9j4Fgb.jpg', NULL, NULL, '大川透', 210, 134228, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014263', 'AN1569', 'ラウラ', 'Race: Xenos Affiliation: Xenos • Ouranos  Laura is a Lamia Xenos. As a Xenos, Laura is far more intelligent and powerful than a normal monster. Laura has light blue scaly skin, claws and a long serpentine tail.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b209695-apNG9lgs87RD.png', NULL, NULL, '浜崎奈々', NULL, 209695, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014264', 'AN1569', 'ミアハ', 'Race: God Affiliation: Miach Familia  Miach is the head of the Miach Familia. Miach is a kind, compassionate, and friendly God, and has good relations with Bell and the members of the Hestia Familia, often handing out free potions to him. He has a habit of handing out free potions, causing financial problems for his Familia, and is referred to as a "natural gigolo" along with Takemikazuchi due to his friendliness toward women. He is also caring of his own Familia member Naaza Erisuis, taking out', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b142549-LwLWawgPSvQt.jpg', NULL, NULL, '古川慎', 188, 142549, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014265', 'AN1569', 'アストレア', 'Race: God Affiliation: Astraea Familia', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b288476-88xXlCWp09Tk.png', NULL, NULL, '中原麻衣', NULL, 288476, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014266', 'AN1569', 'ナァーザ・エリスイス', 'Race: ChienthropeHeight: 169 cm (5''7") Affiliation: Miach Familia Level: 2 Status: • Strength: G218 • Endurance: G204 • Dexterity: G293 • Agility: F339 • Magic: H187 • Mixing: I Magic: Darbh Daol  Naaza Erisuis Is a doctor in the Miach Familia. Naaza has good relations with Bell Cranel just like Miach and Hestia. However, due to her Familia being poor, she sold Bell inferior items and talked him into buying high priced goods. Naaza still will help Bell when he needs it, such as when she helped h', 18, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b142546-s1YcokJOyhAC.png', NULL, NULL, '葉山いくみ', 169, 142546, 'SUPPORTING', 67) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014267', 'AN1569', 'リド', 'Race: XenosHeight: 167 cm (5''6") Affiliation: Xenos • Ouranos Level: 5 (estimate)  Lyd is a Lizardman Xenos. As a Xenos, Lyd is far more intelligent and powerful than a normal monster. He is one of the strongest Xenos, being on par with a first class adventurer. Lyd has red scales and orange eyes. He wears a full set of armor, wields a scimitar and a longsword.  Lyd is an openhearted and friendly individual, quickly warming up to Bell, who he met for the first time, even giving him a nickname. A', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b192620-B1pDjJekHWFe.png', NULL, NULL, '水中雅章', 167, 192620, 'SUPPORTING', 46) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014268', 'AN1569', 'タケミカヅチ', 'Race: God Affiliation: Takemikazuchi Familia    Takemikazuchi is a God and the head of the Takemikazuchi Familia. Takemikazuchi is friendly with Hestia and has taught her many things such as the dogeza. He is kind to his Familia members. He is also a natural gigolo, and is clueless to how his actions affect others around him, which makes him come out as insensitive.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b142543-VIdHpFy6EIRO.png', NULL, NULL, '間島淳司', 176, 142543, 'SUPPORTING', 42) ON CONFLICT DO NOTHING;
