INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014270', 'AN1569', 'フェルズ', 'Affiliation: Ouranos • Xenos Previous Affiliation: Altena Level: 4 Status:  • Mage: ? • Mystery: ? Magic: Dia Panakeia • Dia Orpheus  Fels is a mysterious mage that is affiliated with Ouranos. Fels works directly under Ouranos and will take any orders from him, although they will act on their own if necessary. They consider their experience creating the stone that granted immortality as their trauma.', 800, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b183121-KNCyPqTJd04Y.png', NULL, NULL, '小松未可子', NULL, 183121, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
