INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014274', 'AN1569', '椿・コルブランド', 'Race: Half DwarfHeight: 170 cm (5''7") Affiliation: Hephaestus Familia Level: 5 Achieved Floor: 59 Status: • Blacksmith: ?  Tsubaki Collbrande is the captain of the Hephaestus Familia as well as a master smith. Tsubaki has a very friendly personality, casually interacting with various people, and even asked Finn if she could hug him. Tsubaki is interested in Welf Crozzo and takes care of him, nevertheless, she laments the fact that he refuses to make magic swords, stating that it''s a waste of tal', 38, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b159917-NthMmMeI9Swd.png', NULL, NULL, '生天目仁美', 170, 159917, 'SUPPORTING', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014275', 'AN1569', 'グロス', 'Race: Xenos Affiliation: Xenos • Ouranos Level: 5 (estimate)  Gros is a Gargoyle Xenos. As a Xenos, Gros is far more intelligent and powerful than a normal monster. He is one of the strongest Xenos, being on par with a first class adventurer. Gros has red eyes and a pair of wings. His body is made of ash-colored stone.  Gros is a no-nonsense and stubborn individual. As one of the three leaders of the Xenos, he cares deeply for his kind and will do whatever it takes to protect them. He holds the ', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208893-hQGDjpvcK3AW.jpg', NULL, NULL, '稲田徹', NULL, 208893, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014276', 'AN1569', 'エイナ・チュール', 'Race: Half Elf Affiliation: Guild  Eina Tulle is a receptionist at the Guild and Bell Cranel''s advisor. Eina joined the Guild five years earlier at the age of 14 after she graduated from the school. Originally excited to work at the Guild, she quickly learned that it wasn''t as fun as she thought it would be, eventually changing her personality into what it is now. She met Bell four years later and became his dungeon adviser.   Eina shows a serious, calm demeanor, appearing as a very wise and sis', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/88896-zhwTEI30T5XB.jpg', NULL, NULL, '戸松遥', 164, 88896, 'SUPPORTING', 372) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014277', 'AN1569', 'ヒタチ・千草', 'Race: Human Affiliation: Takemikazuchi Familia Level: 2  Chigusa Hitachi is a member of the Takemikazuchi Familia. Despite having a timid and shy personality, she is loyal to her Familia, especially Ouka who she has feelings for.', 16, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b142553-qRChPxIz6UUr.jpg', NULL, NULL, '井口裕香', 154, 142553, 'SUPPORTING', 45) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014278', 'AN1569', 'アイズ・ヴァレンシュタイン', 'Ais Wallenstein, also known as the Sword Princess, is a First-Class Adventurer and a key member of the Loki Familia. Among the small fraction of First-Class Adventurers, she is considered one of the strongest.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b87655-7QjpIyyZuqyp.png', NULL, NULL, '大西沙織', 162, 87655, 'SUPPORTING', 5651) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014279', 'AN1569', 'レット', 'Race: Xenos Affiliation: Xenos '' Ouranos Level: 4 (estimate)  Let is a Goblin Xenos. As a Xenos, Let is far more intelligent and powerful than a normal monster.  Let refers to Bell as Mister. Bell mentions that he tries to act like a gentleman. He is shown to have rational thinking as he was one of the few Xenos who did not wanted to attack other adventurers after knowing that Ranye’s group was killed by the Ikelos Familia.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b209698-zV1svycBpaew.png', NULL, NULL, '竹田海渡', NULL, 209698, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
