INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014282', 'AN1570', 'イーファ', 'A young girl who served as a slave in Seika''s birthplace, the House of Count Lambrogue. Although she hides it from her surroundings, she has the power to see "spirits" that even Seika cannot see, and the talent to follow them. Ever since she was young, she has taken a liking to Seika, who has treated her well.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b283421-WO7ONF9G0bj6.png', NULL, NULL, '和氣あず未', NULL, 283421, 'MAIN', 149) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014283', 'AN1570', 'アミュ', 'A commoner girl who, like Seika, came to take the entrance exam for Rodnaire Academy of Magic. She has magical aptitude for all attributes, and she has an amazing talent for swords and magic, topping the entrance exam. Because of her ability, it is rumored that she is a "hero" who can defeat the Demon King.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b283422-sQeTzokEtyZt.png', NULL, NULL, '稗田寧々', NULL, 283422, 'MAIN', 115) ON CONFLICT DO NOTHING;
