INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014305', 'AN1570', 'ユキ', 'Ayakashi, a Kangitsune that Seika has been using since before she was reincarnated. She is a useless mascot character with possessiveness and supernatural powers, but she loves Seika from the bottom of his heart. In the past, the human body was like an adult woman, but in this world, for some reason, it has become smaller overall. She usually hides in Seika''s hair in the form of Kangitsune.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b288474-NeTY7AyMYpwi.png', NULL, NULL, '小倉唯', NULL, 288474, 'SUPPORTING', 59) ON CONFLICT DO NOTHING;
