INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014328', 'AN1571', '久保渚咲', 'Nagisa Kubo is the female protagonist of Kubo-san wa Boku (Mobu) wo Yurusanai. She is one of the few people who can easily find Shiraishi.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b164986-FewavqJshmYl.png', '8月2日', NULL, '花澤香菜', 160, 164986, 'MAIN', 1502) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014329', 'AN1571', '白石純太', 'He lacks almost any kind of presence, so people often overlook him. An exception to this is Nagisa Kubo, who is able to find him easily.', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b173331-DJo02GVou1Cj.png', '4月25日', NULL, '河西健吾', NULL, 173331, 'MAIN', 327) ON CONFLICT DO NOTHING;
