INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014338', 'AN1573', 'アニスフィア・ウィン・パレッティア', 'Anisphia is the first Princess of the Kingdom of Palettia.   Possessing memories of her past life, she longs to be able to fly in the sky with the power of magic. However, as she''s unable to use magic herself, she spends her days conducting questionable research in hopes of fulfilling her dream. Her eccentric behavior earned her the nickname "Princess Peculiar".', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203119-1vybpGB6PaEh.png', '4月16日', NULL, '千本木彩花', NULL, 203119, 'MAIN', 2022) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014339', 'AN1573', 'ユフィリア・マゼンタ', 'The daughter of Duke Magenta. A genius beauty who not only excels at magic, but also well-versed in academics, politics and combat.  As the fiancé of Prince Algard, she showed promise as the kingdom''s next queen. But one fateful night would change the course of her life forever...', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203120-8vNUsyywkAn9.png', '11月10日', NULL, '石見舞菜香', NULL, 203120, 'MAIN', 2011) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014340', 'AN1573', 'イリア・コーラル', 'Anisphia''s personal maid. Although a servant, she watches over Anisphia like an older sister. She was saved by Anisphia in the past and is deeply loyal to her.', 27, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b287673-C7AL7s8dn8oe.png', '1月12日', NULL, '加隈亜衣', NULL, 287673, 'MAIN', 213) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014341', 'AN1573', 'レイニ・シアン', 'The daughter of a commoner elevated to the rank of Baron. Despite her humble origins, she has succeeded in attracting the attention of the sons of several influential nobles at the aristocratic academy.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b287678-KKgVKog8UAve.png', '10月5日', NULL, '羊宮妃那', NULL, 287678, 'MAIN', 115) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014342', 'AN1573', 'ティルティ・クラーレット', 'The eldest daughter of the powerful Marquis Claret. She has withdrawn to a private residence, where she studies curses. Occasionally she conducts joint research with Anisphia, but they have a complicated relationship because of their different beliefs.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b287679-pse08YGBKzc6.png', '2月1日', NULL, '篠原侑', NULL, 287679, 'SUPPORTING', 225) ON CONFLICT DO NOTHING;
