INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014353', 'AN1574', '本条楓', 'Maple is the main heroine, who has just started playing NewWorld Online. A shielder class. Since she doesn’t want to get hurt, she always puts her skill points into vitality. Due to this, many think of her as useless offensively, but much to their surprise, she manages her own. She''s a bit silly, though surprisingly intelligent, and often abuses the game''s mechanics in ways the game developers don''t expect. Most of her actions in-game are done for the sole purpose of having fun, and though she p', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b147892-sL0t1VEMhC6p.png', '4月19日', NULL, '本渡楓', NULL, 147892, 'MAIN', 1771) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014354', 'AN1574', '白峯理沙', 'Kaede''s gamer gal pal who invited her to the VRMMORPG NewWorld Online. She is a professional gamer, having numerous achievements that certify her capabilities. Being the swashbuckler class, her reflexes are considered abnormal.  Sally is extroverted, cautious, and practical, reflecting on her past experience with other games. She also has a creative and tricky side to her, evidenced by her choice to become a swashbuckler so that her party with Maple "would never take any damage", as opposed to t', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b147893-t481NA7vtmdF.png', '3月28日', NULL, '野口瑠璃子', 155, 147893, 'MAIN', 660) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014355', 'AN1574', 'カナデ', 'A boy often mistaken for a girl because of his fair build. He joined Maple Tree when Maple invited him.  Kanade is quiet and clever, showing a fascination with puzzles and mysteries of every kind. He will usually devote an entire day to any task he finds interesting.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b152324-hkduA5xtw8Rp.png', NULL, NULL, '新井里美', NULL, 152324, 'MAIN', 204) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014356', 'AN1574', 'ユイ', 'Along with her twin May, they are recruited to Maple Tree while still on the first layer.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155753-r6XYNXGMlCWp.png', NULL, NULL, '諏訪ななか', NULL, 155753, 'MAIN', 184) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014357', 'AN1574', 'カスミ', 'Meets Sally and Maple during the game''s second event. Despite rough first impressions, they become friends and she eventually joins Maple Tree.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155751-yNkFpyB8A21x.png', NULL, NULL, '早見沙織', NULL, 155751, 'MAIN', 265) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014358', 'AN1574', 'クロム', 'Introduced Maple to Iz. He is invited to join Maple tree after the guild system was introduced. He is a caring and honest person who is open-minded and serious. Outside of combat, he gives off a strong parental vibe. Like Maple he is part of the Shield class as well as a sword he still tries to master.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155755-Jr88j18oGVur.png', NULL, NULL, '杉山紀彰', NULL, 155755, 'MAIN', 107) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014359', 'AN1574', 'マイ', 'Along with her twin Yui, they are recruited to Maple Tree while still on the first layer.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155752-zQt16bGFTJOs.png', NULL, NULL, '加隈亜衣', NULL, 155752, 'MAIN', 186) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014360', 'AN1574', 'イズ', 'She plays the production-specialized crafter class, being one of the top crafters in NWO. She joins Maple Tree upon Maple''s invitation.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155754-OhYPoTCUdvxu.png', NULL, NULL, '佐藤聡美', NULL, 155754, 'MAIN', 164) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014361', 'AN1574', 'ドレッド', 'Dred or Dread, is a member of Payne''s Guild, the Congregation of the Holy Swords along side Frederica and Drag.  He has a sharp intuition. His style puts focus on high speed and moderate attack power but his instincts tell him that’s he’s not an opponent for Payne or Maple.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158411-k8Uw7GlwZhHP.jpg', NULL, NULL, '山崎たくみ', NULL, 158411, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014362', 'AN1574', 'ドラグ', 'Drag is a member of Payne''s Guild, Congregation of the Holy Swords along side Frederica and Dread.  He is a gentle man with rough behavior. His combat style is like a boar, rushing in with a lot of power and laying waste to those around him. This style leads to even those close to him having a rough time supporting him.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158415-ocMIDY8lqLpa.png', NULL, NULL, '神奈延年', NULL, 158415, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
