INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014367', 'AN1574', 'ペイン', 'Payne is the top player in NewWorld Online and considered to be the strongest. He is the guild master of the Congregation of the Holy Swords alongside Frederica, Dread, and Drag.   Although polite, he sees Maple as a rival he aims to defeat in the future.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158419-OiDYa7reUOt5.png', NULL, NULL, '小野賢章', NULL, 158419, 'SUPPORTING', 73) ON CONFLICT DO NOTHING;
