INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014373', 'AN1574', 'ミィ', 'Mii is a player in NewWorld Online. She is the guild master of the Flame Emperors guild along side Markus, Misery, and Shin.  Mii acquired a skill and unknowingly built up a character with her great charisma that others willingly follow. After realizing this, she became embarrassed to show her true self; a quiet girl who wants to enjoy cute things. She regrets her actions but decided to up appearances for those who chose to follow her.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b158420-O6Bkva89GzbD.jpg', NULL, NULL, '佐藤利奈', NULL, 158420, 'SUPPORTING', 238) ON CONFLICT DO NOTHING;
