INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014385', 'AN1575', 'モネヴ・ザ・ゲイル', 'Monev the Gale is the first Gung-Ho Gun to fight Vash. Knives locks him in a cell to train his body for twenty years in order to gain the skill and power required to kill Vash. He wears a powered battle suit and carries two high-powered chain guns on his arms. These guns fire extremely fast due to the pressure chambers located on his back, and have tremendous stopping power, enough to tear through entire buildings. He also carries a wide variety of weapons in a big cloth rucksack, including an e', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/18618.jpg', NULL, NULL, '小林親弘', NULL, 18618, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
