INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014389', 'AN1575', 'Livio', 'Livio the Double Fang is a childhood friend of Wolfwood and the final member of the Gung-Ho Guns from the Eye of Michael. He wields the Double Fangs, two small cross-shaped machine guns strapped on his arms that fire from both ends.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b18833-LbjMAEFXWhLd.png', NULL, NULL, '室元気', NULL, 18833, 'SUPPORTING', 61) ON CONFLICT DO NOTHING;
