INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014440', 'AN1578', '緒山みはり', 'Mahiro''s little sister. A genius scientist that skipped grades and is now attending college. She is responsible for drugging Mahiro, turning him into a young girl.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130823-zK793dPoJnRv.png', '4月22日', 'AB', '石原夏織', NULL, 130823, 'MAIN', 432) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014441', 'AN1578', '緒山まひろ', 'He was a hikikomori neet and loner, until he woke up one morning as a little girl thanks to his younger sister drugging him.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130822-P3fYMPhllQLL.png', '3月6日', NULL, '高野麻里佳', NULL, 130822, 'MAIN', 1366) ON CONFLICT DO NOTHING;
