INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014444', 'AN1578', '穂月もみじ', 'Momiji is the younger sister of Kaede. She is in middle school, and is in the same class that Mahiro enters when they reenter school. Momiji likes to dress, look, and act as a tomboy, and many times she is taken for a young teen/tween boy. However, Momiji gives no indication that she is in any way a transgender tween. She appears to only be gender non-conforming.  However, she can be quite feminine in appearance on select occasions, like when she wears the middle school female uniform, a cute ju', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130821-atoZ7e2n5vdo.png', '10月20日', 'A', '津田美波', 149, 130821, 'SUPPORTING', 198) ON CONFLICT DO NOTHING;
