INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014447', 'AN1578', '穂月かえで', 'Kaede is a close personal friend of Mihari. They became friends in middle school. Mihari has progressed further in the academic system than Kaede, but they still are close, and see each other regularly.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130819-v3ibIz7bKfT4.jpg', '9月12日', NULL, '金元寿子', NULL, 130819, 'SUPPORTING', 253) ON CONFLICT DO NOTHING;
