INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014450', 'AN1578', '桜花あさひ', 'Asahi is a classmate of Mahiro in middle school. She befriends Mahiro, and the two become quite close to one another. Asahi talks with a pronounced Osaka accent. In the English language, such characters are usually given a heavy southern accent, similar to a southern, country girl drawl so reminiscent of a southern belle/dixie chick. She pronounces Mahiro''s name as "Maa-high-row".  She loves to hug people, especially her friends. Mahiro tells herself that Asahi always smells like the fresh, clea', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130824-EzuMhCfKdFjd.jpg', '5月5日', 'B', '優木かな', NULL, 130824, 'SUPPORTING', 170) ON CONFLICT DO NOTHING;
