INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014455', 'AN1578', '室崎みよ', 'Miyo-chan is a classmate of Mahiro in middle school. She is friends with Mahiro and Asahi. Miyo-chan is somewhat quiet and shy, and many times does not express herself verbally. However, she likes to hug and embrace her girl school friends, and takes a great interest in them and their activities.  She has become particularly interested in Mahiro, although she is younger then her by a couple of years. Miyo-chan seems to be socially interested only in girls, and limits her time and attention to on', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130820-8rTZFQ3TdhAn.png', '6月18日', 'O', '日岡なつみ', NULL, 130820, 'SUPPORTING', 142) ON CONFLICT DO NOTHING;
