INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014460', 'AN1578', '西宮まり', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b298377-bGpPgB186U7c.jpg', NULL, NULL, '水希凜', NULL, 298377, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014461', 'AN1579', '忘我', 'Occupation: Spy Affiliation: Lamplight Skills: She is a talented engineer and serves as the resident tech expert, though her inventions have been known to cause mayhem, especially during her time at her old school.  Annette is one of the main protagonists in the Spy Classroom series. She has no memories from her past before she join training school, and she became a spy because of her special skills, without even knowing who she was.', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197205-1YBuLlGiqoMA.jpg', '3月15日', NULL, '楠木ともり', NULL, 197205, 'MAIN', 117) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014462', 'AN1579', '愚人', NULL, 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232909-tvPsduetwtrH.png', '6月4日', NULL, '水瀬いのり', NULL, 232909, 'MAIN', 144) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014463', 'AN1579', '夢語', 'Occupation: Spy Affiliation: Lamplight Skills: She is both a master negotiator and a professional seductress, able to use her charms to extract information and achieve her goals.  Thea is one of the main protagonists in the Spy Classroom series. She is the oldest and most attractive member of Lamplight, and was the daughter of a newspaper company president and abducted when she was 11 as a hostage. However, she was saved by a spy who she admired and who became her inspiration to become one herse', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197203-GbieKlNt3dpk.jpg', '11月16日', NULL, '上坂すみれ', NULL, 197203, 'MAIN', 177) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014464', 'AN1579', '草原', 'Occupation: Spy Affiliation: Lamplight Skills: She has a talent for rearing and training animals, using her skills to train pet animals to perform tasks and assist her in various missions.  Sara is one of the main protagonists in the Spy Classroom series. She is a timid but kind-hearted girl who tends to add "ssu" at the end of her words. She is the daughter of a chef and restaurant owner in a rural town.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197204-dg3PP99mEvXY.jpg', '1月12日', NULL, '佐倉綾音', NULL, 197204, 'MAIN', 128) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014465', 'AN1579', '百鬼', 'Occupation: Spy Affiliation: Lamplight Skills: She is good at stealing and is the most athletic member of the team.  Sibylla is one of the main protagonists in the Spy Classroom series. She was born into a gangster family, and she and her younger siblings were forced to help in gang activities. She has a strong sense of justice and wanted to be a spy to protect her younger siblings.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197200-PH2shNWq4Sqv.jpg', '12月9日', NULL, '東山奈央', NULL, 197200, 'MAIN', 96) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014466', 'AN1579', 'クラウス', 'Occupation: Spy Affiliation: Lamplight, Inferno  Klaus is one of the main protagonists in the Spy Classroom series. He is the boss of Lamplight and a former member of Inferno, who re-established Lamplight after Inferno was wiped out. Self-proclaimed "the Greatest Spy in the World". Despite being "the Greatest Spy in the World", he is terrible at teaching as he does things intuitively.', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197206-PCxrF415jqMO.jpg', '7月11日', NULL, '梅原裕一郎', NULL, 197206, 'MAIN', 81) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014467', 'AN1579', '花園', 'Occupation: Spy Affiliation: Lamplight Skills: She has a knack on concocting poisons that can either paralyze or kill her targets.  Lily is one of the main protagonists in the Spy Classroom series. She is the team leader of Lamplight. She wants to become a spy due to her life being saved by one after she survived a poison gas attack during the Great War. Due to her concern for the Lamplight team and her own skills, she is designated by Klaus to be the team leader for Lamplight.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197190-PscSlGlc65sf.jpg', '8月1日', NULL, '雨宮天', NULL, 197190, 'MAIN', 264) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014468', 'AN1579', '氷刃', 'Occupation: Spy Affiliation: Lamplight Skills: She is a genius and excels in every skill, making her the most talented spy among the members of Lamplight   Monika is one of the main protagonists in the Spy Classroom series. She is the daughter of an artist, she ran away from home to become a spy, and within a short period of time, she became the top student at the training school. However, for some reason, she rapidly loses her ambition and is scouted by Lamplight after failing her grades.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197202-lLsc9qJMh71U.jpg', '5月18日', NULL, '悠木碧', NULL, 197202, 'MAIN', 135) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014469', 'AN1579', '愛娘', 'Occupation: Spy Affiliation: Lamplight Skills: She is skilled in disguises, and can even disguise herself as a man without being detected.  Grete is one of the main protagonists in the Spy Classroom series. She was the daughter of a politician but for some reason, she was forced out of her birthplace, and she seems to have decided to become a spy. Although she has an excellent brain, she has a deep-rooted distaste for men.', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197201-MV4skuCoJaG5.jpg', '9月7日', NULL, '伊藤美来', NULL, 197201, 'MAIN', 161) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014470', 'AN1579', 'オリヴィア', 'Olivia is the head maid to left-wing politician Uwe Appel.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301211-jKtoNRhfj61Z.jpg', NULL, NULL, '日笠陽子', NULL, 301211, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
