INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014528', 'AN1582', '桜川九郎', 'Kuro is the main male protagonist of Kyokou Suiri (In/Spectre) and the current boyfriend of Kotoko Iwanaga. He has supernatural powers of immortality and precognition.  Kuro is quiet and tends to be very nonconfrontational, barely even taking notice of his own injuries. He is uncaring about his own safety due to his healing abilities.  (Source: Kyokou Suiri Wiki)', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125947-i00TGOORpPyt.png', NULL, NULL, '宮野真守', NULL, 125947, 'MAIN', 349) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014529', 'AN1582', '岩永琴子', 'Kotoko is the main female protagonist in Kyokou Suiri and the current girlfriend of Kuro Sakuragawa.  She has a very outgoing personality and always makes an effort to find the root of any problem, especially when she has the help of yokai. She is oblivious to danger and she tends to be very clingy when it comes to Kuro. Kotoko is a self-centered, unrepentant prankster, who enjoys poking fun at others expense, and is also a bit of a pervert. She is also shown to have a rather childish demeanor w', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125946-YAjl4xufsVYn.png', NULL, NULL, '鬼頭明里', NULL, 125946, 'MAIN', 1534) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014530', 'AN1582', '音無晋', NULL, 50, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b299894-8tWdJmEG8KwO.png', NULL, NULL, '内田直哉', NULL, 299894, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014531', 'AN1582', '音無薫子', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b299914-duMZAx5su2HX.png', NULL, NULL, '長谷川暖', NULL, 299914, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014532', 'AN1582', '音無莉音', 'She is the daughter of Ryouma Otonashi, the eldest son of Gouichi Otonashi.  Ryouma had business at his shop, so Rion replaced him to attend Gouichi request.', 21, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b299895-OH4Ru4moNMYr.png', NULL, NULL, '石見舞菜香', NULL, 299895, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014533', 'AN1582', '室井昌幸', 'Because of facing many betrayals from his beloved people, he loses faith in human beings and wants to have an isolated life. In reality, he is a very decent person: he forgives those who betrayed him and does not want to enact any revenge; this makes many people confused about his overkind actions.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b266166-XA4bge2qBem8.png', NULL, NULL, '古川慎', NULL, 266166, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
