INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014535', 'AN1582', '嶋井多恵', 'An old woman who lives with a ghost cat in a small port town. Although she is over eighty, she is in good health and is relied on by the townspeople.', 80, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b298672-KY1dbKjwDzec.png', NULL, NULL, '智子宮寺', NULL, 298672, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
