INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014538', 'AN1582', '雪女', 'She has an appearance of a very beautiful woman with a smooth, white complexion, fitting her Snowy profile. She has long hair with a mix color of black and white. She often wears a white kimono. She really cares about Masayuki Muroi, who she thinks is too kind for a human.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b266167-ARBvuHChSJ3y.jpg', NULL, NULL, '悠木碧', NULL, 266167, 'SUPPORTING', 258) ON CONFLICT DO NOTHING;
