INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014595', 'AN1585', 'リョウマ・タケバヤシ', 'The main protagonist who lived an uneventful life as an office worker in Japan before dying in his sleep. Due to his diligent and kind behavior, he earns the grace of the gods who send him to another world as an 8-year-old boy where he lives in a forest for three years while polishing his skills and taming hundreds of slimes, making use of their multiple abilities in various tasks from combat and hunting to cleaning and crafting, until meeting the Jamil family who warmly welcomes him among them.', 11, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b167274-iBWLUtWBoOO6.jpg', NULL, NULL, '田所あずさ', NULL, 167274, 'MAIN', 237) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014596', 'AN1585', 'エリアリア・ジャミール', 'Heir to the Jamil dukedom, Eliaria is an 11-year-old girl who becomes Ryoma''s close friend. Like Ryoma, she is a monster tamer and her body is gifted with large magic potential, but has difficulty controlling it, until Ryoma teaches her how to train herself properly.  (Source: Wikipedia)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b180258-1tE8utxd0gLX.png', NULL, NULL, '桑原由気', NULL, 180258, 'MAIN', 140) ON CONFLICT DO NOTHING;
