INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014713', 'AN1589', 'いたち', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b299517-yZ6LDRaI8wSL.jpg', NULL, NULL, '儀武ゆう子', NULL, 299517, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014714', 'AN1590', '花奏すず', 'An Ayakashi Maiden who is the childhood friend of Matsuri Kazamaki. She is one of few who can see ayakashi, and is often very friendly to them. However, her maiden status makes her a target for ayakashi with ill intentions.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b174838-rS9WJJjPrykq.jpg', '12月25日', NULL, '市ノ瀬加那', NULL, 174838, 'MAIN', 172) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014715', 'AN1590', 'シロガネ', 'A powerful ayakashi and the king of the ayakashi. He is after Suzu Kanade, wanting to consume her to increase his power.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212501-6L1WzIDcFADk.jpg', NULL, NULL, '玄田哲章', NULL, 212501, 'MAIN', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014716', 'AN1590', '風巻祭里', 'A young boy who, along with his childhood friend Suzu Kanade, can see ayakashi (a type of spirit). After he learned about Suzu''s status as an Ayakashi Maiden from his grandfather, he became an exorcist ninja in order to protect her from harm.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b175063-PXAUmLGOj7eP.jpg', '8月1日', NULL, '富田美憂', NULL, 175063, 'MAIN', 80) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014717', 'AN1590', '風巻清弦', 'He is a ninja exorcist from the Kazamaki family and the grandfather of Matsuri Kazamaki.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b275644-tzVsPqq5rm8d.jpg', NULL, NULL, '魚建', NULL, 275644, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014718', 'AN1590', '歌川画楽', 'Garaku Utagawa is a ayakashi born from an ink brush, who has a human form and identity as a famous painter.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b243886-YXae5F52OM2E.png', NULL, NULL, '田丸篤志', NULL, 243886, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014719', 'AN1590', '月丘ルーシー', 'Lucy is a classmate and friend of Suzu Kanade. She''s a more silent and shy type, but she loves taking postworthy pictures of everything. She is usually always with Yayoi Toba.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212503-thQKe9jyv6nk.jpg', NULL, NULL, '木野日菜', NULL, 212503, 'SUPPORTING', 57) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014720', 'AN1590', '香炉木恋緒', 'Reo Kourogi is a Ninja of the Korogi clan and creator of Matsuri Kazamaki''s ninja gear.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b243885-mmtL7TZOBaKg.jpg', NULL, NULL, '山根綺', NULL, 243885, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014721', 'AN1590', '鳥羽弥生', 'Yayoi is a classmate and friend of Suzu Kanade. She always hangs out with Lucy.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212504-hRSjBL5z1Rep.jpg', NULL, NULL, '戸松遥', NULL, 212504, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
