INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014723', 'AN1590', 'ニノ曲宗牙', 'Soga Ninokuru is a ninja exorcist from the Ninokuru family and considers Matsuri Kazamaki as his rival.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b181101-KPDkVGHlhbDg.jpg', NULL, NULL, '石毛翔弥', NULL, 181101, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
