INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014776', 'AN1593', '照三', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290256-CaU2jgqzJ187.png', NULL, NULL, '小林千晃', NULL, 290256, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014777', 'AN1594', '鳴宮湊', 'Minato Narumiya is the protagonist of the series. He is a first-year at Kazemai High School where he is a member of the kyudo club.  Minato is a reserved and withdrawn person, which resulted from after his accident in sixth grade and his target panic incident at his last middle school tournament. He is serious and responsible, always doing his chores and cleaning the school kyudojo proactively. His seriousness often causes him to get flustered by more cheerful individuals like Nanao and Ryouhei.', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128273-Jmokq7D1CeEI.png', '12月21日', NULL, '上村祐翔', 173, 128273, 'MAIN', 188) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014778', 'AN1594', '竹早静弥', 'Seiya Takehaya is a first-year student at Kazemai High School and a member of the kyudo club, as well as serving as the club head and captain of the boys'' division.  Seiya is viewed as a mature, reliable, and kind character, determined to facilitate and oversee Minato''s success in kyudo. However, as he himself stated in episode two, when he gets serious, he has no need for compassion. Seiya and Minato have been friends since childhood due to being neighbors. Along with Ryouhei, the three of them', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128274-mAMhSDaBwfwW.png', '4月2日', NULL, '市川蒼', 175, 128274, 'MAIN', 385) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014779', 'AN1594', '山之内遼平', 'Ryouhei Yamanouchi is a first-year student at Kazemai High School where he is a member of the kyudo club.  Ryouhei was childhood friends with Minato and Seiya and went to kindergarten and elementary school with them until he transferred in fifth grade and went to a different middle school than them. In middle school, he took kyudo classes as part of his required martial arts course.  Ryouhei greatly admires Seiya for his intelligence and kindness to everyone, and frequently praises him for it. H', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128277-CWxvWU64FRN5.png', '2月23日', NULL, '鈴木崚汰', 182, 128277, 'MAIN', 124) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014780', 'AN1594', '如月七緒', 'Nanao Kisaragi is a first-year at Kazemai High School and a member of the kyudo club.  Ever since he was little, Nanao has attracted many female admirers due to his looks and charisma. However, the side effect of this was that he also received many jealous attacks, so his mother and aunts decided to have Kaito, his cousin, act as his bodyguard. This worked well in elementary school, and though they went to separate middle schools, they were still in extracurriculars and cram school together. Som', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128275-TPfdt9sMnHH5.png', '10月18日', NULL, '矢野奨吾', 170, 128275, 'MAIN', 153) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014781', 'AN1594', '小野木海斗', 'Kaito Onogi is a first-year student at Kazemai High School and a member of the kyudo club.  Kaito comes off as short-tempered, overly serious, and aggressive. He is easily riled up, especially when his cousin Nanao calls him Kacchan or when he perceives someone to not be taking something as seriously as he does. He is blunt with his words and not afraid to say what he really thinks. He tends to jump to conclusions. This causes people to be afraid of him. A large part of his current personality m', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128276-D9Jb4mg5F0cx.png', '9月22日', NULL, '石川界人', 178, 128276, 'MAIN', 143) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014782', 'AN1594', '滝川雅貴', 'Masaki Takigawa is a senior shrine priest at Yata Shrine and later becomes the coach for the Kazemai High School Kyudo Club. He holds a fifth dan rank in kyudo.  Masaki gives off the image of a mysterious, refined young man, but he is actually more laid-back and down-to-earth than he seems. He has the air of an old man despite his young age. He is noted to act roughly and sloppily in many things except in kyudo. He seems to dislike formality, asking everyone to call him "Masa-san" instead. He is', 23, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128729-93C82wnqJzmH.jpg', '8月10日', NULL, '浅沼晋太郎', 184, 128729, 'MAIN', 444) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014783', 'AN1594', '二階堂永亮', 'A second-year student at Tsujimine High School and a member of its kyuudou club.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b295848-TN0nLPUB6Xwv.jpg', '2月7日', NULL, '福山潤', 174, 295848, 'SUPPORTING', 57) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014784', 'AN1594', '白菊乃愛', 'Noa Shiragiku is a first-year student at Kazemai High School and a member of the kyudo club.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b168021-CSjivvUbt7zK.jpg', '3月7日', NULL, '七瀬彩夏', NULL, 168021, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
