INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014839', 'AN1597', 'レクター・アランドール', 'Affiliation: Imperial Army Intelligence Division, The Ironbloods Nationality: Erebonian  A senior intelligence officer and the head of the Imperial Army Intelligence Division. He is one of the Ironbloods, a handpicked aide of Chancellor Giliath Osborne. He is specialized in negotiation, usually sent to negotiate with hostile powers against Erebonia far and wide. He is very serious and cold when it comes to his job as an Intelligence Officer, with the tendency to use every option that could turn ', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244076-Tl2Kn6j3UMue.png', NULL, NULL, '森田成一', NULL, 244076, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014840', 'AN1597', 'マキアス・レーグニッツ', 'Affiliation: Thors Military Academy, Government Accountability Inspectorate Nationality: Erebonian  A prodigy student with strict standards that he holds over everyone in his class. He is the vice president to Class VII and the second runner in academic ranking in the class, next to Emma Millstein. His notable trait is his distaste towards the nobility as a whole. He is the son of Carl Regnitz, Imperial Governor of Capital City Heimdallr.', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b235225-jjMwQYhPZGoW.jpg', NULL, NULL, '佐藤拓也', NULL, 235225, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014841', 'AN1597', 'グラーク・グロマッシュ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b293421-We8D95Gu007x.png', NULL, NULL, '壤晴彦', NULL, 293421, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014842', 'AN1597', 'カンパネルラ', 'Affiliation: Ouroboros  A mysterious trickster affiliated with Ouroboros. He is the Zeroth Enforcer and he acts mostly as an observer to the plan carried by the Anguis of Ouroboros. He reports straight to the Celestial Globe, to the Grandmaster herself. He appears to have not aged a bit throughout the entire series. He is able to utilize magic without the help of Arts and Combat Orbments', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b201631-q4dQZHiDnXAd.png', NULL, NULL, '伊藤かな恵', NULL, 201631, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
