INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014844', 'AN1597', 'ローガン・ムガート', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b293419-8xunj3xarZBC.png', NULL, NULL, '近藤孝行', NULL, 293419, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014845', 'AN1597', 'クレア・リーヴェルト', 'Affiliation: The Railway Military Police, The Ironbloods Nationality: Erebonian  Captain to the Railway Military Police, a military organization reserved for the protection of the Erebonian Empire''s Transcontinental Railway System. She is also a part of the Ironbloods, Chancellor Osborne''s most trusted aide. It is noted that Claire has an unusual cognitive perception level, being able to grasp events and calculate it as a whole. She is a very cold and calculating character when she dons her mili', 24, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b298406-2WEnkeMLewkx.png', NULL, NULL, '小清水亜美', NULL, 298406, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014846', 'AN1597', 'オリビエ レンハイム', 'Nationality: Erebonian Affiliation:   A handsome blond man from the Erebonian empire who claims to be a traveling musician. He is indeed blessed with great musical talents on almost all instruments, but is also extremely carefree and has peculiar tastes. Some of his antics include drinking an incredibly expensive wine after giving a performance at a local restaurant (which gets him in jail) and making several passes at all other attractive characters (in his eyes, he is the Hunter of Love).', 26, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b50327-te87GWPgR3zQ.png', '4月1日', NULL, '子安武人', NULL, 50327, 'SUPPORTING', 185) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014847', 'AN1597', 'ギリアス・オズボーン', 'Nationality: Erebonian Affiliation: Erebonian Imperial Government, The Ironbloods,   Chancellor to the Imperial Government of Erebonia, trusted by the Emperor to hold complete control over domestic politics of the Empire, presiding over The Vermillion Palace in the capital Heimdallr. Born a commoner, he strongly opposes the noble regime of the Erebonia Empire. He is the figurehead to the Reformist Faction that wishes to take the power from the noble for the Imperial Government. Cunning and well-', 53, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199309-2lqTw56NoZRa.png', NULL, NULL, '中田譲治', NULL, 199309, 'SUPPORTING', 46) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014848', 'AN1597', 'オーレリア・ルグィン', 'Nationality: Erebonian Affiliation: Lamare Provincial Army, Thors Military Academy Branch Campus (Principal)   Aurelia Le Guin, the daughter of Count Le Guin. She is the only known master practitioner of the Empire''s two renowned swordsmanship school, Vander and Arseid school of swordsmanship. Known on the battlefield as The Golden Raksasha, she is a formidable fighter and general, She sought to reach the pinnacle of strength by mastering and eventually besting the Masters of respective school, ', 31, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b298405-O1VsDzKd249m.png', NULL, NULL, '住友優子', NULL, 298405, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014849', 'AN1597', 'エステル・ブライト', 'Affiliation: Bracer Guild Nationality: Liberlian  The main protagonist of Trails in the Sky. A bright, cheerful, and always optimistic girl. She is described by many people as hot-headed to the point of recklessness. She is quick to act on her whim without so much of planning or consideration to the effect her action may cause. Even so, this hot-headed and recklessness stems from her strong sense of justice. She is the daughter of Cassius Bright and is also a Bracer. Her weapon of choice is a Bo', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b30247-UPFbpaHYYqMj.png', '8月7日', NULL, '神田朱未', NULL, 30247, 'SUPPORTING', 384) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014850', 'AN1597', 'リィン・シュバルツァ', 'Affiliation: Thors Military Academy Class VII, Thors Miltary Academy Branch Campus Class VII Instructor, Erebonia Imperial Army, The Schwarzer Barony Nationality: Erebonian  Rean Schwarzer is one of the students chosen as a member of an experimental class dubbed "Class VII" in Thors Military Academy and the protagonist of the series in "Erebonia Arc" (Trails of Cold Steel series). Rean came from a family of lesser noble hailing from the Northern Territory of the Empire, Ymir.      After finishin', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127452-R2zvfbjvz3Ox.png', '5月', NULL, '内山昂輝', NULL, 127452, 'SUPPORTING', 254) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014851', 'AN1597', 'ルーファス・アルバレア', 'Rufus Albarea is introduced as the oldest son of Duke Helmut Albarea, head of one of the Four Great Houses, and half brother to Jusis Albarea.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b190373-V1b9Tigw8uVT.png', NULL, NULL, '平川大輔', NULL, 190373, 'SUPPORTING', 72) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014852', 'AN1597', 'ウォレス・バルディオス', 'Nationality: Erebonian Affiliation: Sutherland Provincial Army,   Brigadier General to the Sutherland Provincial Army, an army tasked with the protection of the southern province of Erebonia. He is the descendant of the Nord people who assisted Emperor Dreichels Reise Arnor in the War of the Lions and subsequently moved to Erebonia, gaining their family the seat of nobility in the Empire society. He is the successor to the Bardias Spearsmanship school originating from Nord Highlands. His skill w', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b298407-NjY9ZAreTYE9.png', NULL, NULL, '近藤孝行', NULL, 298407, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014853', 'AN1597', 'ヨシュア ブライト', 'Affiliation: Bracer Guild  A quiet young man with black hair and amber eyes who''s always there to keep the hot-headed Estelle from getting too deep into trouble. His choice of weapons is a pair of swords. He lives with Cassius Bright and Estelle Bright on the outskirts of Rolent. He undertook the Bracer Examination Test together with Estelle at the start of the series. Has been noted as quite the handsome young man and is also oblivious to things regarding romantic advances pointed at him.', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b50121-ZICSm4Cevqha.png', '12月20日', NULL, '斎賀みつき', NULL, 50121, 'SUPPORTING', 141) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014854', 'AN1597', 'アルティナ・オライオン', 'Affiliation: Noble Alliance,  Nationality: Erebonian  During the event of Trails of Cold Steel II, Altina works for the Noble Alliance, serving as the antagonist of the series. She is accompanied by a jet-black Combat Shell named "Claiomh Solais" which heeds to her every order through a mental link. Altina doesn''t understand human feelings and as such, she sometimes has trouble expressing her emotions.', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128898-hZfpS9yWS2Ak.jpg', NULL, NULL, '水瀬いのり', NULL, 128898, 'SUPPORTING', 120) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014855', 'AN1597', 'ブルブラン', 'A phantom thief with a knack for dramatic flairs, he always makes an attempt to make his act known far and wide. One could say that Phantom Thief Bleublanc is a man with intense narcissism as a trait. As a thief, he is the expert at disguise and infiltration. There is nothing that he can''t steal but he will only steal things of a significant beauty value to it. Due to their shared passion with seeking beauty, he and Olivier shared a kind of rivalry with each other, aiming to see whose beauty is ', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b54683-21ZqWyKODq0l.png', NULL, NULL, '三浦祥朗', NULL, 54683, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014856', 'AN1597', 'ロイド・バニングス', 'Affiliation: Crossbell Police Department Special Support Section Nationality: Crossbellan  A young detective that is assigned to the Special Support Section. He used to live in the Republic of Calvard prior to his employment at Crossbell Police Department. He is remarked as a brilliant detective, earning his Detective license at a very young age. He acts as a de facto leader of the Special Support Section due to his natural knack for leadership and charisma to inspire and lead.', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72237-DBSPWJKhZAov.jpg', NULL, NULL, '柿原徹也', NULL, 72237, 'SUPPORTING', 157) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014857', 'AN1597', 'イバーノ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', NULL, NULL, '福島潤', NULL, 293417, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014858', 'AN1597', 'ミリアム・オライオン', 'Nationality: Erebonian Affiliation: Imperial Intelligence Division, Thors Military Academy Class VII,   A petite girl belonging to the Imperial Intelligence Division. She is linked to a silver humanoid shell-puppet called "Airgetlam". She is very childlike in nature and a kind of a blabbermouth, which makes her a rather poor Intelligence agent. Even so, her destructive ability is a great asset to the division. She is rather attached to Jusis Albarea, much to his annoyance.', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b237986-dzCpEGhw9aiS.png', NULL, NULL, '小岩井ことり', NULL, 237986, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014859', 'AN1597', 'デュバリィ', 'Affiliation: Knights of the Stahlritter  Head Knight of the Stahlritter, an order of knights established by Arianrhod. She is a stern knight with unwavering loyalty to her liege. Acting as Arianrhod''s left hand in most matters, she is a fearsome warrior with unparalleled speed, earning her the moniker, Duvalie the Swift. Stern as she is, it is noted that she has to her an airhead and clumsy side, which earns her the endless teases from her fellow knights or even adversaries, much to her dismay. ', 23, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b299534-9glwp69lCfr1.png', NULL, NULL, '大空直美', NULL, 299534, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014860', 'AN1597', 'リーシャ・マオ', 'Affiliation: Arc en Ciel Theater Troupe,  Nationality: Calvardian  The up-and-coming star of Arc en Ciel theater troupe. Scouted personally by the troupe''s main star, Ilya Platiere. Originally a traveler from Calvard visiting Crossbell. She is very slender and quick on her feet, which makes her a natural in the craft. She served as the lead performer alongside Ilya and is garnering a lot of loyal fans at home and even abroad.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b76164-J8QE4HZh0Nze.png', NULL, 'O', '佐藤利奈', 159, 76164, 'SUPPORTING', 67) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014861', 'AN1597', 'タック', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', NULL, NULL, '木島隆一', NULL, 293418, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014862', 'AN1597', 'エリオット・クレイグ', 'Affiliation: Thors Military Academy Class VII, Heimdallr Music Academy Nationality: Erebonian  The son of the famous military general, Craig the Red. Elliot is a bright young man with a tremendous talent for music. Though he originally wanted to study music at an academy in Heimdallr, his father objected, forcing him to enroll at Thors instead. There, he was placed in Class VII, met Rean, and the rest is history. Growing over the course of his time spent with Class VII, Elliot graduated early an', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b211601-gZ597tJbng9S.png', NULL, NULL, '白石涼子', NULL, 211601, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014863', 'AN1598', 'サトシ', 'Satoshi (known as Ash Ketchum in most international territories) is the main character of the Pocket Monsters anime. He is also the main character of various manga based on the anime, including but not limited to Dengenki Pikachu, Satoshi to Pikachu, and Pocket Monsters Diamond & Pearl. He is a Pokémon Trainer from Masara Town whose goal is to become a Pokémon Master. His starter Pokémon was a Pikachu that he received from Professor Okido after arriving late at his laboratory.      He shares his', 10, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b2473-JDoo3I82Km4l.png', NULL, NULL, '松本梨香', NULL, 2473, 'MAIN', 1591) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014864', 'AN1598', 'ピカチュウ', 'Pikachu is the signature Pokémon of the Pocket Monsters anime, and the first Pokémon that Satoshi obtained on his journey as a Pokémon Trainer, given to him by Professor Okido.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b3891-edgrZOgCJ9do.jpg', NULL, NULL, '大谷育江', NULL, 3891, 'MAIN', 1278) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014865', 'AN1598', 'タケシ', 'Takeshi appeared primarily as an opponent to Satoshi in his debut episode; unlike later Gym Leaders, he requested to join Satoshi on his journey, aiming to be the world''s greatest Pokémon Breeder.  Takeshi mainly provides an advisory role to the other main characters of the anime, being several years older than the rest of them. His knowledge of Pokémon battles is great, causing him to often referee matches between Satoshi and others. Takeshi also fancies himself as something of a ladies'' man, t', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b3854-qMVUF2YmWYoW.png', NULL, NULL, 'うえだゆうじ', NULL, 3854, 'MAIN', 643) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014866', 'AN1598', 'カスミ', 'Kasumi is a Gym Leader of Hanada City''s Gym, known officially as the Hanada Gym. She gives the Cascade Badge to Trainers who defeat her in battle. She specializes in Water-type Pokémon.  Kasumi is a friend and former traveling partner of the anime''s main character, Satoshi. After he stole her bike and proceeded to accidentally destroy it, Kasumi followed him around the Kanto region, the Orange Islands, and the Johto region, using the time she spent with him to further her goal of becoming the gr', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b2909-wNDR5aaxwDdi.png', NULL, NULL, '飯塚雅弓', NULL, 2909, 'MAIN', 495) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014867', 'AN1598', 'オーキドシゲル', 'Shigeru is a character who is roughly the same age as Satoshi (though Shigeru is assumed to be slightly older, due to the height difference between the two); they were playmates and next-door neighbors when they were younger, but drifted apart when they both discovered their love of Pokémon, according to the video game. At the start of the series his rivalry with Satoshi becomes a recurring motif. Like the video games, manga and anime, Shigeru is described as an overconfident and arrogant traine', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b4848-vR9au1dEKjyy.png', NULL, NULL, '小林優子', NULL, 4848, 'SUPPORTING', 101) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014868', 'AN1598', 'ハナコ ', 'She is Ash&#039;s mother. Delia is very caring of her son, always reminding him to do his best. She is very talented, having won a beauty pageant and cooked a dish so popular that elite chefs at the Indigo Plateau have asked for its recipe. It is not known who is the father of Ash, but it isn&#039;t clear that Ash&#039;s parents have separated, although she has contacted him at least once since Ash left. She has a Mr. Mime housekeeper who helps her with chores and is also rather adept in battle.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/29184.jpg', NULL, NULL, '豊島まさみ', NULL, 29184, 'SUPPORTING', 58) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014869', 'AN1598', 'バリちゃん', 'Barri-chan is a Barrierd who is currently living with Satoshi''s mother Hanako.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b152206-TEBlsOK6TwyP.png', NULL, NULL, 'うえだゆうじ', NULL, 152206, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014870', 'AN1598', 'リザードン', 'Lizardon is a draconic, bipedal Pokémon. It is primarily orange with a cream underside from the chest to the tip of its tail. It has a long neck, small blue eyes, slightly raised nostrils, and two horn-like structures protruding from the back of its rectangular head. There are two fangs visible in the upper jaw when its mouth is closed. Two large wings with blue-green undersides sprout from its back, and a horn-like appendage juts out from the third joint of each wing. A single wing-finger is vi', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b180037-u3b2oiaWdfAm.png', NULL, NULL, '三木眞一郎', NULL, 180037, 'SUPPORTING', 126) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014871', 'AN1598', 'ハハコモリ', 'Hahakomori is a thin, yellow, bipedal insectoid Pokémon. It has a broad, split leaf around its large, round head and it has long antennae that end in semicircles. Its eyes are red with no apparent sclerae. Its tiny thorax is dark green, and its long abdomen is yellow and covered in a green leaf. Its hands are long and leaf-like with a "bite" taken out of each. Its upper arms are also leaf-like, but with a vein of yellow at the top. Its thin legs are yellow with dark green, thick segments around ', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b177083-JANkoLZsi4Ks.png', NULL, NULL, '犬山イヌコ', NULL, 177083, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014872', 'AN1598', 'ハブネーク', 'Habunake is a serpentine Pokémon that is usually depicted scrunched up like an accordion. It is mostly black in color but has several markings on its body. It has yellow hexagon markings that run from its head to its tail, small yellow bumps where it touches the ground, and various purple scar-like marks. It has elongated red fangs that protrude from its upper jaw and fierce red eyes. Its tail is partially red and has a blade-like shape. Habunake sharpens its tail on rocks and can use it for its', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b192413-4fp6IPkFRPQ6.png', NULL, NULL, '佐藤智恵', NULL, 192413, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014873', 'AN1598', 'マスキッパ', 'Muskippa is a green Pokémon resembling a Venus flytrap. Its circular eyes have small pupils, and it has spiky teeth. Its stem is yellow with green spots, with red and green vines beneath with the appearance of tentacles. It can hang from tree branches using these vines, and it is said to look like a plant. It has two arms resembling leaves with three leafy ''fingers'' each. Its mouth can open to about 180 degrees wide. With its mouth wide open, it attracts the prey it waits for with sweet-smelling', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b192411-omOcj1Qcm2lw.png', NULL, NULL, '阪口大助', NULL, 192411, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014874', 'AN1598', 'ジョーイ', 'Nurse Joy is a recurring character in every Pokemon series released.   There are multiple Nurse Joys in every town, city and region. They all look the same, have the same voice and personalities. There have been numerous speculations as to why all the Joys look alike, though it seems they are all related in some way.   However, there have been instances in which a Nurse Joy has been known to have a different personality and appearance (such as the aggressive sun-tanned Nurse Joy of the Orange Is', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b7558-LzxI6BSiinA3.png', NULL, NULL, '真堂圭', NULL, 7558, 'SUPPORTING', 86) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014875', 'AN1598', 'カビゴン', 'Kabigon is a huge, bipedal, dark blue-green Pokémon with a cream-colored face, belly, and feet. Its body is composed of mostly its belly, as its limbs are comparatively small. Its head is large with small, pointed ears and two pointed teeth protruding from its lower jaw. It has round feet, which both have three claws and a circular brown paw pad, and short arms with five claws on each hand. Kabigon''s bulk makes it the heaviest Normal type.  Kabigon is often found in mountains and forests. It wak', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b177037-VAWVNfkeSEpZ.png', NULL, NULL, '小西克幸', NULL, 177037, 'SUPPORTING', 83) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014876', 'AN1598', 'キングラー', 'Kingler is a crustacean Pokémon resembling a crab. Its strong shell covers the outside of its body, featuring a red upper half and a light tan lower half. Its upper half is topped with six tall, thin spikes that resemble a crown. Its light tan arms are also connected to its upper body. Its lower half doubles as its jaw with six fangs overlapping its upper body. Its two outer fangs are much larger than the inner four and are roughly half as tall as Kingler''s entire body. Its hips visibly protrude', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b181416-O550UaSJ8shf.png', NULL, NULL, '石塚運昇', NULL, 181416, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014877', 'AN1598', 'モロバレル', 'Morobareru is a mushroom-like Pokémon with a large, light-colored Poké Ball designed cap with warts. It also has a huge, gray, stem-like body; fierce-looking eyes; and a large, pink mouth. Morobareru wields two Poké Ball-like shields. It uses the Poké Ball-like patterns on its arms to lure in prey, though it doesn''t work too well in most cases. It also blows poisonous spores at its opponents. These spores can grow into mushrooms on wherever they landed if they are not washed off quickly. Morobar', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b198081-Ek3jwmSDaDOC.png', NULL, NULL, '石塚運昇', NULL, 198081, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014878', 'AN1598', 'スマホロトム', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b288049-95pZSMCqtdYo.png', NULL, NULL, NULL, NULL, 288049, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014879', 'AN1598', 'コジロウ', 'Kojirou is a member of the Rocket Gang, more specifically part of a trio with Musashi and Nyarth, that follows Satoshi and his friends around in the Pocket Monsters anime, usually trying to steal Satoshi''s Pikachu.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b3936-5sX4EZIY2BRU.png', NULL, NULL, '三木眞一郎', NULL, 3936, 'SUPPORTING', 1167) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014880', 'AN1598', 'オーキド・ユキナリ', 'Yukinari Ookido is a Pokémon Professor and a major supporting character of the Pocket Monsters anime who lives and works at his research lab in Masara Town. He appears semi-regularly to give Satoshi advice to help him achieve his goal of becoming the greatest Pokémon Master.   (Source: Bulbapedia)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b17783-OwYJSOFjd91A.png', NULL, NULL, '堀内賢雄', NULL, 17783, 'SUPPORTING', 76) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014881', 'AN1598', 'ミジュマル', 'Mijumaru is a bipedal sea otter-like Pokémon. It has a spherical white head with small, triangular dark-blue ears on the sides. Mijumaru''s eyes are dark and its dark orange nose is shaped like a horizontal oval. Several freckles cover its cheeks which may be premature whiskers, and two pointed teeth can be seen when it opens its mouth. The light blue fur on its body forms bubble shapes around its neck. Its arms are white and rounded, while its feet are dark blue with three toes each. It also pos', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b176871-kTOvY3UZh3cc.png', NULL, NULL, '福圓美里', NULL, 176871, 'SUPPORTING', 61) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014882', 'AN1598', 'ラプラス', 'Laplace is a large sea Pokémon that resembles a plesiosaur. It has a blue hide with darker blue spots and a cream-colored underside. It has large brown eyes, a short horn on its forehead, and tightly curled ears. It has a long neck and four flippers. The foremost flippers are larger than the hind. On its back is a heavy, gray shell covered in blunt knobs.  Laplace is a gentle, helpful Pokémon that enjoys ferrying people across bodies of water. In the past, its docility made it an easy target for', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b224575-QAmzeADDKgBh.png', NULL, NULL, '愛河里花子', NULL, 224575, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014883', 'AN1598', 'デスマス', 'Desumasu is a shadow-like Pokémon holding a golden mask that has a face from its time as a human. It has two shadowy, tendril-like arms and large, red eyes. It also has a small tail-like appendage that holds the mask. Desumasu is capable of speech when possessing a human, but not in its regular form.  Due to being a human long ago, it has memories of being a human. It becomes furious when the mask is lost or taken away. If someone wears the mask Desumasu carries, they will become possessed by th', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b177132-6aKEs4NQxiDh.png', NULL, NULL, 'かないみか', NULL, 177132, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014884', 'AN1598', 'ムサシ', 'Musashi is a member of the Rocket Gang, more specifically part of a trio with Kojirou and Nyarth, that follows Satoshi and his friends around in the Pocket Monsters anime, usually trying to steal Satoshi''s Pikachu.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b3935-m000RuoIVOGI.png', NULL, NULL, '林原めぐみ', NULL, 3935, 'SUPPORTING', 671) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014885', 'AN1598', 'ジュンサー', 'Officer Jenny is not a single entity. Rather, there are many Jennys working as police officers across the various regions of the Pokémon world.  Generally, Officer Jennies are brave and determined, but mostly ineffective in their police duties. They fight against the likes of Team Rocket, Team Magma, Team Aqua and Team Galactic - among other miscellaneous criminals. The town/region where a certain Jenny comes from can be discerned by the symbol on their hats which always differs depending on loc', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/26545.jpg', NULL, NULL, '清水理沙', NULL, 26545, 'SUPPORTING', 74) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014886', 'AN1598', 'カイリュー', 'Kairyu is a draconic, bipedal Pokémon with light orange skin. It has large, grayish-green eyes and a round snout with small nostrils. A pair of long, thin antennae sprout from the top of its head with a small horn set between them. Its striated underbelly is cream-colored and extends from its neck to the tip of its long, tapering tail. It has thick arms and legs ending in three claws each. The leg joints are well defined, while its arms have a smooth, rounded appearance. Kairyu''s wings are small', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b142475-s0UL21Qb4nr4.png', NULL, NULL, '三宅健太', NULL, 142475, 'SUPPORTING', 75) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014887', 'AN1598', 'ヒコザル', 'Hikozaru is a bipedal Pokémon resembling a chimpanzee. Its fur is primarily a shade of orange, though its face, outer ears, underbelly, hands, and feet are light yellow. Its rear has a small, round, red patch that is usually obscured by flames produced by burning gas in its stomach. These flames go out when it goes to sleep, and burn weakly when it feels ill. Its ears are large in comparison to its head size and red inside. It has two pointed teeth in its upper jaw. Hikozaru has red markings nea', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b169027-phU6SpQvXhNc.png', NULL, NULL, 'うえだゆうじ', NULL, 169027, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014888', 'AN1598', 'ヘラクロス', 'Heracros is a bipedal, beetle-like Pokémon covered in a blue exoskeleton. There is a long, pronged horn on its forehead. The horn ends in a cross on the male and a heart-shape in the female. On either side of the horn is a short antenna with a spherical tip. Heracros has oval, yellow eyes. Its forearms have a pair of spikes near the wrists, while its thighs have a single spike each. It has two claws on its hands, and a single long claw on each foot. There is a single pair of wings covered by its', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b177034-86PsQedjGC3P.png', NULL, NULL, '小西克幸', NULL, 177034, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014889', 'AN1598', 'ゲンガー', 'Gangar is a dark purple, bipedal Pokémon with a roundish body. It has red eyes, a wide mouth that is usually curled into a sinister grin, and pointed ears. On its back are numerous spikes and it has smaller spikes on top of its head similar to tufty fur. Its arms and legs are short with three digits on both its hands and feet. It also has a stubby tail.  Gangar has the ability to hide perfectly in the shadow of any object, granting it exceptional stealth. However, Gangar''s body acts as a heat si', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b25680-trcx01Kv1BuL.png', NULL, NULL, '間宮康弘', NULL, 25680, 'SUPPORTING', 161) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014890', 'AN1598', 'イワーク', 'Iwark is a Pokémon composed of a giant chain of gray boulders that become smaller towards the tail. Its length makes it the tallest Rock-type Pokémon. It has black eyes and a rounded snout. On top of its head is a rocky spine. As it grows older, it becomes more rounded and smoother, eventually becoming similar to black diamonds. Inside its brain is a magnet that serves as an internal compass, guiding Iwark wherever they need to go and prevents them from getting lost while digging.  Iwark tunnels', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b180469-iL9DhgXFimuK.png', NULL, NULL, '石塚運昇', NULL, 180469, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014891', 'AN1598', 'ツタージャ', 'Tsutarja is a bipedal, reptilian Pokémon with a slender build. Most of its body is green with a cream underside. A yellow stripe runs down the length of its back and tail, and it has yellow markings around its large eyes. Two curved yellow structures that resemble leaves or small wings protrude from its shoulders and bend backwards. Its slender arms have three fingers, while its tiny feet have no digits whatsoever.   It has a large, palmate leaf with three prongs on the end of its tail. This tai', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b177023-OPOk2SetMEWH.png', NULL, NULL, '林原めぐみ', NULL, 177023, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014892', 'AN1598', 'ナエトル', 'Naetle is a small, light green, quadruped Pokémon resembling a turtle or tortoise. Its eyes, feet, and lower jaw are yellow. Its body is covered by a brown shell that is composed of earth. The shell has a thick black stripe and a black rim. On a very healthy Naetle, the shell should feel moist. A small seedling grows on a brown patch on its head. This seedling will wilt if the Pokémon becomes thirsty. As a plant-based Pokémon, Naetle usually nourishes itself through photosynthesis. It also drink', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b169028-wxKcFhl4DJB6.png', NULL, NULL, '三木眞一郎', NULL, 169028, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014893', 'AN1598', 'ゴマゾウ', 'Gomazou is a small, blue elephant-like Pokémon. It has large, floppy ears, which it uses as fans to cool itself. There are two red pads on each ear and another on the bridge of its short trunk. This small trunk is sensitive, yet strong. It can send a person flying with an affectionate, playful bump of its snout. Additionally, this little Pokémon is easily capable of carrying an adult human on its back. Gomazou has a single nail on each of its four feet, and a short tail.  Gomazou is found in roc', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b190815-cfbM9SYkD4iI.png', NULL, NULL, '三宅健太', NULL, 190815, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014894', 'AN1598', 'チコリータ', 'Chicorita is a small, pale green Pokémon with dark green buds around its neck. Its head is large in proportion to the rest of its body, and it has big red eyes. It has four short legs with a single nailed toe on each and a stubby tail. On top of its head is a large, green leaf that is usually longer than its body. A soothing aroma wafts from the leaf, which can calm battling Pokémon. The leaf is also used to sense temperature and humidity. Chicorita actively seeks out and enjoys the sun''s warmth', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b190816-kqKra8cXB63L.png', NULL, NULL, 'かないみか', NULL, 190816, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014895', 'AN1598', 'ゼニガメ', 'Zenigame is a small Pokémon that resembles a light blue turtle. It has large, purplish or reddish eyes and a slightly hooked upper lip. Each of its hands and feet have three pointed digits. The end of its long tail curls inward. Its body is encased by a tough shell that forms and hardens after birth. This shell is brown on the top, pale yellow on the bottom, and has a thick white ridge between the two halves.  Zenigame''s shell is a useful tool. It can withdraw into the shell for protection or to', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b181415-PDKBuX4s07HF.png', NULL, NULL, '愛河里花子', NULL, 181415, 'SUPPORTING', 98) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014896', 'AN1598', 'ジュプトル', 'Juptile is a bipedal Pokémon similar in appearance to a theropod dinosaur. It is primarily green with a red underside. There is a belt-like green stripe across its belly. Juptile''s hands have two clawed fingers and powerful legs with birdlike feet. Its well-developed muscles make it an expert climber and allow it to leap quickly from branch to branch. Juptile has three long leaves on its wrists, a large leaf on top of its head, and two tails that have a leafy appearance. This leafy appearance al', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b224569-foWn3akw2mwZ.png', NULL, NULL, 'うえだゆうじ', NULL, 224569, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014897', 'AN1598', 'ラティアス', 'Latias is a Pokémon with a bird-like body stylized after a plane. Its long neck stretches forward from its squat body. It has no legs, usually floating instead. The rear half of its body is largely red and the upper half white, with jet-plane wings high on its rear and fins on the bottom near its tail. A blue triangle marks the center of its chest, while a red mask partially covers its face. Ear-like fins sit on top of its head and its eyes are yellow. It has short, three-fingered arms with a re', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b147268-grmjjNgeSLl4.png', NULL, NULL, '真堂圭', NULL, 147268, 'SUPPORTING', 53) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014898', 'AN1598', 'ラティオス', 'Latios is a dual-type Dragon/Psychic Legendary Pokémon introduced in Generation III.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b147269-kx8NVtCiXaWs.png', NULL, NULL, '江原正士', NULL, 147269, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014899', 'AN1598', 'プルリル', 'Pururill is a jellyfish-like Pokémon resembling young royalty. Regardless of gender, it has a round head with a crown-like tuft, and five tentacle-like appendages: two serving as arms and three as the lower half of its body. It has oval eyes with white pupils, and a collar around its neck. It has invisible poison spikes on its appendages. As a male Pururill, it is blue, with smooth appendages and a triangular crown. It has red eyes with blue sclerae and a straight eyelash on each eye, its collar', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b198082-mOvqew1kyPgp.png', NULL, NULL, 'たかはし智秋', NULL, 198082, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014900', 'AN1598', 'デリバード', 'Delibird is a red, penguin-like Pokémon with a white, hollow tail. Its face and chest are covered in white feathers with two, three-pointed crests above its eyes. Black markings surround its circular eyes, and it has a light yellow beak and feet. There is a single white spot on its stomach. Its feet have two digits each.  Delibird is omnivorous. It carries food bundled up in its tail. It normally gives stored food to its chicks, but has been known to share its food with humans stranded on icy mo', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b190817-F6hI788JmtGh.png', NULL, NULL, '小西克幸', NULL, 190817, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014901', 'AN1598', 'サカキ', 'Anime: Sakaki is the Rocket Team Boss and a former Tokiwa City Gym Leader. He is a very ambitious man and is intolerant of failure. Sakaki is shown to have access to vast wealth and resources. The money probably comes from Rocket Team''s main source of income — the profit of selling stolen Pokémon. Sakaki also gains a lot of money from smuggling Pokémon, Pokéball trafficking, and other crime rackets. He has Rocket Tean operations in both Kanto and Johto. He rarely meets people in person, as he pr', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b9881-eDgj9qqKOFhQ.jpg', '8月1日', 'O', '三宅健太', NULL, 9881, 'SUPPORTING', 46) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014902', 'AN1598', 'コロモリ', 'Koromori is a blue, spherical Pokémon, resembling a Honduran White Bat. It is covered in shaggy fur and has a large, piggish nose with a heart-shaped nostril. Two tufts of shaggy fur hide its eyes, and its mouth has a single fang in the center of its upper jaw. There are two relatively small, black wings on either side of its body.  Koromori''s nose serves various purposes: It uses ultrasonic waves from its nostrils for echolocation, and it can also be used to grip walls as Koromori sleeps, which', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b177129-lqFPD95TweSI.png', NULL, NULL, '古島清孝', NULL, 177129, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014903', 'AN1599', 'ドラルク', 'Draluc is an immortal higher vampire from the prestigious Dragon Clan who keeps dying and turning to dust from all kinds of small things. As his castle was destroyed, he moved in with Ronaldo, much to the other''s dismay. Draluc is a typical-looking adult vampire with pale and boney complexion, pointy ears and nose. He has round lazy eyes, short black hair that is combed backwards.', 208, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195177-yXosuPbcJag8.png', '11月28日', NULL, '福山潤', NULL, 195177, 'MAIN', 198) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014904', 'AN1599', 'ジョン', 'John is a male armadillo and a familiar of Draluc. He understands human language, but is unable to speak. As only Draluc can understand him, John uses gestures and signs to communicate with others. He gained immortality after officially becoming Draluc''s familiar.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217146-bXXuJrvBnHFB.png', '7月1日', NULL, '田村睦心', NULL, 217146, 'MAIN', 564) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014905', 'AN1599', 'ロナルド', 'A vampire hunter in his 20s with a base of operations in Shin-Yokohama. Originally not thrilled to have Draluc as a roommate, the success of the partnership in his novel series, _The Ronaldo Chronicles_, leads him to reluctantly put up with the vampire. He frequently kills Draluc when annoyed. He also has an extreme phobia of celery.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195178-rhZQGshcPlO8.png', '8月8日', NULL, '古川慎', NULL, 195178, 'MAIN', 207) ON CONFLICT DO NOTHING;
