INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014963', 'AN1599', '半田桃', 'Hinaichi''s subordinate. A dhampir and former high school classmate of Ronaldo''s. As a mama''s boy, he hates that his vampire mother is a fan of Ronaldo''s books and seeks to show her a less desirable side of the hunter. His hatred borders on obsession, his room decorated with Ronaldo posters and merchandise.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217147-0CU5dEWC2Paw.png', '7月2日', NULL, '松岡禎丞', NULL, 217147, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
