INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014970', 'AN1600', '南雲安奈', 'A member of Aobanishi High School''s Judo Club. Anna and Michi have been classmates since elementary school, and have known each other the longest. She joined the kendo club in high school and soon became a regular member, leading the Kendo Club to the national tournament. However, She could not let go of her desire to be in a club with Michi, and transferred to the judo club.  She calls herself a "prodigy" at every opportunity, but she never neglects her daily efforts and excels, both academical', 15, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n127938-5G76UvMdODHz.png', '2月25日', NULL, '稗田寧々', NULL, 127938, 'MAIN', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014971', 'AN1600', '滝川早苗', 'A member of Aobanishi High School''s Judo Club, and Michi''s best friend. Her weight class is 57kg. She is a talented girl with excellent grades and was ranked second in her junior high school class. She''s also a tutor for Michi, who isn''t good at studying, and is one of the few people who can give sharp advice to her. Sanae''s judo skills are mediocre in both physical strength and technique, but she''s tenacious and good at pulling her opponents into pinning moves.', 15, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n127937-wPw1aTiKOag3.png', '7月8日', NULL, '安齋由香里', NULL, 127937, 'MAIN', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014972', 'AN1600', '園田未知', 'The protagonist of Mou Ippon. She has an innocent personality and is not afraid to talk to anyone, and can easily get along with others. Michi is sometimes considered a bit of a nuisance by those who don''t like noisy people because she doesn''t read the atmosphere, but she is well-liked by those around her because she is able to openly and honestly recognize and praise the strength and effort of others.   Although she is small in stature, she is flexible and has a strong torso, and while her phys', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n127936-sItCB4pwyiRq.png', '2月26日', NULL, '伊藤彩沙', NULL, 127936, 'MAIN', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014973', 'AN1600', '氷浦永遠', 'The ace of Aobanishi High School''s judo club. Her weight class is 52kg. She entered Aobanishi High School, the same school as Michi, after rejecting a recommendation for a private high school, because of a match with Michi in junior high school. Hiura is a mainstay of Aonishi, recognized by both club members and Natsume, and although her body is thin, she is physically strong. She is usually reserved and reticent, but when she puts on her judo uniform, Hiura''s expression tightens up like a diffe', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n127939-Px4A7aUEywuS.png', '11月16日', NULL, '三浦千幸', NULL, 127939, 'MAIN', 17) ON CONFLICT DO NOTHING;
