INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014978', 'AN1600', '姫野紬', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b272469-3WvJylUp63MI.png', NULL, NULL, '永瀬アンナ', NULL, 272469, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014979', 'AN1600', '夏目紫乃', 'A tall female physical education teacher, and the advisor of Aobanishi''s Judo Club. Shino started judo in earnest after becoming the club''s advisor, and although she is only a shodan, she shows the strength to win forever in randori (free-style judo practice). She has mastered not only forceful, but intelligent judo as well, which is evident in her coaching.   Shino has a keen eye for not overlooking the personalities and abilities of his team members, as well as their efforts behind the scenes.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b272466-52203Rq65zCn.png', NULL, NULL, '内山夕実', NULL, 272466, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014980', 'AN1600', '天音恵梨佳', 'The ace of Kasumigaoka High School''s Judo Club, she graduated from Kawakita Junior High School and is a year older than Michi. Erika is in the 52kg class. She was Hiura''s senior at Kitakawa, and is about the same size as her.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b272467-3Y1qUqubj1BT.png', NULL, NULL, '古賀葵', NULL, 272467, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014981', 'AN1600', '妹尾緑子', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b272632-8w7YE9cycUIi.png', NULL, NULL, '長縄まりあ', NULL, 272632, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014982', 'AN1601', '竹下みいこ', 'Takeshita Miiko is a member of the group Lyrical Lily.  Miiko loves to play and she also loves her fellow members of Lyrical Lily. She is always cheerful and can be friends with anyone. She has a dream about traveling all over the world and making friends in many different countries. It is hard for others to perceive what she is thinking, but it often turns out that she''s not thinking about anything at all. She''s the type of person to have fun and laugh at haunted houses and horror movies.  (Sou', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207331-bzmgqhXDOJkX.jpg', '2月22日', NULL, '渡瀬結月', NULL, 207331, 'MAIN', 36) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014983', 'AN1601', '白鳥胡桃', 'Shiratori Kurumi is the VJ for the group Lyrical Lily.  With a cheerful personality, Kurumi loves fun things. Bored of being in a strict school for children of rich and prestigious families, Kurumi is always looking for ways to work some kind of mischief. Although she is grateful to Miyu for helping her out of trouble and Kurumi feels like she owes a lot to her, she has no intention of stopping her antics.  (Source: D4DJ Fandom Wiki)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207329-MJPxW3wSljkW.png', '11月12日', NULL, '深川瑠華', NULL, 207329, 'MAIN', 80) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014984', 'AN1601', '桜田美夢', 'Sakurada Miyu is the vocalist for the group Lyrical Lily.  Miyu is a kind-hearted and thoughtful high school student with good morals. She started her DJ activities when she came across some analog equipment with Haruna, Kurumi and Miiko. She loves singing and is well-versed in popular songs from the Showa era, as well as nostalgic music due to her family''s influence.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b204572-oNh22HqspcjM.png', '12月14日', NULL, '反田葉月', NULL, 204572, 'MAIN', 78) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014985', 'AN1601', '春日春奈', 'Kasuga Haruna is a member of the group Lyrical Lily.  Haruna is an earnest girl who belongs to her high school''s disciplinary committee. Her softhearted nature always gets her involved in all sorts of trouble. She acts as though she is not interested in DJ activities, but the audio fanatic side of her is brimming with excitement.  (Source: D4DJ Fandom Wiki)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207328-hQeEmeimSlDm.png', '5月25日', NULL, '進藤あまね', NULL, 207328, 'MAIN', 56) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014986', 'AN1601', '愛本りんく', 'Position: Vocals  Rinku is a member of Happy Around!  Rinku lived abroad in Africa as a child due to her parents'' work, but she came back to Japan alone for high school and now lives with her grandmother. She is always cheerful and optimistic. Calling even nature her friend, she can sometimes be seen as an oddball. She became interested in DJing from her encounter with Maho.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b168296-nNmy7rh5HpIT.png', '6月30日', 'O', '西尾夕香', NULL, 168296, 'SUPPORTING', 190) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014987', 'AN1601', '花巻乙和', 'Position: Vocals/Performer  Towa is a member of Photon Maiden.  Towa actively attends the local festivals due to her family''s participation in the local youth organization. Once, a photo of her at a local event went viral on social media. As a huge idol enthusiast, she still goes to idol concerts and tries to learn from their performances.  (Source: D4DJ Fandom)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b189099-S9ESBXvDJxBJ.png', '1月30日', 'O', '岩田陽葵', NULL, 189099, 'SUPPORTING', 77) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014988', 'AN1601', '小舟柳人', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b189829-Zu4h63Lm5vCT.png', NULL, NULL, '古谷徹', NULL, 189829, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014989', 'AN1601', '渡月麗', 'Position: Vocals/Keyboard  Rei is a member of Happy Around!  Born into a wealthy family, Rei had lessons in all sorts of activities in which she showed the most talent at piano. She felt oppressed living the life her parents had prepared for her, but didn''t have the courage to make a change. When she met Rinku unexpectedly, change began to brew inside her.  Rei is noted to be skilled in songwriting, and the music Maho develops often stems from melodies created by Rei.  (Source: D4DJ Fandom)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b182715-94nZ9Nn7m65p.png', '10月30日', 'O', '入江麻衣子', NULL, 182715, 'SUPPORTING', 152) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014990', 'AN1601', '瀬戸リカ', 'Rika a member of the group Merm4id.  Holding "Life is to enjoy!" as her motto, Rika leads a positive university life. Loves to dance and sing with her friends at parties. She starts her DJ activities with her best friend Marika along with Saori and Dalia who she met by chance. She is a gifted individual who overcomes anything with luck and charm.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b204568-rdPlB3qEdpJl.png', '8月30日', NULL, '平嶋夏海', NULL, 204568, 'SUPPORTING', 107) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014991', 'AN1601', '矢野緋彩', 'Yano is a member of the group RONDO.  Hiiro is a sleek university student with a mature atmosphere. As a VJ, her knowledge in art allows her to build the unique worldview of the unit. Since she majors in psychology, she acts as the counselor of the unit and listens to the members'' consultations, but scolds anyone who becomes too selfish.  (Source: D4DJ Wikia)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206282-YkdRvbE2tayr.png', '3月23日', NULL, 'もものはるな', NULL, 206282, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014992', 'AN1601', '天野愛莉', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b189832-OxrXdAYeatLw.png', NULL, NULL, '水樹奈々', NULL, 189832, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014993', 'AN1601', '明石真秀', 'Position: Vocals/DJ  Maho is a member of Happy Around!  Deeply moved by a DJ performance had seen in the past, Maho became immersed in DJ activities herself. Recently she has been trying track-mixing as well. She was persuaded by Rinku to form a unit. Although she is sometimes bewildered by Rinku''s eccentric actions, she continues to improve her performance as a DJ.  (Source: D4DJ Fandom)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b168297-LMkkRWrFF3YT.png', '9月20日', 'A', '各務華梨', NULL, 168297, 'SUPPORTING', 169) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014994', 'AN1601', '出雲咲姫', 'Position: DJ/Vocals  The DJ and lead vocals of the unit Photon Maiden.  Saki is a talented girl who excels in both study and sports. Having "synesthesia", she can see color in music. A DJ concert she happened to attend made her want to become a DJ herself. She is a person of few words, but shows outstanding performance on the stage.  (Source: D4DJ Fandom)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b189100-J52DBsSr4wGS.png', '5月10日', 'AB', '紡木吏佐', NULL, 189100, 'SUPPORTING', 167) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014995', 'AN1601', 'ローラ・ブラッドリー', 'A famous producer and track-maker from the United States.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b298039-oLhsuYWJrT1Z.png', NULL, NULL, '内田秀', NULL, 298039, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014996', 'AN1601', '大鳴門むに', 'Position: Vocals/VJ  Muni is a member of Happy Around!  Rinku praised Muni''s drawing when they were young, and as a result she began to take drawing seriously. Now she has attracted attention on the internet as a renowned illustrator. She acts very affectionate to people who acknowledge her, but does not let her guard down with others.  Muni occasionally refers to herself as “The one and only Muni-chan” (唯一無二のむにちゃん, "Yuiitsu Muni no Muni-chan")  She has a cat-shaped MP3 player named "Nyochio" th', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b182716-i1Ujwd9j501q.png', '3月3日', 'B', '三村遙佳', NULL, 182716, 'SUPPORTING', 201) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014997', 'AN1601', '日高さおり', 'Saori is a member of the group Merm4id.  Saori started her DJ career in high school, and due to her hardworking nature, she''s built up a certain level of technique. She decided to become a DJ after listening to a remix made by a person who worked at the club FROLIC. Her pessimistic thinking held her back from DJing actively, even as a university student. Rika forced her to join the unit, but has made up her mind to change her mentality and achieve her goals. She is the one who always stops Rika ', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206240-U6nztNhHF2lN.png', '11月27日', NULL, '葉月ひまり', NULL, 206240, 'SUPPORTING', 80) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014998', 'AN1601', '青柳椿', 'Tsubaki is a member of the group RONDO.  Tsubaki was asked to join the DJ unit, which was lacking a vocalist, by Aoi, and quickly attracted attention as soon as she joined. A born vocalist who has been humming melodies for as long as she can remember. She may have a strong attitude, but she hates to be alone.  (Source: D4DJ Fandom)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b204570-FZsOYJJxOfo3.png', '1月7日', NULL, '加藤里保菜', NULL, 204570, 'SUPPORTING', 99) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014999', 'AN1601', '海原ミチル', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b298334-n0BpCye1LMjU.png', '1月23日', NULL, '小岩井ことり', NULL, 298334, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015000', 'AN1601', '山手響子', 'Position: Vocals/DJ  Kyouko is a member of Peaky P-key.  Born and raised in a musical family, she has a natural talent for music but spares no effort to improve her performance. She finds herself strangely attracted to Happy Around''s energetic performances.  (Source: D4DJ Fandom)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b182718-VmPx0Pii6F5P.png', '4月27日', 'B', '愛美', NULL, 182718, 'SUPPORTING', 188) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015001', 'AN1601', '犬寄しのぶ', 'Position: DJ  Shinobu is a member of Peaky P-key.  Shinobu is the DJ and brains of Peaky P-key. She and Kyouko are childhood friends, and they have a strong trust in each other. A very skilled DJ, also excels in remixing and track-making. Her hobby is online games, in which she is also famous. She is a very picky eater, and her diet is that of a young child. She is very arrogant, but has the most common sense in the unit.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b189830-6tdOgOhvtjLb.png', '2月4日', 'A', '高木美佑', NULL, 189830, 'SUPPORTING', 111) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015002', 'AN1601', '水島茉莉花', 'Marika is a member of the group Merm4id.  Marika is an easygoing girl with a comforting atmosphere. Besides being a university student, she also works as a model. She was the center of attention upon entering university, but she became friends with Rika, who was able to talk to her despite all the attention. She has a calm personality, but loves concerts and is dedicated to her DJ activities.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206238-DfI0hmfcAIKT.png', '7月30日', NULL, '岡田夢以', NULL, 206238, 'SUPPORTING', 55) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015003', 'AN1601', '福島ノア', 'Position: Vocals/Performer  Noa is a member of Photon Maiden.  Noa became interested in theater plays through her love of literature, and decided to become a performer when she was praised at a theater workshop. Very curious and full of knowledge, she becomes talkative when it comes to things she''s interested in. She loves cute things.  (Source: D4DJ Fandom)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b189097-HQwqEwhSB46H.png', '10月9日', 'A', '佐藤日向', NULL, 189097, 'SUPPORTING', 103) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015004', 'AN1601', '松山ダリア', 'Dalia is a member of Merm4id.  Dalia devotes herself to practicing ballet, traditional Japanese dance, contemporary dance, and any other dance form in order to become a genre-exceeding dancer. She sees something that she lacks in Rika''s positivity, and decides to join the unit. She is also a grade holder in martial arts, and acts as the bodyguard of the unit. She has a cool personality, and is able to stay calm during most situations.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206241-W8wkZn1QOaoj.png', '6月1日', NULL, '根岸愛', NULL, 206241, 'SUPPORTING', 67) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015005', 'AN1601', '清水絵空', 'Position: Chorus/Performer  Esora is a member of Peaky P-key.  Esora is the self-proclaimed "lovely" member of Peaky P-key. As a natural-born entertainer, she joined the unit to bring entertainment to everyone. She is even willing to expend her own fortune to achieve this goal. She is skilled at getting people to let their guards down and speak their minds.  (Source: D4DJ Fandom)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b189833-yulbGlcrJfij.png', '9月9日', 'A', '倉知玲鳳', NULL, 189833, 'SUPPORTING', 82) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015006', 'AN1601', '三宅葵依', 'Miyake is a member of the group RONDO.  Aoi is a DJ that performs exclusively for a members-only club, "Alter-Ego", which has a long history. Her androgynous looks attract many fans. She became captivated by Tsubaki''s vocals and asked her to form a DJ unit. Usually she wears a poker face and doesn''t show her true emotions, but she opens up her heart to her unit members.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206288-okUpPp8tGnDr.png', '7月7日', NULL, 'つんこ', NULL, 206288, 'SUPPORTING', 119) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015007', 'AN1601', '笹子・ジェニファー・由香', 'Position: VJ/Chorus  Yuka is a member of Peaky P-key.  Yuka is the moodmaker of Peaky P-key. She met Kyouko as she was searching for the "perfect snapshot" to capture with her camera and decided to join the unit as a VJ. Raised by parents who work as gym trainers, she is very cheerful and kind to everyone.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b189828-BIzGBAMLk4rn.png', '12月5日', 'A', '小泉萌香', NULL, 189828, 'SUPPORTING', 45) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015008', 'AN1601', '月見山渚', 'Nagisa is a member of the group RONDO.  Nagisa is a guitarist who grew up in a rock music-loving family. She came across the club where Aoi performed as a DJ when she was searching for a place to practice, and often visits Hiiro''s house as well. She can be shy around strangers, but honors friendship more than anything else.  At the same time, she can be noticeably open or even playful with her close people, whom she trusts enough. Notable examples include her friendly behavior with Saori during ', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206279-zEFtdJFtgZKi.png', '8月15日', NULL, '大塚紗英', NULL, 206279, 'SUPPORTING', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015009', 'AN1601', '新島衣舞紀', 'Position: Vocals/Performer  Ibuki is a member of Photon Maiden.  Ibuki loves to move her body and has participated in many sports since childhood. In junior high, she became hooked on the joy of dancing and singing and started to attend a show production school. Never forgetting to care for others, she is a leader in both name and reality.  (Source: D4DJ Fandom)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b189098-swRofcVQaIvz.png', '4月10日', 'A', '七木奏音', NULL, 189098, 'SUPPORTING', 63) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015010', 'AN1602', '夕凪ツバサ', 'A bird from the Puni Bird Tribe. He dreams of being able to fly, so he studies aerodynamics very hard in order to make it happen. Tsubasa is a hard worker and vows to protect Ellee-chan.', 12, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b296117-sdW0jB0kG3v5.png', '5月21日', NULL, '村瀬歩', NULL, 296117, 'MAIN', 124) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015011', 'AN1602', 'ソラ・ハレワタール', 'An athletic girl from the floating kingdom in the sky, Sky Land. Sora has trained hard everyday to become a hero like the person of her dreams who saved her when she was a child. She and Eru are staying at Mashiro''s house in Sorashido City. Sora transforms into the Precure of the Sky, Cure Sky.', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b296116-p81b1Ua0QVXb.jpg', '9月20日', 'A', '関根明良', NULL, 296116, 'MAIN', 202) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015012', 'AN1602', '聖あげは', 'Ageha is kindhearted, sisterly and has a soft spot for younger children. Her childhood friend is Nijigaoka Mashiro and she acts as an older sister to her.', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b296119-0fONDsuwGOd9.jpg', '8月8日', 'B', '七瀬彩夏', NULL, 296119, 'MAIN', 135) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015013', 'AN1602', '虹ヶ丘ましろ', 'A girl who lives in Sorashido City. Mashiro is a gentle and kind girl, who knows a lot about cooking and nature. She lives with her grandmother, Yoyo, as her parents are working overseas.   Mashiro transforms into the Precure of Light, Cure Prism.', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b296118-WiyZx4Qv4zNn.jpg', '7月16日', 'AB', '加隈亜衣', NULL, 296118, 'MAIN', 176) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015014', 'AN1602', 'エルちゃん', 'A young princess from Sky Land. Ellee-chan came to Sorashido City with Sora after she had been kidnapped. She has the power to create the Sky Tones, which allows the Pretty Cures the ability to transform. Ellee-chan loves to say "Eru~!"', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b296120-ZC0FJZCgDkJG.png', '3月12日', NULL, '古賀葵', NULL, 296120, 'MAIN', 44) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015015', 'AN1602', '長内たける', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b316599-BVOAHUiTNOg1.jpg', NULL, NULL, '小平有希', NULL, 316599, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015016', 'AN1602', 'カバトン', 'A tough guy from the Underg Empire. He believes that the strong are always right. His catchphrase is "I''m TUEEE!"   He currently lives somewhere in Sorashido City.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b298014-ko4pZAcl6OCQ.jpg', NULL, NULL, '間宮康弘', NULL, 298014, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015017', 'AN1602', 'スキアヘッド', 'A general from the Undergu Empire and Empress Undergu''s right-hand man.', 300, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b323183-z78RtMEa7ZZj.jpg', NULL, NULL, '宮本充', NULL, 323183, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015018', 'AN1602', 'ランボーグ', 'A selfish and violent monster that has been possessed by Underg Energy.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b298018-L2LAIv7q9rAG.jpg', NULL, NULL, '相馬康一', NULL, 298018, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015019', 'AN1602', 'バッタモンダー', 'A general from the Undergu Empire. Battamonda is an egocentric and laid-back villain, who doesn''t like getting physical with his enemies, instead using Ranborgs to do the fighting for him. He also prefers not to touch weaklings, thinking they''re not worth the effort. Battamonda has a short temper but quickly reverts back to being calm and sultry when he realizes he''s angry.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b307275-esh3Fg5ObNKR.jpg', NULL, NULL, 'KENN', NULL, 307275, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015020', 'AN1602', 'ミノトン', 'Minoton is a general from the Undergu Empire, and a villain from *Hirogaru Sky! Pretty Cure*. He is a hot-blooded and prideful warrior who prefers to fight fairly.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b323292-vUOZN8Hut0g0.jpg', NULL, NULL, '酒井敬幸', NULL, 323292, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
