INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015023', 'AN1602', '虹ヶ丘ヨヨ', 'Mashiro''s grandmother, and a well known scholar back in Sky Land.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301433-1j3PE9oFeJ7y.png', NULL, NULL, '塩田朋子', NULL, 301433, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015024', 'AN1602', 'べリィベリー', 'A member of Sky Land''s Azure Guard. Beryberie is a hot-headed girl who doesn''t like weaklings, as she thinks they''ll get in the way. She is a hard worker, who did her very best to end up where she is today. However, she does respect those who treat her kindly with gratitude and admiration.  When Beryberie was little, she injured her arm badly. This caused her to fail the test to join the Azure Guards for three years. But she worked harder than anyone, and became strong.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b304905-mzotSIunzI76.jpg', NULL, NULL, '松田颯水', NULL, 304905, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015025', 'AN1602', '国王', 'The king of Skyland.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b298013-FzWmuDBcZEyj.jpg', NULL, NULL, '一条和矢', NULL, 298013, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015026', 'AN1602', 'シャララ', 'Shalala is the captain of the Azure Guards, and the strongest swordfighter in Skyland. She has a very strong sense of justice, and takes her missions seriously. She is a calm and kind-hearted woman, who is sympathetic about others.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b304906-g5k5E8BzB6q3.jpg', NULL, NULL, '斎賀みつき', NULL, 304906, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
