INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015045', 'AN1604', 'オーフェン', 'Hair: Brown Eyes: Brown Height: 171 cm Weight: 61 kg   Orphen is the main male lead. Fans claim "he comes off as a ''badass'' kind of guy", because of his apparent lack of emotions, dedication to finish what he is working on as soon as possible (his eagerness to stop helping people he feels he doesn''t have to help), and his ''coldness'' towards people he doesn''t know. He is partly an anti-hero throughout the entire series. The only time his attitude changes is when the subject of Azalie is brought u', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n1411-dKMaZJPRUXLW.jpg', NULL, 'O', '森久保祥太郎', 171, 1411, 'MAIN', 87) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015046', 'AN1604', 'クリーオウ・エバーラスティン', 'She is the tomboyish, feisty main female lead. Her father had inherited the Sword of Balthanders, and Orphen needed the sword. She accompanies him on his journey, allowing him to take the sword (as it was just an ornament to her, knowing nothing of its power), claiming that she is only coming to "make sure he doesn''t harm her investment".  (Source: Wikipedia)', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b5758-qqcFHAAlNEQI.png', '9月27日', NULL, '大久保瑠美', NULL, 5758, 'MAIN', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015047', 'AN1604', 'マジク・リン', 'Majic Lin is the apprentice of Orphen, and the second-male lead. Majic deals with the torment from both Cleao and Orphen on their journey together to save Azalie. His father is paying Orphen to teach him, which at first seems a waste of money to his father. When Orphen repairs a glass that fell with his magic, before the father''s eyes, the father''s opinion about his money being "thrown out the window" disappears.  (Source: Wikipedia)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b5656-DgU1N9wT0ury.png', '3月25日', NULL, '小林裕介', NULL, 5656, 'MAIN', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015048', 'AN1604', 'ボルカン', 'Dortin and Volkan are often viewed as comic relief throughout the series. Volkan is the one with the plans - the very bad plans, that is. He hates Orphen (whom he refers to as &quot;the black wizard&quot;) and his companions, and always finds a way to ruin whatever they had in mind. He is also very annoying to Orphen. It is his fault that Orphen often must use his magic on them to make them go away - them, being him and Dortin. Volkan wants power, and money. Any scheme he has in mind has the end', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/1406.jpg', NULL, NULL, '水野まりえ', NULL, 1406, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015049', 'AN1604', 'ドーチン', 'Dortin is the voice of reason (that is never paid any attention to) on his and Volkan''s quests. He is kind and knowledgable, though something of a nerd. When Volkan messes up, Dortin always tries to tell Orphen he had no part in Volkan''s schemes, but they both wind up being victim''s of Orphen''s magical blasts anyway. (from Wikipedia)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b1407-T2MBA450E3Zm.png', NULL, NULL, '渕上舞', NULL, 1407, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015050', 'AN1604', 'ロッテーシャ', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b288233-5yNQx2cQq1aQ.jpg', NULL, NULL, '青木志貴', NULL, 288233, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
