INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015052', 'AN1604', 'レキ', 'Leki is a supporting character in Sorcerous Stabber Orphen. Being a Deep Dragon, Leki looks like a wolf with black fur (blue in the 1998 anime) and green eyes.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214763-j3jVm8oim6gg.png', NULL, NULL, NULL, NULL, 214763, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
