INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015061', 'AN1607', '黒死牟', 'Combat Style:   Kokushibo is a member of the Twelve Demon Moons, holding the position of Upper Moon One.', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141918-Bfgq88XJFOPz.png', NULL, NULL, '置鮎龍太郎', 190, 141918, 'SUPPORTING', 1091) ON CONFLICT DO NOTHING;
