INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015063', 'AN1607', '童磨', 'He is Upper Moon Two, making him the third-strongest demon after Muzan and Upper Moon One. He has a very friendly attitude, and fights with a pair of metal fans. He is the founder of a cult known as the "Eternal Paradise Cult," and eats his followers, allegedly in order to release them from the pain of living.', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b144591-v2yrXtHorZFS.png', NULL, NULL, '宮野真守', 187, 144591, 'SUPPORTING', 1231) ON CONFLICT DO NOTHING;
