INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015083', 'AN1608', '牡丹', 'Race: Tensen Tao Attribute: Earth Occupation: Ruler of Kotaku Affiliation: Lord Tensen  Mu Dan is a member of Lord Tensen, as well as one of the rulers of Kotaku.  Mu Dan has a cheerful, yet very sadistic attitude. He is very blunt with his words and is not afraid to tell his enemies what they want because of the confidence in his own power. Mu Dan views humans as simply research material and "toys" that he can do whatever he wants with.  He seems to get along quite well enough with the other Te', 1000, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b148753-yLtDQsR4vB4f.png', '9月1日', NULL, '甲斐田裕子', NULL, 148753, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
