INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015157', 'AN1612', '佐々木瑛太', 'Sasaki is the older brother of Runa Sasaki. He is also Yamada-kun''s senpai back in their hometown. His hobby is playing video games. He also plays the game Forest of Savior (FOS) and is also a member of the guild [Chocolate Rabbit].', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199121-8PgP309K6DkU.png', '6月11日', NULL, '花江夏樹', NULL, 199121, 'SUPPORTING', 463) ON CONFLICT DO NOTHING;
