INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015168', 'AN1613', 'リリアン ・ ワインバーグ', 'A famous American diva and songstress whose name is known by the whole world. Her passion in adventuring lead her aboard the International Space Station (ISS) alongside Senku''s father, Byuakuya Ishigami.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149274-lYJFmrdqT7Hq.jpg', '10月1日', 'A', NULL, NULL, 149274, 'SUPPORTING', 175) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015169', 'AN1613', '礁', 'One of the older members of Ishigami Village. He is the village''s top fisherman, almost never shown away from fish or boats. He is married to Sango, and is frequently shown hanging out with the other elders, especially Alumi and Natri.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301927-FYIUeqg4w1qn.jpg', NULL, NULL, '相馬康一', NULL, 301927, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
