INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015172', 'AN1613', 'コクヨウ', 'Father of Kohaku and Ruri. He was the village chief of Ishigami Village at the time of Senku''s reawakening.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b150509-6LyHh2A6wVyc.jpg', '4月19日', 'B', '金尾哲夫', NULL, 150509, 'SUPPORTING', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015173', 'AN1613', 'シャミール・ヴォルコフ', 'Shamil was a Russian Cosmonaut residing on the International Space Station (ISS) when the Petrification on Earth''s surface occurred. He returned to Earth''s surface along with the rest of the ISS crew, helping to establish Ishigami Village. After returning to Earth, Shamil married fellow ISS astronaut Connie Lee and had several children together. His personality was the opposite of Byakuya''s, being a stoic, serious, pragmatic man of few words.', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b150497-e3XqWcXpTp4I.jpg', '3月9日', 'B', '森久保祥太郎', 180, 150497, 'SUPPORTING', 76) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015174', 'AN1613', 'あるみ', 'Villager from Ishigami Village. She is the mother of Carbo and the wife of Natri.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255671-WYQN6b3Xx7ff.png', NULL, NULL, '所河ひとみ', NULL, 255671, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015175', 'AN1613', 'ダリヤ・ニキーチナ', 'Russian cosmonaut and doctor who was on board the International Space Station (ISS) alongside her husband Yakov Nikitin. While in space, she witnessed the petrification of all human life on Earth''s surface.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b150498-lNfkfOS4Stgi.jpg', '3月6日', 'B', '田中理恵', 163, 150498, 'SUPPORTING', 36) ON CONFLICT DO NOTHING;
