INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015179', 'AN1613', 'ジャスパ', 'An inhabitant of Ishigami Village who is a stickler for the rules. He serves alongside Turquoise as guard for the village''s priestess.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b147640-ljghkxCRasNI.jpg', NULL, 'A', '竹内良太', NULL, 147640, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
