INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015183', 'AN1614', '金生谷倫', 'The girl that accidentally hit Yamada in the face with a basketball.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b306771-PoYfabeTiS4o.png', NULL, NULL, '芹澤優', NULL, 306771, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015184', 'AN1614', 'Lucifer Nigorikawa', 'Lucifer Nigorikawa is a figment of Ichikawa''s imagination in Boku no Kokoro no Yabai Yatsu.  Not quite a real "character" per se, Nigorikawa is an imaginary figure that Ichikawa conjures up to help himself deal with his emotional shortcomings. He is largely based off of Nigorikawa-kun, the male lead of Yamada''s favorite shoujo manga, Your Color''s Octave. The "Lucifer" moniker and the associated black wings he sometimes sprouts are additions from Ichikawa''s chuunibyou delusions.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b306772-6CcMAQGLsPFy.png', NULL, NULL, '福山潤', NULL, 306772, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015185', 'AN1615', '天上優夜', 'Yuuya Tenjou is the main protagonist of the series. Located in his grandfather''s secret room, Yuuya came across a door leading to another world, Argena, where he gained his powers. Being able to go back and forth between Earth and Argena, Yuuya became extrodinary in both worlds.', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b192860-E2kX3ctHLf4g.jpg', NULL, NULL, '松岡禎丞', NULL, 192860, 'MAIN', 343) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015186', 'AN1615', '宝城佳織', 'The daughter of Ousei Academy''s chairman, Tsukasa Houjou, Kaori Houjou was saved by Yuuya Tenjou when she was harrased by strangers near a convenience store. With her recommendation, she was the reason behind his acceptence into Ousei Academy.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b192862-82vHVNphCQ4Y.jpg', NULL, NULL, '鬼頭明里', NULL, 192862, 'MAIN', 306) ON CONFLICT DO NOTHING;
