INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015213', 'AN1615', '翔', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b303347-kRwe5AWeosmc.jpg', NULL, NULL, '堀金蒼平', NULL, 303347, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015214', 'AN1616', '四宮かぐや', 'The vice president of the student council of Shuchiin Academy, member of the wealthy Shinomiya family, she is a multi-talented genius who can do anything if she sets her mind to it. Due to the way she was raised, she instinctively looks down on others and thinks of ways to use them for her own benefit. Kaguya rarely interacted with other people before she joined the student council, but that has begun to change. She is an incredibly sheltered girl, resulting in her lacking in several pieces of w', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b120649-NPaWaIpWy60E.png', '1月1日', 'AB', '古賀葵', 158, 120649, 'MAIN', 21380) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015215', 'AN1616', '白銀御行', 'He is a second year student at Shuchi''in Academy and the president of the student council.  Miyuki is a handsome young man with blond hair and blue eyes. Due to his constant sleep deprivation and nearsightedness, his eyes appear to glare. He usually wears the regular Shuchi''in Academy black male uniform adorned with the Aiguilette, the golden chain-like accessory around his neck. The Aiguilette symbolizes his authority as student council president.  Shirogane is a diligent student who, despite h', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121101-Q8HzKP15At2d.png', '9月9日', 'O', '古川慎', 175, 121101, 'MAIN', 9613) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015216', 'AN1616', '四条眞妃', 'Maki is a classmate and friend of Nagisa. She has short hair styled in short pigtails. She is friends with Nagisa and is secretly jealous of Nagisa''s relationship with her boyfriend, as she too liked Kashiwagi''s Boyfriend, but could not confess before. As a branch member of the Shinomiya clan, she is Kaguya''s second cousin twice removed so she sometimes refers to Kaguya as "Auntie". Miyuki and Yuu observe she acts very tsundere (cold on the outside but wanting to be affectionate), and similar to', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134328-s3cEgqb5MEbh.png', '1月1日', 'AB', '市ノ瀬加那', NULL, 134328, 'SUPPORTING', 842) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015217', 'AN1616', '子安つばめ', 'Tsubame is a third-year student who is vice-captain of the cheer squad and a rhythmic gymnast. She is very popular. She encourages Yuu in the cheering activities.', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134326-GOZE06QSlJSb.png', '4月4日', 'A', '福原遥', NULL, 134326, 'SUPPORTING', 421) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015218', 'AN1616', '大仏こばち', 'Kobachi is Miko''s classmate with the glasses and a member of the disciplinary committee. She has been looking after Miko for over 10 years.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134331-pGWnRI42SZAl.png', '6月6日', 'B', '日高里菜', NULL, 134331, 'SUPPORTING', 123) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015219', 'AN1616', '藤原千花', 'The secretary of the Shuchiin Academy student council. She could not be predicted, her thoughts could not be read. A natural disaster who unconsciously threw everything into chaos simply by being present, also known as Subject F.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121103-UGLxT8utLPnq.png', '3月3日', 'O', '小原好美', NULL, 121103, 'SUPPORTING', 16994) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015220', 'AN1616', '石上優', 'The treasurer of the student council of the Shuchiin Academy. He''s extremely valued by Miyuki, given that he single-handedly manages all the school''s funds. He''s also terrified of Kaguya, though no one else is sure why that is. Yuu keeps to himself and rarely speaks up, often getting into trouble when he does. He has a depressed outlook on life while having an inferiority complex. In contrast to his attitude, he is willing to help those in need and will sacrifice his pride if need be. Unlike his', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121102-tiQFxnSEIAwm.png', '3月3日', 'O', '鈴木崚汰', NULL, 121102, 'SUPPORTING', 15360) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015221', 'AN1616', '白銀圭', 'Kei Shirogane is Miyuki Shirogane''s little sister. She attends Shuchiin middle school and is the treasurer for the middle school student council.  She is a hard worker just like her brother and can be very prideful at times. She also inherited his sense of righteousness and hates it when someone doesn''t do the right thing in a given situation. Like her brother, she likes helping out those who are in trouble even if it means going out of her way to do it. Since she grew up in a family that places', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126144-4fc2sYUVFKOJ.png', '8月1日', 'B', '鈴代紗弓', NULL, 126144, 'SUPPORTING', 1854) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015222', 'AN1616', '伊井野ミコ', 'She is a freshman at Shuchiin Private Academy and the Auditor of the Student Council. Miko has a strong sense of justice and will correct others on what''s right and wrong. Unfortunately, this led to her being bullied, though she still continues to uphold her idea of "right". She idolizes Chika Fujiwara, listening to anything she says, even if it''s for Chika''s enjoyment.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125886-TQbmqAaSgBLS.png', '5月5日', 'O', '富田美憂', 147, 125886, 'SUPPORTING', 15658) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015223', 'AN1616', '藤原萌葉', 'Moeha is Chika''s little sister who is in junior high. She is the student council vice-president at the junior high. She admires Miyuki as well and hopes to confess someday. She has a habit of voicing dark ideas, which unnerve Kaguya a great deal.', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134329-cRdrf5BqmIVk.png', '6月26日', 'AB', '小澤亜李', NULL, 134329, 'SUPPORTING', 107) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015224', 'AN1616', '田沼正造', 'Shouzou Tanuma is a world famous heart surgeon and the physician of the Shinomiya family. He is also Tsubasa''s grandfather', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b177066-ZHk7nsy5wDcn.jpg', NULL, NULL, '森田順平', NULL, 177066, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015225', 'AN1616', '柏木渚', 'Nagisa is a classmate who occasionally asks Kaguya about what to do in her relationships. Tsubasa''s girlfriend.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134330-2b7ad7GPw1Wl.png', '6月25日', 'B', '麻倉もも', NULL, 134330, 'SUPPORTING', 149) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015226', 'AN1616', '龍珠桃', 'Momo Ryuuju is a supporting character in the series. She is the president of the Astronomy Club and one of The Impossible Girls. As a member of a yakuza family, she places little value on the school rules, as seen by her wearing a hat and playing games on her cellphone while on school grounds. She also has a short temper, and others view her as being threatening.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212390-cCppoJIBYxyA.jpg', NULL, NULL, '早見沙織', NULL, 212390, 'SUPPORTING', 48) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015227', 'AN1616', '巨瀬工リカ', 'She is a member of the mass media club at Shuchi''in Academy.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126986-Pcspig2orfPq.png', NULL, NULL, '朝井彩加', NULL, 126986, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015228', 'AN1616', '田沼翼', 'He is a student in Shuchi''in highschool and always asks Miyuki Shirogane for advice about love. Kashiwagi''s boyfriend.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134327-5tqYKvBaqRe2.png', '8月25日', 'A', '八代拓', NULL, 134327, 'SUPPORTING', 40) ON CONFLICT DO NOTHING;
