INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015230', 'AN1616', '紀かれん', 'She is a member of the mass media club at Shuchi''in Academy.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126987-sWw4vqsdHNWe.png', NULL, NULL, '朝日奈丸佳', NULL, 126987, 'SUPPORTING', 60) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015231', 'AN1616', '早坂愛', 'Ai Hayasaka is a second-year student at Shuchiin Academy and a valet of the Shinomiya family. She is a member of the Hayasaka family, who have served the Shinomiya family for generations, gaining their trust.  Having been personally assigned to enter Shuchiin Academy with her, Ai supports Kaguya Shinomiya in her high school life and has been a part of Kaguya''s life for ten years. Because of their close relationship, Ai is one of the few people around to which Kaguya''s amiability is not an act.  ', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121104-7TYRl3EEsDYU.png', '4月2日', 'AB', '花守ゆみり', NULL, 121104, 'SUPPORTING', 11361) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015232', 'AN1616', '生前徒会長', 'The Previous Student Council President (real name unknown) is a supporting character in the series. He is a third-year high school student at Shuchi''in Academy and the president of the 66th Student Council.  He is a third year student at Shuchi''in Academy and was the president of the School Council when Miyuki Shirogane was in his first year.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212389-M0QAzDPJvn7Z.jpg', NULL, NULL, '島﨑信長', NULL, 212389, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015233', 'AN1617', '岩倉美津未', 'First-year high school student who moved to Tokyo from the outskirts of Ishikawa Prefecture near Suzu. Raised a child prodigy, she entered high school at the top of her class; however, she has no athletic ability. Her pure personality unintentionally influences the people around her. She has a younger sister and brother.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b138851-KqCx4CjktnPl.png', '3月3日', NULL, '黒沢ともよ', NULL, 138851, 'MAIN', 2638) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015234', 'AN1617', '志摩聡介', 'Mitsumi''s classmate who is popular with girls. He is known for sabotaging the entrance ceremony and skipping classes. Though he planned to skip the entrance ceremony, he meets Mitsumi and they run to school together.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b138850-eqwZ11Q6sLrl.png', '10月9日', NULL, '江越彬紀', NULL, 138850, 'MAIN', 1592) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015235', 'AN1617', '遠山文乃', 'Fumino is Mitsumi''s childhood friend. She remains in Ishikawa while Mitski attends high school in Tokyo. Despite the distance, the two remain best friends, frequently catching up over video calls, and confiding in each other.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b234805-L7wiQWESaCyy.jpg', NULL, NULL, '諸星すみれ', NULL, 234805, 'SUPPORTING', 104) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015236', 'AN1617', 'ナオ', 'Mitsumi''s paternal aunt. She is a transgender woman and works as a stylist. Mitsumi''s guardian since she moved to Tokyo.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b234811-a4qkRQwypnnY.png', NULL, NULL, '斎賀みつき', NULL, 234811, 'SUPPORTING', 435) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015237', 'AN1617', '村重結月', 'Mitsumi''s classmate and her first friend in Tokyo. Her popularity among boys made her develop a complex about being shunned by other girls. She studied abroad in her childhood and has blonde hair, so people assume she is good at English, but according to herself she is not that good at it.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b138849-NAyVfRTuUi1B.png', '12月11日', NULL, '内田真礼', NULL, 138849, 'SUPPORTING', 909) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015238', 'AN1617', '迎井つかさ', 'Mitsumi''s classmate and Sousuke''s friend since middle school. He is quiet and kindhearted.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b234809-bmTuzvphzAHl.png', '5月19日', NULL, '田中光', NULL, 234809, 'SUPPORTING', 41) ON CONFLICT DO NOTHING;
