INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015243', 'AN1617', '久留米誠', 'Mitsumi''s classmate. She is introverted and worries about becoming isolated; she meets Mitsumi when she joined the student council to join some kind of community. Despite not liking flirtatious people, she meets Yuzuki through Mitsumi and they become close friends.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b234806-IFZjaw0mSNJJ.png', '4月17日', NULL, '潘めぐみ', NULL, 234806, 'SUPPORTING', 213) ON CONFLICT DO NOTHING;
