INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015262', 'AN1620', '崎宮ミサキ', 'Misaki Sakimiya, known professionally as Zaki, is the former heiress to Sakimiya Steel and the assassin hired to kill the original Polka Shinoyama. In the aftermath of her own premature murder and subsequent resurrection as a Zombie—respectfully the accidental and purposeful doing of the Corpse God—she moves in with the Corpse God and assists him with his fortune-telling endeavors. Misaki has since evolved to become a Vampire Larva per the Corpse God''s magic, her newfound powers allowing her to ', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205705-FkNqE6Ipy84w.png', NULL, NULL, '水瀬いのり', NULL, 205705, 'MAIN', 388) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015263', 'AN1620', '屍神殿', 'The Corpse God (屍神殿 Kabane Shinden), later known as Polka Shinoyama (四乃山ポルカ Shinoyama Poruka), is the main protagonist of Dead Mount Death Play. As a human born with the Evil Eye, the Corpse God (not yet known as such) was sold to the necromancer Easlies Swordfrail at the age of ten and studied Necromancy under her tutelage, eventually becoming an Undead himself. Though he wanted nothing more then to live a peaceful life, the Geldwood church spent a century wanting nothing more than to see him d', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205706-8XUDkf1xie7B.png', NULL, NULL, '榊原優希', NULL, 205706, 'MAIN', 293) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015264', 'AN1620', '繰屋匠', 'Takumi Kuruya is an informant based in Tokyo''s Shinjuku Ward who uses illegal drones to collect data alongside other methods; occasionally, he also helps contract killers conceal their victims'' corpses. Per Lisa Kuraki''s instructions, he has become companion to the Corpse God and assists his fortunetelling business by collection information on clients during their sessions.', 23, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205707-bgpDrXLcLh2L.png', NULL, NULL, '内田雄馬', NULL, 205707, 'MAIN', 67) ON CONFLICT DO NOTHING;
