INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015266', 'AN1620', '雷小幽', 'Xiaoyu Lei is a former member of the Heilei who currently serves the Shinoyama Clan. His ongoing assignment is to protect Sayo Shinoyama during her residence with the impostor posing as her half uncle.', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b299372-rUzPpWzIzwBa.png', NULL, NULL, '福圓美里', NULL, 299372, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
