INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015268', 'AN1620', '細呂木雅', 'Miyabi Hosorogi  is a spirit possessing Misaki Sakimiya''s mechanical pencil as per a pact with the Corpse God. He currently works as a ''gimmick'' in the Corpse God''s fortune-telling business, acting as an autonomous pencil in order to convince clients of the Corpse God''s legitimacy.  While alive, Hosorogi was at one point Chief of Police and an Internal Affairs inspector investigating a certain symbol alongside Tsubaki Iwanome. He was murdered before he could see his case through, and his last li', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302181-1gAGRIsvaVqT.png', NULL, NULL, '七海ひろき', NULL, 302181, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
