INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015272', 'AN1620', 'イーズリーズ・ソルドフレイル', 'Easlies Swordfrail, nicknamed "Wandering Balcony" and often referred to as the "Demon of the Peninsula" in books, is a powerful necromancer, the former second-ranked imperial court sorcerer to the Byandy Empire, and the former necromancy master of Corpse God.[1]', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b205714-XVeml54MoS2C.png', NULL, NULL, '豊口めぐみ', NULL, 205714, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
