INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015275', 'AN1620', 'ロメルカ・リメルカ', 'Romelka Rimelka the "Roaming Woodlands" is a Wood Mage who served as seventh-ranked imperial court sorcerer of Byandy Empire until its collapse.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302198-hXIW0rGJOzhA.png', NULL, NULL, '高森奈津美', NULL, 302198, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015276', 'AN1620', 'シャグルア・エディス・ルグリッド', 'Sir Shagrua Edith Lugrid the Calamity Crusher is a former knight of the Geldwood church''s subjugation unit who possesses the Evil Eye.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205711-jHsqn94DCjlx.png', NULL, NULL, '草尾毅', NULL, 205711, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
