INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015281', 'AN1620', '八津蘭丸', 'Occupation: Policeman  Affiliation: Member of Materials Compiling Group No.3.  While Yatsu may greet an adversary with a toothy smirk and cool confidence, he is not above voicing a complaint or two when aggrieved and reacting to an obnoxious adversary with a naked grimace. Like the rest of Comps-3 he is staunchly loyal to Iwanome, to whom he also will not hesitate in pointing out unpleasant truths.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252007-i1BTy6vgW1vQ.png', NULL, NULL, '吉野裕行', NULL, 252007, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015282', 'AN1620', '四乃山紫月', 'Shizuki Shinoyama is Kazuki Shinoyama''s twin brother and the youngest grandson of Rozan Shinoyama. He and Kazuki, unbeknownst to either of them, are shadowed by the spirit of their deceased older sister Suzuka.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256806-xTocOeW48HWj.png', NULL, NULL, '市川蒼', NULL, 256806, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
