INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015291', 'AN1620', '四乃山華月', 'Kazuki Shinoyama is Shizuki Shinoyama''s twin sister, and the youngest granddaughter of Rozan Shinoyama. Though neither she nor her brother knows it, their deceased older sister Suzuka still watches over them in spirit form.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256807-5Z1b5ftjsmxp.png', NULL, NULL, '芹澤優', NULL, 256807, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015292', 'AN1620', 'レミングス', 'Lemmings is a killer and star member of Takeru Shinoyama''s Dragon King''s Palace Agency. Though most Shinjuku residents consider him an urban legend, Comps-3 has linked him to more than one crime and seeks his capture.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256810-1EHKpjKmjE8x.png', NULL, NULL, '蒼井翔太', NULL, 256810, 'SUPPORTING', 65) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015293', 'AN1620', '胡蝶・エイトポート', 'She is a journalist for the Weekly Dry tabloid who covers stories on everything from politics to art. Though only a junior reporter, she has penned a number of "fine exposés" and is reputed as capable, though those who stand to lose from her investigations are liable to consider her a potential thorn in their sides.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255865-qGPeygCwVePn.png', NULL, NULL, '佐倉綾音', NULL, 255865, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015294', 'AN1620', 'レクリア・ローフィラルド', 'Head Priestess Recuria Lofilardo is a powerful hieromancer of the Geldwood Church based in the Kingdom of Nyanild. She ultimately places her loyalty in Shagrua Lugrid over Geldwood when Shagrua defects, and consequently earns the ire of Geldwood''s upper echelon.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302144-8tki6YV4aFlr.jpg', NULL, NULL, '柚木涼香', NULL, 302144, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
