INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015297', 'AN1620', '大貝', 'Taipei is a member of the Heilei who currently serves Takeru Shinoyama alongside Bao.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302220-VQ3lxOHjEEMq.png', NULL, NULL, NULL, NULL, 302220, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015298', 'AN1620', '四乃山尊', 'Takeru Shinoyama is Rozan Shinoyama''s eldest grandson, the president of Shinoyama Security, and the employer of an elite team known as Dragon King''s Palace Agency.', 26, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256804-v78PjzXwfr0C.png', NULL, NULL, '小西克幸', NULL, 256804, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015299', 'AN1620', '雪車村天鵶', 'Tena Sorimura (雪車村天鵶 Sorimura Tena), nicknamed the Phantom Solitaire (怪人 ソリティア Kaijin Soritia) by Tsubaki Iwanome, is one of several troublemakers in Shinjuku who fall under the jurisdiction of Materials Compiling Group No.3.  He is currently haunted by the spirit of a wheelchair-bound girl, as visible to those who possess the Evil Eye. The girl appears to be worried about the path Sorimura is traveling down.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256811-DmxYpBcd0j5x.png', NULL, NULL, '高橋広樹', NULL, 256811, 'SUPPORTING', 106) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015300', 'AN1620', '幌島ヒイロ', 'Hiiro, alongside his sister Rinne, is an ex-Agakura sniper.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302213-Ysp1S7cT6YlL.png', NULL, NULL, '岩中睦樹', NULL, 302213, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015301', 'AN1620', '暴', 'A woman who works for Takeru Shinoyama.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302212-j7eggvzkGMGE.png', NULL, NULL, '相川奈都姫', NULL, 302212, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015302', 'AN1620', '岩野目ツバキ', 'Occupation: Policeman  Affiliation: Member of Materials Compiling Group No.3.  He is the manager of Materials Compiling Group No.3 and currently in charge of the Phantom Solitaire investigation''s jurisdictional side.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255864-rCo9PhcbV3lS.png', NULL, NULL, '江口拓也', NULL, 255864, 'SUPPORTING', 55) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015303', 'AN1620', '四乃山涼火', 'Suzuka Shinoyama is the deceased eldest granddaughter of Rozan Shinoyama and older sister to the twins Shizuki Shinoyama and Kazuki Shinoyama. Her spirit has followed the twins for the past year, born out of Suzuka''s love for them and fear for their safety prior to her murder at Know''s hands.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256805-XwRETdHu46SD.png', NULL, NULL, '原紗友里', NULL, 256805, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015304', 'AN1620', '四乃山ポルカ', 'Polka Shinoyama is the second son of Rozan Shinoyama and one of two heirs to the Shinoyama Financial Group. Shortly after running away from home, Polka is assassinated by contract killer Misaki Sakimiya. The Corpse God reincarnates into Polka''s freshly murdered body, anchoring Polka''s spirit, and soon transfers Polka''s spirit to one of Takumi Kuruya''s drones. Later, he again transfers Polka''s spirit to a stuffed bonito shark toy. Polka has given permission for the Corpse God to use his name and ', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205704-21COp1cXoXS2.jpg', NULL, NULL, NULL, NULL, 205704, 'SUPPORTING', 56) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015305', 'AN1620', '山田文代', 'An elderly woman who is 25-year veteran of Shinjuku station.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302179-iD8hsLFh6ny2.png', NULL, NULL, '小林沙苗', NULL, 302179, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015306', 'AN1620', 'カルラ・ウォン', 'She is a bouncer that works at Youtoukorou.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b299374-XvYx2J9mZVKu.png', NULL, NULL, '大西沙織', NULL, 299374, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015307', 'AN1621', '由​​​​​​​​​​​​​​崎​​​​​​​星​​​​​​​​​​​​空', 'Likes: Math, Physics, Finances  Kindhearted, charismatic, and intelligent, albeit only in certain areas. Nasa Yuzaki decided he had no need for a high school education, and, well, he was mostly right. He is the type of person who would worry if his friends got hurt when they tripped over a pebble, while he ended up falling down a cliff. He is very in love with his wife.', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130944-Bi9EfjnNO3LT.png', '5月5日', 'A', '榎木淳弥', NULL, 130944, 'MAIN', 1624) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015308', 'AN1621', '由崎司', 'Relatives: Tokiko Tsukuyomi (grandaunt), Enishi Yuzaki (father-in-law), Kanoka Yuzaki (mother-in-law)  Tsukasa Yuzaki is the wife of Nasa Yuzaki. Not much is known about her, but what is known is that she''s mysteriously cute.  Tsukasa has long pink hair with a clasp on the back and pink-red eyes. She wears elegant clothing and a skirt. While at home she is usually seen wearing modern clothing. During her trip to Kyoto, she wore a floral Yukata.  Tsukasa comes across as calm and level-headed; see', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131106-ZJOpYOpurcYS.png', '4月3日', 'O', '鬼頭明里', 154, 131106, 'MAIN', 4825) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015309', 'AN1621', '鏡球馬', 'She is Kaname''s classmate and is always looking for her. She lacks logic and always draws queer conclusions. In a word: a klutz.  (Source: Tonikaku Kawaii Wiki)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188274-hA8VqOYeRXTW.jpg', NULL, NULL, '久野美咲', NULL, 188274, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015310', 'AN1621', '百鬼桜花', 'She was Nasa''s classmate in middle school and is the same age as him. She currently owns an electronics store and apparently, she doesn''t have any clear desire for affective relationships.  (Source: Tonikaku Kawaii Wiki)', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188279-kJgriY1uVlsc.jpg', NULL, NULL, '三上枝織', NULL, 188279, 'SUPPORTING', 51) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015311', 'AN1621', '有栖川要', 'She''s been helping the bathhouse for a long time. Despite being young, she is very mature and always gives good suggestions to Nasa to help him out with his couple life. Like her mom, she really likes dirty jokes and apparently, she has no fear of cleaning the males'' bath while Nasa is in there. She isn''t shy and prefers a direct approach.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b137513-h2d62OMGdOVO.png', NULL, NULL, '芹澤優', NULL, 137513, 'SUPPORTING', 557) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015312', 'AN1621', '月読時子', 'She was the minister of education, but she resigned a few days after Nasa and Tsukasa married. As for why she says she is worried about her health and she may no longer be involved in politics due to her age. She has great influence and power. Indeed, she easily tracks down Tsukasa''s location while she was still living in Nasa''s apartment.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188292-w0QmQU0Jht9T.jpg', NULL, NULL, '平野文', NULL, 188292, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015313', 'AN1621', '有栖川綾', 'She is Kaname''s older sister. She is a lazy ditz but, Kaname considers her on the "genius side" for her great learning capacity. In contrast with that, she usually misunderstands important things and she gets really confused in the blink of an eye. Her favorite hobby is probably playing video games and she usually nags Kaname into playing with her.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b137514-8CLYxq6Vrsll.png', NULL, NULL, '上坂すみれ', NULL, 137514, 'SUPPORTING', 232) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015314', 'AN1621', '鍵ノ寺千歳', 'Apparently, Tsukasa saved her from falling off a cliff when they were children. Chitose wants to use her own life for the sake of Tsukasa to pay her back. She obviously doesn''t want Tsukasa falling into Nasa''s hands. She has two maids: Aurora and Charlotte. Chitose has a personality that quickly bends from being strong to whining. She considers Tsukasa her sister.  (Source: Tonikaku Kawaii Wikia)', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b137515-SwOZGCSqhpmO.png', '10月20日', NULL, '小原好美', NULL, 137515, 'SUPPORTING', 126) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015315', 'AN1621', 'トースト', 'Nasa and Tsukasa''s cat.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313800-rOizKztfVXDd.jpg', NULL, NULL, NULL, NULL, 313800, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015316', 'AN1621', 'シャーロット', 'She is one of Chitose''s maids. She quickly changes her personality from being simple-minded and innocent to going berserk with a giant sword in her hands. However, she is always happy with a big smile on her face. She will probably do everything Chitose tells her to do without hesitation.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b137517-g9L9c1mlYaOm.png', NULL, NULL, '大和田仁美', NULL, 137517, 'SUPPORTING', 237) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015317', 'AN1621', '柳直子', 'She is a teacher from the middle school that Nasa had frequented. She is always super busy with work and doesn''t have much time for her life. However, once she sees how happy Nasa''s marriage is, she becomes more open to future relationships. She considers herself a boring person.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b175114-OgCJf9Zlf1QB.png', NULL, NULL, '伊藤かな恵', NULL, 175114, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015318', 'AN1621', 'Dadakri', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b330261-uhTpRyt6XER8.jpg', NULL, NULL, NULL, NULL, 330261, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015319', 'AN1621', '鬼丸銀河', 'He is not a Yakuza, but everything about him recalls one. Indeed he always dresses as such and often changes normal terms with words more shadier and fishy. Besides that, he is a high school student and Nasa''s cousin.  (Source: Tonikaku Kawaii Wiki)', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188288-CJxKPS92MCy9.png', NULL, NULL, '興津和幸', NULL, 188288, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015320', 'AN1621', '谷口', 'He is a teacher from the middle school that Nasa had frequented and even though he finds the courage to ask Yanagi-sensei to go out, he is very shy.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b190385-GPWK4umn1M6B.png', NULL, NULL, '新井良平', NULL, 190385, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015321', 'AN1621', 'アウロラ', 'She is one of Chitose''s maids. She is usually serious and cold-minded. Probably the exact opposite personality of Charlotte: the second maid of Chitose. She always appears with Charlotte and she usually tries to stop her from being too impulsive.   (Source: Tonikaku Kawaii Wikia)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b137516-Ea2oRhAwnVv9.png', NULL, NULL, '長久友紀', NULL, 137516, 'SUPPORTING', 57) ON CONFLICT DO NOTHING;
