INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015398', 'AN1624', 'Raeliana McMillan', 'Reincarnated as only a side character dying in the hands of her fiancée, Raeliana Mcmillan is the badass main female character who is determined to live her life and not die as she was destined to do so. In a moment of desperation, she goes to Noah Wyknight and offers him a contract for an arrange marriage, to avoid her doom by canon fate.', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b147510-Z9O3wnkPFAhw.jpg', NULL, NULL, '宮本侑芽', NULL, 147510, 'MAIN', 878) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015399', 'AN1624', 'Noah Wynknight', 'The famous Duke of Wynknight and the main male protagonist of the story. In the original timeline, he ends up with Beatrice but due to Raeliana changing the original timeline to avoid her fate, he fell for Raeliana instead. He''s Siatrich''s younger brother.', 23, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b147511-oDqLy4YLv99L.jpg', NULL, NULL, '梅原裕一郎', NULL, 147511, 'MAIN', 863) ON CONFLICT DO NOTHING;
