INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015455', 'AN1627', '羽鳥智世', 'Chise Hatori is a Sleigh Beggy and one of the main protagonists of the series. She is the apprentice and wife of Elias Ainsworth.  Devoid of love from a young age, Chise has a mysterious connection to magic, which causes her to attract fairies. She learns more about her magical abilities as she finds herself in the care and tutelage of Elias, a powerful mage.  (Source: Ancient Magus Bride Wiki & Crunchyroll)', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88344-zn7wbe8rKgqT.png', NULL, NULL, '種﨑敦美', 155, 88344, 'MAIN', 2963) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015456', 'AN1627', 'エリアス・エインズワーズ', 'He is an ancient magician with both human and fae characteristics. Despite his appearance, he is gentle and polite with humans and shows a great interest in them. He understands why humans feel the emotions they do, but has never experienced them himself.   One day, he buys Hatori Chise from the black market and makes her his Mage Apprentice.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b121430-n1k9M5RdkXyI.png', NULL, NULL, '竹内良太', NULL, 121430, 'MAIN', 1980) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015457', 'AN1627', 'ヴェロニカ・リッケンバッカー', 'Student attending the College and a classmate that sits next to Chise in Narcisse Maugham''s class. She is known to usually be in the company of April and May Atwood, along with Philomela.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302374-L4qy5J5UzlQE.jpg', NULL, NULL, '上田麗奈', NULL, 302374, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
