INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015462', 'AN1627', 'リアン・スクリムジョ', 'Rian Scrimgeour is a student attending the College in the same year as Chise Hatori. He is sorcerer who has a fascination with magecraft and has a mentorship with Torrey Innis. Though he is a member of House Scrimgeour, he states that he is leaving it.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302376-jpXHZiy3CV6n.jpg', NULL, NULL, '山下誠一郎', NULL, 302376, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
