INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015495', 'AN1627', 'アイザック・ファウラー', 'Student attending the College. He appears to be a shy individual, but considers himself more approachable than the others as he is not a member of the Seven Shields. He''s also knowledgeable about many things.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302373-5kq2lRJTZklw.jpg', NULL, NULL, '西山宏太朗', NULL, 302373, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
