INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015498', 'AN1627', 'カルタフィルス', 'Cartaphilus is a sorcerer that serves as a recurring antagonist of the series.   (Source: The Ancient Magus Bride Wikia)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n129385-jdRVhN7MJUTb.png', NULL, NULL, '村瀬歩', NULL, 129385, 'SUPPORTING', 198) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015499', 'AN1628', 'エルゼ・シルエスカ', 'Elze is an adventurer equipped with gauntlets on both hands. She is the type who acts rather than talks and often pitches in before thinking. She is the older of the twins.  (Source: Honey''s Anime)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/122732-JigJPfeKW3O2.jpg', NULL, NULL, '内田真礼', NULL, 122732, 'MAIN', 197) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015500', 'AN1628', '望月冬夜', 'Touya is a young boy who has come to this other world. For the most part, he is very well-mannered, but when he feels that those close to him could be harmed, he also has a side that will not hesitate.  (Source: Honey''s Anime)', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b122730-SC9en2JOxQ6y.jpg', NULL, NULL, '福原かつみ', NULL, 122730, 'MAIN', 226) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015501', 'AN1628', 'リンゼ・シルエスカ', 'Linze was in the city with her sister and right before they were tricked into something, Touya saved them. She is reserved, but there are times where she shows her inner strength. She is the younger of the twins.  (Source: Honey''s Anime)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/122733-GuPOvPWFU91H.jpg', NULL, NULL, '福緒唯', NULL, 122733, 'MAIN', 193) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015502', 'AN1628', 'ユミナ・エルネア・ベルファスト', 'A Princess of Belfast, and daughter of King Tristwin and Queen Yuel. Yumina met Touya when he heals her father from an attempted poisoning. Yumina possess the Null magic "Mystic Eyes", an ability that comes from her Heterochromic Eyes which give her the ability to see a person''s true nature. Due to this power, upon seeing the selfless and kind aura surrounding Touya after he saves her father, she asks to be engaged to him, believing that she will never find a better candidate to be her husband. ', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b122735-w0z8H5SF2yaz.jpg', NULL, NULL, '高野麻里佳', NULL, 122735, 'MAIN', 307) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015503', 'AN1628', '九重八重', 'Born in the far eastern country of Eashen to a samurai family, Yae left her home to travel and hone her skills elsewhere. Touya''s group crosses paths with her during their travels, helping to fend off a group of ruffians attacking her. Thereafter, she decides to accompany Touya on his travels.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b122734-lDf5Zyt9b1i4.png', NULL, NULL, '赤﨑千夏', NULL, 122734, 'MAIN', 225) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015504', 'AN1628', 'ヒルデガルド・ミナス・レスティア', 'Hildegard Minas Lestia, nicknamed Hilde, is one of Touya Mochizuki''s wives. Hilde is also the first princess of Knight Kingdom of Lestia and she is currently living with Touya and everyone else at Brunhild Dukedom.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248013-RAAHKSZNxwRA.jpg', NULL, NULL, '芹澤優', NULL, 248013, 'SUPPORTING', 49) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015505', 'AN1628', 'レネ', 'Originally a homeless pickpocketer, but after Touya rescued her from two other pickpockets going after her because of a territory problem, he decided to hire her to be a maid.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b228828-PqCA3ie9CFhC.png', NULL, NULL, '青山吉能', NULL, 228828, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015506', 'AN1628', 'ザナック・ゼンフィールド', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b228831-4BlVBAjV1zXx.png', NULL, NULL, '鈴木琢磨', NULL, 228831, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015507', 'AN1628', 'ルーシア・レア・レグルス', 'Lucia Rea Regulus, nicknamed Lu, is one of Touya Mochizuki''s wives. Lu is also the third princess of the Regulus Empire and she is currently living with Touya and everyone else in the Duchy of Brunhild.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248011-lsbcNi4FOTJU.jpg', NULL, NULL, '高木美佑', NULL, 248011, 'SUPPORTING', 67) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015508', 'AN1628', 'アルフレッド・エルネス・オルトリンデ', 'Duke Alfred Ernes Ortlinde is the brother of the King of Belfast.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b228833-r8izU9qqn4Hw.png', NULL, NULL, '楠大典', NULL, 228833, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
