INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015510', 'AN1628', '桜', 'Sakura is one of Touya Mochizuki''s wives. She survived from an assassination attempt after being rescued by Touya. However, she suffered amnesia was given the temporary name Sakura by Touya. Later, it is revealed that her real name is Farnese Forneus but she decides to use Sakura as her name. She is actually planned as the successor of Xenoahs Demon Kingdom. Currently, she stays with Touya at Brunhild Dukedom.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248012-vdKm6Gzgn8Jo.jpg', NULL, NULL, '久保田未夢', NULL, 248012, 'SUPPORTING', 42) ON CONFLICT DO NOTHING;
