INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015597', 'AN1634', 'スレッタ・マーキュリー', 'A second-year student in the piloting department, who transferred to the school from Mercury. Suletta is timid and somewhat lacks communication skills. She is the pilot of the Gundam Aerial developed on Mercury.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b279507-nKzMuTa8fBek.png', NULL, NULL, '市ノ瀬加那', NULL, 279507, 'MAIN', 1254) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015598', 'AN1634', 'ミオリネ・レンブラン', 'An attractive and academically distinguished second-year student in the management strategy department. Miorine is the only daughter of Delling Rembran, the president of the Beneritt Group and chairman of the school''s board. She has a strong rebellious feeling towards her father.  Miorine has shown an interest in gardening in her spare time, with an apparent focus on tomatoes.  (Source:  Mobile Suit Gundam: The Witch from Mercury Official Site)', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b279508-JvHoPuV6NwOs.jpg', NULL, NULL, 'Lynn', NULL, 279508, 'MAIN', 903) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015599', 'AN1634', 'ヌーノ・カルガン', 'He is a second-year mechanic in the Earth dormitory. He is a geek who is well versed in software, and he and Ojero work together as partners in crime.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290041-7XKIsBbQeZVv.jpg', NULL, NULL, '畠中祐', NULL, 290041, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015600', 'AN1634', 'アリヤ・マフヴァーシュ', 'A third-year mechanic in the Earth Dormitory. She is a sensible person who keeps her own pace. She loves fortune-telling and livestock (yaks, goats, and chickens), which she brought from her hometown.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290044-wCC5Ejctm8Nq.jpg', NULL, NULL, '島袋美由利', NULL, 290044, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015601', 'AN1634', 'レネ・コスタ', 'A second-year pilot student in the Grassley House. She is one of the female students who support Shaddiq. She seems to be a friendly person, but she is a black-hearted person who changes her demeanor when it comes to male and female students.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294367-3BTOxIR2DmaF.png', NULL, NULL, '鈴代紗弓', NULL, 294367, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
