INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015610', 'AN1634', 'リリッケ・カドカ・リパティ', 'She is a first-year student in the Business Strategy Department, living in the Earth Dormitory. She is cheerful and friendly. She loves to talk about her love life and is popular among male students.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290042-BiWwUrbzG2I4.jpg', NULL, NULL, '稲垣好', NULL, 290042, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
