INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015615', 'AN1634', 'エラン・ケレス', 'The top pilot backed by Peil Technologies, one of the group''s three branches. A third-year student in the piloting department. Elan is a taciturn and solitary person, who doesn''t open his heart to anyone in school. He has an interest to Suletta.  (Source: Official Website)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b279505-4JNsemle78MV.jpg', NULL, NULL, '花江夏樹', NULL, 279505, 'SUPPORTING', 131) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015616', 'AN1634', 'ソフィ・プロネ', 'Sophie is a sadistic and aggressive girl. She is excitable and impulsive, and appears to enjoy fighting and threatening her enemies.  She is easily excitable in combat, Sophie also has an interest in fellow witches and Gundams like Suletta and the Aerial, both of whom she had watched through videos of their duels, and was in euphoric delight at fighting both, developing an obsession towards both.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b296137-sUlCCN8WdcqU.png', NULL, NULL, '井澤詩織', NULL, 296137, 'SUPPORTING', 42) ON CONFLICT DO NOTHING;
