INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015622', 'AN1634', 'ペトラ・イッタ', 'She is a second-year mechanic student in the Jeturk House. She is the cool, intelligent, honor student type. Much like Felsi, she adores Guel.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b288849-rWsIbEfBpfrv.png', NULL, NULL, '広瀬ゆうき', NULL, 288849, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
