INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015645', 'AN1635', 'ブルー', 'An extremely horny Magical Girl with a love of surströmming who wields an odd shaped scythe that can cut through almost anything. Her wish is to see a certain rock band live when the SSC are gone.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b287628-7okOe2PkKXVV.png', NULL, NULL, '愛美', NULL, 287628, 'MAIN', 57) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015646', 'AN1635', 'ピンク', 'A magical girl who hides behind a gas mask and speaks in a verbal tic that only Blue seems to understand. She wields a large, magical syringe and is skilled at creating different kinds of drugs. Her wish is to work in a maid cafe one day.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b287629-6XPheCn4YKAU.png', NULL, NULL, '黒沢ともよ', NULL, 287629, 'MAIN', 92) ON CONFLICT DO NOTHING;
