INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015708', 'AN1637', 'フィナ', 'A ten-year-old girl and a resident of the town Crimonia. She lives with her mother and younger sister. Fina''s father died when she was still young, while her mother contracted a serious illness and is bedridden. In order to care for her family, Fina is forced to work at an early age to buy medicine for her mother and food for her family. Being only ten years old she is limited in what she can do and earns small wages through occasionally helping the guild with skinning monsters.  Fina is kind, h', 10, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b156324-ZUNzdQ5BGOVK.png', NULL, NULL, '和氣あず未', NULL, 156324, 'MAIN', 131) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015709', 'AN1637', 'ユナ', 'A fifteen year old girl who lives by herself. She became socially withdrawn at age twelve by her own choice because she wanted to play World Fantasy Online as much as possible. After she gave her parents 100 million yen, they left her to her own volition and only return home when they run out of money to spend, causing Yuna to secretly move out into a luxury apartment to hide from them. There, she spends nearly her entire day playing World Fantasy Online and the remainder only eating and sleepin', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b156323-JZbBp6YPZhmN.png', NULL, NULL, '河瀬茉希', NULL, 156323, 'MAIN', 898) ON CONFLICT DO NOTHING;
