INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015724', 'AN1637', 'くまきゅう', 'Kumakyuu is Yuna''s summoned Beast along with Kumayuru. Kumakyuu takes the appearance of a White Bear. In its normal adult form, it is as big as a large bear, but it can also change its size to be more compact in its cub form. Whether big or small, Kumakyuu looks like a cute teddy bear.  (Source: Kuma Kuma Kuma Bear Wiki)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b173793-GFyhHVVBGfyf.png', NULL, NULL, '黒瀬ゆうこ', NULL, 173793, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
