INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015728', 'AN1637', 'リズ', 'Liz is a helper and employee at the orphanage. She is also the instructor for the orphans. Just like Bo, she cares for the children very much and teaches them for a living.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b194291-6KKGTiasSg2F.png', NULL, NULL, NULL, NULL, 194291, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
