INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015732', 'AN1637', 'ノアール・フォシュローゼ', 'A noble girl who resides in the town of Crimonia. Her father is the Feudal Lord of Crimonia and together they live in a mansion located there, while Noir''s mother and sister live together at the Capital City.  Noir has a slightly spoiled and prideful attitude, although not to the point of it being offensive but rather cute and childish. She doesn''t seem to mind associating with people outside her social class to a certain degree and became friends with Fina even with their social status differen', 10, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b156325-k1F0bdgHCQ9W.png', NULL, NULL, '日高里菜', NULL, 156325, 'SUPPORTING', 66) ON CONFLICT DO NOTHING;
