INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015739', 'AN1637', 'シア・フォシュローゼ', 'A noble girl who resides in the Royal Capital. Shia is the elder sister of Noir and the daughter of Cliff and Eleanora Fochrosé. She currently lives together with her mother and attends the Royal Academy, while her sister and father live together in Crimonia.  Shia had a very prideful and arrogant personalty before meeting Yuna. Initially she believed that she is one of the strongest students at her school and that no girl is stronger than her, but after suffering a complete defeat at the hands ', 15, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b156326-f2LforXiRCzP.jpg', NULL, NULL, '水瀬いのり', NULL, 156326, 'SUPPORTING', 47) ON CONFLICT DO NOTHING;
