INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015742', 'AN1637', 'ボウ', 'Bow is the headmistress of the orphanage in Crimonia. She loves the children she takes care of very much but could not do as much for them because they did not have enough money until Cliff caught Roland, who was in charge of the money not giving out money for the orphanage.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b194290-1SppQeL4cTZZ.png', NULL, NULL, '岡村明美', NULL, 194290, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
