INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015747', 'AN1637', 'くまゆる', 'Kumayuru is Yuna''s summoned beast along with Kumakyuu. Kumayuru takes the appearance of a Black Bear. It is as big as a large bear in its normal adult form, but it can also change its size to be more compact in its cub form. Whether big or small, Kumayuru looks like a cute teddy bear.  (Source: Kuma Kuma Kuma Bear Wiki)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b173794-KfPaNHInJdsC.png', NULL, NULL, '宮島えみ', NULL, 173794, 'SUPPORTING', 45) ON CONFLICT DO NOTHING;
