INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015767', 'AN1637', 'グラン・ ファーレングラム', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b196315-PI6aaaBEQVz8.png', NULL, NULL, '髙坂篤志', NULL, 196315, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015768', 'AN1638', 'ハッピー', 'Happy is a machine cat from the planet Excede, Rebecca Bluegarden''s companion, and a member of the Edens Zero''s crew. His ability "Happy Blasters" allows him to transform into a pair of guns that fire Ether bullets. These bullets are powerful enough to incapacitate their targets, but won''t kill them.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203889-ncXC9xRe9s8a.jpg', NULL, NULL, '釘宮理恵', NULL, 203889, 'MAIN', 152) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015769', 'AN1638', 'シキ・グランベル', 'Shiki, the main protagonist of the story, is a friendly yet socially awkward boy who''s the sole human denizen of the Granbell Kingdom, a fantasy theme park on the planet Granbell inhabited by robots. He possesses an ability called Ether Gear, which is inherited from the park''s animatronic Demon King, granting its user powers akin to those of a machine; Shiki uses a variation known as "Satan Gravity" that allows him to alter and redirect his own personal gravity. Encouraged by his artificial fami', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126469-0qKVqlbEj9JG.png', NULL, NULL, '寺島拓篤', NULL, 126469, 'MAIN', 702) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015770', 'AN1638', 'レベッカ・ブルーガーデン', 'Rebecca Bluegarden, the female protagonist, is a kind and energetic girl from the planet Blue Garden who travels to different planets to record videos of and upload to her channel on Aoneko, a video-sharing website, with the goal of obtaining one million subscribers. She pilots a spaceship called the Aqua Wing, which also functions as a seaboat.  Rebecca''s power, Leaper, is an Ether Gear that enhances her jumping ability, giving her great speed and agility.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126467-y4nX1uDjZ2VZ.png', NULL, NULL, '小松未可子', NULL, 126467, 'MAIN', 623) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015771', 'AN1638', 'コウゲツホムラ', 'Homura Kougetsu is a member of the Demon King''s crew on Edens Zero, and a self-described knight from Planet Blue Garden. Her power, Soul Blade, is a type of Ether Gear that allows her to create bladed weapons made of Ether.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134910-s5J23uA2Jkow.png', NULL, NULL, '青木志貴', NULL, 134910, 'SUPPORTING', 607) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015772', 'AN1638', 'カウチポ', 'A B-Cuber who was abducted together with Rebecca Bluegarden. She runs the food-centric Mogumogu Channel on B-Cube where her content revolves around eating.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230780-Vj3ygnUbvWXW.png', NULL, NULL, NULL, NULL, 230780, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015773', 'AN1638', 'ブリガンダイン', 'He is a machine and one of the Demon King''s Four Dark Stars.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191292-FuP6NYW58MKb.png', NULL, NULL, '山本祥太', NULL, 191292, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015774', 'AN1638', 'シスター・イヴリィ', 'Sister Ivry is a machine part of the Four Shining Stars. Her power, Heal Atomizer, is a Healing Ether ability that allows her to mend wounds, undo negative status effects, and repair living machines. Sister is short tempered, enjoys teasing, and has a laid-back attitude, but she is also dutiful and can be friendly to her allies. She has a sadistic side and enjoys torture. She dislikes things that can''t be healed.  Sister is shown to be someone who cannot accept death as a finality for machines, ', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154653-JRXVBIFjAOTz.jpg', NULL, NULL, '藤井ゆきよ', NULL, 154653, 'SUPPORTING', 251) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015775', 'AN1638', 'ラビリア・クリスティ', 'Labilia Christy is an adventurer and B-Cuber who works at the Shooting Starlight guild.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134911-SbUNoom8ipOR.png', NULL, NULL, '綾乃あゆみ', NULL, 134911, 'SUPPORTING', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015776', 'AN1638', 'ウィザード', 'He is a Machine and one of the Demon King''s Four Dark Stars.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191300-RyfBrip6u9FE.png', NULL, NULL, '村田太志', NULL, 191300, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015777', 'AN1638', 'シャオメイ', 'Xiaomei is shown to have a calm and serious disposition as well as knowledgeable due to her precognition abilities.  Due to her precognition abilities not being able to tell a single outcome, it is shown that Xiaomei has an interest in watching people battle and this interest grows to the point where she becomes visibly excited and aroused.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154654-qs8J69oXReZO.jpg', NULL, NULL, '井上ほの花', NULL, 154654, 'SUPPORTING', 84) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015778', 'AN1638', 'ジン', 'Jinn is a cyborg who was in the team "Rogue Out". His power, Wind Rage, is a type of Ether Gear that uses wind similarly to a typhoon. Jinn likes his sister Kleene and dislikes any man that approaches her.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191286-ebRH6YSjrZO1.png', NULL, NULL, '新祐樹', NULL, 191286, 'SUPPORTING', 52) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015779', 'AN1638', 'キラー', 'He is a machine and one of the Demon King''s Four Dark Stars.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191291-8ewxl9XwwXkc.png', NULL, NULL, '市川蒼', NULL, 191291, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015780', 'AN1638', 'EMピーノ', 'Pino is a miniature anti-bot machine who joins the crew of Edens Zero. She can emit bursts of electromagnetic pulses, also known as EMP, that short out electronics for a few seconds and cancel out Ether Gear when it''s in use.  Her digital avatar resembles a young human girl with rabbit-like ears. She wears a necktie that is decorated with a single large heart.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154655-mzkGhnSyV52y.png', NULL, NULL, '井澤詩織', NULL, 154655, 'SUPPORTING', 142) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015781', 'AN1638', 'ドラッケン・ジョー', 'He is one of the Oración Seis Galáctica, the former owner of the Belial Gore, and the most notorious man in the Sakura Cosmos underworld. Element 4 is under his order.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191301-3PFrJhM3PxxZ.jpg', NULL, NULL, '楠大典', NULL, 191301, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015782', 'AN1638', 'ラグナ・ヒューゼルト', 'Laguna Husert is the element of water in the Element 4 under Drakken Joe. He is also an actor. Laguna''s power is Tears Lover, a type of Ether Gear that can turn anyone who sheds a tear into water. He likes fashion and dislikes dryness.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191280-blAaVXJW6idZ.jpg', NULL, NULL, '八代拓', NULL, 191280, 'SUPPORTING', 35) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015783', 'AN1638', 'クラウン', 'He is a machine and one of the Demon King''s Four Dark Stars.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191285-8Wb966SFGDxW.png', NULL, NULL, '柳田淳一', NULL, 191285, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015784', 'AN1638', 'ハーミット・ミオ', 'Hermit Mio is an android who''s the member of the Four Shining Stars. Her power, Master Code, is a type of Program Hacking. Hermit likes clothes and video games, and used to dislike humans, but not anymore.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154652-cI8zW1FoUVxP.jpg', NULL, NULL, '高尾奏音', NULL, 154652, 'SUPPORTING', 286) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015785', 'AN1638', 'セス・アンダーソン', 'A sentient computer program housed within a robotic body who served as a member of Drakken Joe''s team.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242732-w01A0wSPI96i.png', NULL, NULL, NULL, NULL, 242732, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015786', 'AN1638', 'ダイチ', 'He is the element of Earth of the Element 4 under Drakken Joe.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191306-dAUcFlb72LAQ.jpg', NULL, NULL, '伊丸岡篤', NULL, 191306, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015787', 'AN1638', 'ポセイドン・ネロ', 'He is a member of the Oracion Seis Galáctica like Elsie Crimson and Drakken Joe. He rules over the Aoi Cosmos.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191284-UIhFoFqzWqSR.jpg', NULL, NULL, '土師孝也', NULL, 191284, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015788', 'AN1638', 'ウィッチ・リグレット', 'Witch Regret is a machine part of the Four Shining Stars. She is responsible for defending Edens Zero. Her power, Shield Ether, allows her to produce barriers made of Ether.   Witch is very dutiful and holds a deep respect to Ziggy and his adoptive grandson Shiki. Although she is usually emotionless, Witch is capable of showing emotions. She finds it embarrassing to show her face to other people.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154254-62DER4tnyGed.png', NULL, NULL, '安野希世乃', NULL, 154254, 'SUPPORTING', 214) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015789', 'AN1638', 'ファイ', 'He is the Fire Element of the Element 4 under Drakken Joe.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191295-wEoESHTDDEHE.jpg', NULL, NULL, '増田俊樹', NULL, 191295, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015790', 'AN1638', 'ディエゴ・レイエス', 'Diego Reyes is an android and former member of Drakken Joe''s team.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242734-uTTSiWd2s56q.png', NULL, NULL, NULL, NULL, 242734, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015791', 'AN1638', 'ポセイドン・シュラ', 'Shura is a cruel and sadistic young man who feels entitled to everything in the Aoi Cosmos, including people due to being the son of The Emperor. He will kill any that displeases him. In front of his father he masks his true personality and acts the role of the respectful son. Additionally, he also wields gravity Ether gear.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b198023-eTLEdbeaCHZa.png', NULL, NULL, '鈴村健一', NULL, 198023, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015792', 'AN1638', 'モスコ', 'Mosco is a machine tasked with the chores on board of the Edens Zero and a former mercenary from the team Rogue Out. He is an expert sumo wrestler who uses sumo techniques to fight. He likes Sister and little animals, but dislikes ghosts.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b170569-kADfZyUIep1k.jpg', NULL, NULL, '岩田光央', NULL, 170569, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015793', 'AN1638', 'コナー', 'He is the captain of the Edens One and follow the order of Ziggy.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191282-14qdpmAHEnaJ.jpg', NULL, NULL, NULL, NULL, 191282, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015794', 'AN1638', 'シビル', 'He is the leader of a gang of criminals who operated on Planet Norma in the year X442. He appears later as an elderly man and an older version of Sibir from X442. He works for Drakken Joe as a in-debt slave.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191296-BJFHo53YrJqs.jpg', NULL, NULL, NULL, NULL, 191296, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015795', 'AN1638', 'Xenolith', 'Ziggy''s old mentor.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b206292-bBqMJcTB4KKb.png', NULL, NULL, '井上和彦', NULL, 206292, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015796', 'AN1638', 'ワイズ・シュタイナー', 'Weisz is a member of Edens Zero and a former thief from the Planet Norma. His power is Machina Maker, an Ether Gear that manipulates machines.  Weisz is a selfish, stubborn, and vain man with a perverted side. However, he does care for his friends, and shows concern for others in his own way. Weisz likes money and bunny girls, and dislikes studying.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139877-iS3Gk1VaIwrf.png', NULL, NULL, '手塚ヒロミチ', NULL, 139877, 'SUPPORTING', 272) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015797', 'AN1638', 'クリーネ・ラザフォード', 'She is the element of the wind of the Element 4 under the command of Drakken Joe. Her power, Wind Snatch, is a form of Ether Gear that allows her to manipulate wind to steal anything in the vicinity. Jinn is her elder brother. Kleene likes her brother and anything cute, and dislikes spam messages.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191302-k3rFZUH6oLtF.png', NULL, NULL, '大久保瑠美', NULL, 191302, 'SUPPORTING', 39) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015798', 'AN1638', 'ノア・グレンフィールド', 'He is the Director of the Galactic Intelligence Agency in the Sakura Cosmos. He is currently working undercover as the Guild Master of Shooting Starlight. His Ether Gear is name Eye of God, he can observe where people are with that.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191298-xWsU3FW4QG75.jpg', NULL, NULL, '岡本信彦', NULL, 191298, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015799', 'AN1639', '西村茜', 'Akane is a 5th grade girl with a withdrawn and slightly backward personality. She is called "Shinigami" by everyone in her class and she is teased. She is nervous about Takada-kun who keeps coming back without knowing the circumstances.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191319-2vdUG10nTHK6.jpg', NULL, NULL, '小原好美', NULL, 191319, 'MAIN', 199) ON CONFLICT DO NOTHING;
