INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015821', 'AN1641', '綾小路美月', 'A first year high school student. A serious girl who has social anxiety and difficulty understanding people''s emotions. Cares about the integrity of the salon.  Plays the role of a kind upperclassman at the cafe, and is Hime''s reliable "big sister."', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253965-TRnGlbDMTjg5.png', '7月7日', NULL, '上坂すみれ', 171, 253965, 'MAIN', 115) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015822', 'AN1641', '白木陽芽', 'A first-year high school student. A liar who is "loved by everyone" and keeps up a facade of friendliness with nearly everyone she meets. She rarely lets down her guard, even to those who know her true face. Hopes to marry rich.   Plays the role of an innocent kohai and Mitsuki''s "little sister" at the cafe.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253964-tHwYMJ8aXKaz.png', '2月14日', NULL, '小倉唯', 145, 253964, 'MAIN', 114) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015823', 'AN1641', '知花純加', 'A third year high school student. Dresses like a gyaru outside of work. Cares a lot about workplace harmony and dislikes seeing her coworkers get hurt because of romance.  Plays the role of a cool, bespectacled upperclassman in the cafe, and is Kanoko''s "elder sister."', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253966-V4VIHtKSTC39.png', '12月3日', NULL, '小市眞琴', 165, 253966, 'SUPPORTING', 94) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015824', 'AN1641', '西寺寧々', 'Kitchen staff for the cafe.', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253967-IAjYZouCRb15.png', '10月30日', NULL, '瀬戸麻沙美', 156, 253967, 'SUPPORTING', 44) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015825', 'AN1641', '小柴舞', 'The manager of Liebe who suffered an arm injury. Plays the role of a kohai character who also serves as the cafe''s mascot. Watches over the staff as a mature adult, despite her childlike appearance.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253968-KzZgH4SmhFJa.png', '5月3日', NULL, '田村ゆかり', 145, 253968, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015826', 'AN1641', '間宮果乃子', 'A first year high school student and Hime''s best friend. Is fiercly protective of Hime and has romantic feelings for her, which she doesn''t want to see returned. Comes across as soft-spoken, but is actually very blunt.   Plays the role of a shy kohai and Sumika''s "little sister" at the cafe. Usually wears glasses, except while playing her Liebe character.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253969-EzO4Hk5c9jRH.png', '7月30日', NULL, '田中美海', 156, 253969, 'SUPPORTING', 80) ON CONFLICT DO NOTHING;
