INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015844', 'AN1643', 'ロイ', 'An upbeat, energetic boy who likes to go hunting for treasures. Adventurous by nature, Roy seeks to start a journey to meet Pokémon he has not seen, and battle Legendary Pokémon just like the fabled ancient adventurer he has heard about from his grandfather. He owns a mysterious ancient Poké Ball that was given to him by his grandfather.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294409-ur1pQlkGbZDd.png', NULL, NULL, '寺崎裕香', NULL, 294409, 'MAIN', 45) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015845', 'AN1643', 'リコ', 'Liko is a protagonist of Pokémon Horizons. She owns a mysterious pendant, which was given to her by her grandmother. Liko is a member of Rising Volt Tacklers and travels with them, so she attends Indigo Academy remotely.  She is a kind and polite girl who doesn''t do well in stressful situations. Despite her shyness, Liko can easily make friends.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294410-lIZ6eTpStnFk.png', NULL, NULL, '鈴木みのり', NULL, 294410, 'MAIN', 288) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015846', 'AN1643', 'フリード', 'Friede is a Pokémon Professor and the commander of Rising Volt Tacklers.  Friede appears to be a young and competent Trainer, albeit rather distracted and forgetful, as he forgets to mention certain things to his friends sometimes. Despite this, Friede is quite protective of his team, whether putting himself in danger to protect the ship or protecting his teammates from opponents, especially the younger members.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b299753-y2yJxU3wyt8F.jpg', NULL, NULL, '八代拓', NULL, 299753, 'MAIN', 83) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015847', 'AN1643', 'クワッス', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b305057-cs5Om3CKhY5F.jpg', NULL, NULL, '浪川大輔', NULL, 305057, 'MAIN', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015848', 'AN1643', 'ウルト', 'Uruto is a major supporting character in Pokémon Horizons: The Series, introduced in the Mega Voltage arc. He is Roy''s rival and a member of the Rising Volt Tacklers. Born and raised in Lumiose City, Uruto received from his father at some point in his childhood, a mysterious Dusk Ball, the contents of which had never been revealed to him.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b378635-3rQWcGMdHpqK.png', NULL, NULL, '藤原夏海', NULL, 378635, 'MAIN', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015849', 'AN1643', 'ドット', 'A skilled programmer responsible for the Brave Asagi''s technology system and a member of the Rising Volteccers. Online, she is known as Gurumin, a popular streamer that makes videos on various topics of the Pokémon world.  Dot seems to be reclusive and spends most of her time behind doors creating videos, and is rarely seen by the other Rising Volteccers members. On the other hand, as Gurumin, she is seen as perky, using exaggerated teaching methods, and giving a beginner''s guide to Trainers int', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b304179-x4lWxNVyY4wb.jpg', NULL, NULL, '青山吉能', NULL, 304179, 'MAIN', 110) ON CONFLICT DO NOTHING;
