INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015854', 'AN1643', 'アメジオ', 'Amethio is an admin of the mysterious organization Explorers, sent to retrieve Liko''s pendant alongside Conia and Zir. After witnessing the efforts of the Rising Volteccers to protect Liko, Amethio decided to discover the secrets that Liko''s pendant hides at all costs. He is a formal person who does not show much emotion in many situations. However, his politeness is a front he uses to manipulate others into giving him what he wants. He battles with a Soublades.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b304176-vOd2Q1eCnyt7.jpg', NULL, NULL, '堀江瞬', NULL, 304176, 'SUPPORTING', 61) ON CONFLICT DO NOTHING;
