INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015857', 'AN1643', 'カブ', 'Kabu is the Gym Leader of Motostoke''s Gym. He specializes in Fire-type Pokémon. He gives the Fire Badge to Trainers who defeat him.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313795-nUMKVFt70FoO.png', NULL, NULL, '東地宏樹', NULL, 313795, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015858', 'AN1643', 'チリ', 'Chili is a character appearing in Pokémon Scarlet and Pokémon Violet. She is an Elite Four member of the Paldea region, she specializes in Ground types.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b321126-jwE3tP3RWdEM.png', NULL, NULL, '斎賀みつき', NULL, 321126, 'SUPPORTING', 90) ON CONFLICT DO NOTHING;
