INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015860', 'AN1643', 'ハイダイ', 'The Gym Leader of Cascarrafa Gym. He specializes in Water-type Pokémon.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b333206-MutTgBlKP6vE.png', NULL, NULL, '間宮康弘', NULL, 333206, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015861', 'AN1643', 'ブライア', 'A descendant of the historian Heather, who is writing a book telling her discoveries about the real history involving Area Zero.  Briar has a kind and jovial attitude, being friendly and kind to those she meets. Briar has a big sense of curiosity, getting easily excited to things related to her ancestor''s research amongst other things, such as encountering Terapagos, and wanting to learn more about Area Zero''s history and such.  (Source: Bulbapedia)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b355095-EGpfl1r4RAgo.jpg', NULL, NULL, '嶋村侑', NULL, 355095, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015862', 'AN1643', 'マチエール', 'Matiere is an orphan girl who became Handsome''s assistant.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b233245-OXTyFQ4tunlZ.png', NULL, NULL, '久野美咲', NULL, 233245, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015863', 'AN1643', 'コニア', 'Conia is an agent of the mysterious organization Explorers, sent to retrieve Liko''s pendant.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b304177-Ma6q7Lyg3Isa.jpg', NULL, NULL, '志田有彩', NULL, 304177, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015864', 'AN1643', 'ソウブレイズ', 'Soublades is a bipedal, humanoid Pokémon. Its body is primarily black, with blue colorations on its head, arms and legs. Its head has sharp pale blue "ears" protruding from either side, and has a fire burning above it that resembles the plume on a knight''s helmet. Its eyes have pink irises and wisps emanating from its white pupils. Almost all of Soublades'' body is covered in an old dark purplish blue suit of armor, filled with grudges. A plate with three pink indentations on its center covers So', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b305054-pcxp4iRNEAQx.jpg', NULL, NULL, '田邊幸輔', NULL, 305054, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
