INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015869', 'AN1643', 'ライム', 'Ryme is a legendary rapper and Ghost-type Gym Leader also known as the MC of RIP. Her bars and her Pokémon battles are both emotional and passionate.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b321377-Zw9ChH1XYn3I.png', NULL, NULL, '斉藤貴美子', NULL, 321377, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015870', 'AN1643', 'カイデン', 'Kaiden is a tiny avian Pokémon. Its feathers are mostly black, except for the grayish light-blue feathers covering its chest area, and the yellow covert feathers on its wings, as well as a yellow crescent-like marking on its face. Its head is nub-like and contains its fairly long orange beak, located just above the bottom of the crescent marking. Its eyes cover the tips of the crescent, which have white sclerae, black irises, and teal pupils. It has small webbed feet that are orange in color, an', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b355098-0xxdEHprLh1P.jpg', NULL, NULL, '佐倉綾音', NULL, 355098, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
