INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015876', 'AN1643', 'ジニア', 'He serves as the biology teacher of Naranja Academy/Uva Academy, as well as the homeroom teacher for the general studies track. Along with the World Pokémon Ecological Society, he is known for his research on ecologically similar Pokémon.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b331970-2h3RX5M3YwBT.png', NULL, NULL, '畠中祐', NULL, 331970, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
