INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015878', 'AN1643', 'ゼイユ', 'Seille tends to be distrustful towards people outside of her homeland at first before warming up to them. She has a hot tempered and competitive personality, hates losing and is always looking to challenge other people to various events for the sake of winning.  (Source: Bulbapedia)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b355094-0z5KBcuaZ5OP.jpg', NULL, NULL, '福圓美里', NULL, 355094, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015879', 'AN1643', 'インディ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b385553-PaKO83i2y9R4.jpg', NULL, NULL, '寺島惇太', NULL, 385553, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015880', 'AN1643', 'オリオ', 'A machine enthusiast and a member of the Rising Volteccers. Orio is a welcoming individual and is also a very diligent and hard-working person, responsible for observing any possible damages done to the Brave Asagi and reporting on them. She is skillful at her own profession, but seems to be rather clumsy outside of it.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300232-oc3dLexcbI2T.jpg', NULL, NULL, '佐倉綾音', NULL, 300232, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015881', 'AN1643', 'ネモ', 'A character introduced in Pokémon Scarlet and Violet. She is the player character''s friend and hopes to find an equal rivalry with them. Nemona is the president of the academy''s student council.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b308648-cY1icUbWE9yw.png', NULL, NULL, '喜多村英梨', NULL, 308648, 'SUPPORTING', 63) ON CONFLICT DO NOTHING;
