INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015888', 'AN1643', 'モリー', 'A healing specialist and a member of the Rising Volteccers. Molly is shown to be a fairly stoic individual, rarely displaying overt emotion. However, she is also shown to be caring, looking after and treating Pokémon that are sick or injured.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300234-4lyx8Hz83uad.jpg', NULL, NULL, '真堂圭', NULL, 300234, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015889', 'AN1643', 'アン', 'Anne is a student of Indigo Academy and Liko''s dorm mate. Her partner Pokémon is Mijumaru.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b304180-VLbNO7wMdm0X.jpg', NULL, NULL, '緒方佑奈', NULL, 304180, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015890', 'AN1643', 'ナンジャモ', 'Nanjamo is one of the Gym Leaders from the Paldea Region, specifically Hakkou City, and specializes in the Electric Type. When she isn''t representing the Gym (and sometimes even when she is), she serves as a popular idol streamer for the masses on her show *Donna Monja TV*, along with her partner Pokémon, Harabarii.   (Source: PocketMonsters.Net)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289725-aBGJvUvLqf7c.jpg', NULL, NULL, '本渡楓', NULL, 289725, 'SUPPORTING', 173) ON CONFLICT DO NOTHING;
