INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015900', 'AN1643', 'カエデ', 'The Gym Leader of Cortondo Gym in the Paldea Region. She specializes in Bug-type Pokémon.  She runs a bakery named Patisserie Soapberry. She believes that both sweets and Bug-type Pokémon have great power despite their small sizes. She was trained in the art of baking under the wing of Kofu.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b333205-sWLeNtv09Vqp.png', NULL, NULL, '三石琴乃', NULL, 333205, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015901', 'AN1643', 'ルシアス‎のファイヤー', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b344701-vL9I9yKRnFQQ.png', NULL, NULL, NULL, NULL, 344701, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015902', 'AN1643', 'カヌチャン', 'Kanuchan is a short, pink, humanoid Pokémon, with a relatively large head and arms compared to the rest of its body and stumpy toeless feet. Its arms have three fingers each, and it has what appears to be a pyramidal diamond-shaped steel plate on its torso. Its head has light pink circles on its cheeks, silver eyes, and a mouth with a square teeth-like growth on the lower lip. It has thin eyebrows or eyelashes above its eyes that give it a perpetually worried expression. On top of its head is a ', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b355099-G7D1yruXRa3Y.jpg', NULL, NULL, '林原めぐみ', NULL, 355099, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015903', 'AN1643', 'シアノ', 'Cyano is the founder and director of Blueberry Academy.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b378638-cRvnouJobcaA.png', NULL, NULL, '大和田伸也', NULL, 378638, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015904', 'AN1643', 'マードック', 'A skilled chef and a member of the Rising Volteccers. Murdock is a caring person. He likes to shower his Pokémon with affection and praises and is mindful to his teammates.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300238-x4RqI1mRlgG9.jpg', NULL, NULL, '三宅健太', NULL, 300238, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015905', 'AN1643', 'サンゴ', 'An executive of the mysterious organization Explorers.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b311744-bEBpTLI7fTpt.jpg', NULL, NULL, '大谷育江', NULL, 311744, 'SUPPORTING', 134) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015906', 'AN1643', 'テペン', 'Tepen is a character of the day who appeared in Ep 28. He is an acquaintance of Diana.  Long ago, when Diana was young, Tepen was once a friend of hers, as a fellow adventurer and explorer of ancient ruins. However, as time went on, Tepen became increasingly disillusioned with exploring, letting his fear of danger get the better of him, and eventually became a deceitful antique seller.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b331611-gHfqpQNkDZZx.png', NULL, NULL, '菊池通武', NULL, 331611, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015907', 'AN1643', 'グルーシャ', 'The Gym Leader of Glaseado Gym. He specializes in Ice-type Pokémon.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b333208-QAVgKQdJpTAn.png', NULL, NULL, '小林千晃', NULL, 333208, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015908', 'AN1643', 'パモ', 'Pawmi is a small, quadrupedal, rodent-like Pokémon that has a body that is almost entirely orange, with cream colorations on its lower forelimbs, snout, and tail, and green on the insides of its ears. It has beady brown eyes and a tiny nose. Its forelimbs are considerably large, and it has a tuft of fur on top of its head. Pawmi can stand on its hind legs, but barely.  Pawmi has yellow underdeveloped electric sacs in its cheeks, as well as yellow pad-like organs on its forepaws that can discharg', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b346570-IkQbDQY2uwWE.png', NULL, NULL, '青山吉能', NULL, 346570, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015909', 'AN1643', 'ミブリム', 'Mibrim is a small Pokémon with a round pink body and a pair of small feet. Most of its body is covered by a blue wig-like feature with a pink, hat-like erect tail. This tail is decorated with a white spot and has a blue bulbous growth on its tip. The flaps on the side of its head appear to be able to function like limbs. It is a female-only species with no male counterpart.  The tail protrusion on Mibrim''s head constantly senses and captures other creatures'' emotions. As such, Mibrim is a reclus', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b355103-dwfc5WNaQYjp.jpg', NULL, NULL, '真堂圭', NULL, 355103, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015910', 'AN1643', 'タロ', 'Taro is a second-year student attending Blueberry Academy, daughter of Unova Gym Leader Yacon, and a member of the BB League Elite Four. She uses Fairy-type Pokémon.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b378639-vMQPcAeuNB8c.png', NULL, NULL, '小林星蘭', NULL, 378639, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
