INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015913', 'AN1643', 'アゲート', 'An executive of the mysterious organization Explorers.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b311745-bmpy3m2BRNSf.jpg', NULL, NULL, '舞羽美海', NULL, 311745, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015914', 'AN1643', 'ルシアス', 'Lucius is a Pokémon Trainer who existed in the past called the “Ancient Adventurer”. It’s documented that he traveled the world with a Black Rayquaza, Oliva, Galarian Fire, Laplace, Basagiri, and Entei, collectively known as the Six Hero Pokémon. As well as his partner Terapagos, they reached a paradise known as “Rakua”.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b330035-dRoE8csb8v3t.jpg', NULL, NULL, '浪川大輔', NULL, 330035, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
