INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015916', 'AN1643', 'リップ', 'The Gym Leader of Alfornada Gym. She specializes in Psychic-type Pokémon.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b333207-HCeyGNrp39WN.png', NULL, NULL, '永井真里子', NULL, 333207, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015917', 'AN1643', 'サザレ', 'A skilled photographer from the Sinnoh region.  Sazare has a positive, upbeat and adventurous personality as a whole, being jovial and friendly to those she first meets. Sazare has a good sense of sportsmanship and honor, as she kept her word to provide information regarding Lucius''s Basagiri after Dot defeated her in a Pokemon battle. As a professional photographer, she is always keen to take pictures of Pokémon and when something catches her eye and curiosity, she is determined to take a photo', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b355096-4m22zWkehXnD.jpg', NULL, NULL, '高野麻里佳', NULL, 355096, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015918', 'AN1643', 'ルカ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b355104-QFy8zWAA9fYI.png', NULL, NULL, '高橋ひかる', NULL, 355104, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015919', 'AN1643', 'カキツバタ', 'Kakitsubata is a second-year student attending Blueberry Academy, and a member of the BB League Elite Four. He uses Dragon-type Pokémon.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b378640-BMDF7NFHryga.png', NULL, NULL, '吉野裕行', NULL, 378640, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015920', 'AN1644', '向日葵乱奈', 'Ranna Himawari is a young girl with a notorious reputation as a Sukeban wielding a Bokken, often described as a "monster" for her sheer strength and brutality. She is the first main girl to fall in love under Rokudou''s spell. Generally, Ranna does not speak or express much emotion other than emotional distance unless Rokudou is around, but tolerates his friends. Around Rokudou, she is extremely bubbly and smiles. She will not hesitate to stop and protect him when he is in danger, but will respec', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163490-6MVkyv9A3rlq.jpg', NULL, NULL, '上坂すみれ', NULL, 163490, 'MAIN', 77) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015921', 'AN1644', '六道桃助', 'Tousuke Rokudou is physically weak and cowardly attending a school filled with delinquent students. He and his two friends live in constant fear and is regularly bullied, leading to the trio venting their frustrations in private in the school''s restroom. Upon receiving a scroll from his grandfather, Rokudou gains a special pentagram mark on his forehead. Rokudou''s ancestors used this spell to exorcise oni, but in the modern day, the spell causes any "bad girl" to instantly fall in love with him ', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163492-2EHmYiG0rgmn.jpg', NULL, NULL, '佐藤元', NULL, 163492, 'MAIN', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015922', 'AN1644', '乙姫恵梨香', 'Erika is the leader of an all girl-gang, Team Ryuugu. In the past, Team Ryuugu was a street gang who constantly got into fights with rival gangs. During a brawl, Ranna joined in and became an unofficial member, helping her team ascend to the top of the city gangs. However, once the Onishima Alliance began attacking her crew, she decided to disband it for their safety. She is the one who gave Ranna her wooden sword. Now her gang are law abiding citizens who continue to dress in their original gan', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163496-3mDjPmRvnXYu.png', NULL, NULL, '駒形友梨', NULL, 163496, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015923', 'AN1644', '菫雷乃', 'The youngest of the Sumire Triplets (Amano, Kazeno, and Raino Sumire) and the only girl. Raino crossdresses, taking on an appearance and personality of an Ikemen and is skilled with make up. Her make-up skills are so convincing that she could effortlessly disguise Rokudou as a cute girl. She shares Rank 5 with Kazeno in the Onishima Alliance.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163495-lwAF3IiatzZk.png', NULL, NULL, '上田麗奈', NULL, 163495, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015924', 'AN1644', '木嶋耕太', 'Most likely nicknamed for his formal attire and businesslike demeanor, "Manager" is one of Rokudou''s friends at the beginning of the series. Like "Colonel" and Rokudou, he too, wishes to lead a peaceful life at Amori High and is constantly bullied by his delinquent classmates. Like "Colonel", he notices that Rokudou is popular with "bad girls" and tags along with Rokudou and his friends when he gets into conflict with delinquent gangs.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163489-1xHWe2VZelPe.jpg', NULL, NULL, '石田彰', NULL, 163489, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015925', 'AN1644', '幼田小百合', 'With the appearance and demeanor of an elementary school, Sayuri is often mistaken as one despite being a student at Aomori High. Despite her petite appearance, Sayuri is the Bancho of the school having built a reputation its strongest physical fighter. She originally targets Rokudou for his inexplicable ability to become popular with the female students of Amori High, but when she begins her attack on him, she becomes enamored with him due to his spell''s power. Rokudou thus becomes her first lo', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163491-W99Yey5SoUpw.jpg', NULL, NULL, '大空直美', NULL, 163491, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015926', 'AN1644', '姫野莇美', 'Passionate about police work and motorcycles, Azami Himeno is the third major female character to become enamored with Rokudou. Initially assumed to be sweet and feminine, she loves riding motorcycles. She holds a grudge against biker gangs, who she violently beats while mounted on her motorcycle. She acts like a vigilante, warning citizens about traffic safety and taking down those she perceives to be evil delinquents on the road. [4] She is the only one of the main girls to not attend Amori Hi', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163501-O3jPpiYRBNpg.png', NULL, NULL, '夜道雪', NULL, 163501, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015927', 'AN1644', '椰子谷唯', 'Holding Rank 1 in the Onishima Alliance and is the strongest member of its alliance after Douji. She has an interest in strong men, but she shows her feelings through acts of sadism, reveling in breaking their spirits. Under Rokudou''s power, she sees him as an exaggeratedly strong man that progressively intensifies during their fight. Rokudou "defeats" her after rescuing her from falling out a window, causing his power to exaggerate his appearance so much that she faints in bliss. In the afterma', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163494-7BX3VfvctVf0.png', NULL, NULL, '風間万裕子', NULL, 163494, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015928', 'AN1644', '松ヶ宮童子', 'Leader of the Onishima Alliance. Though he is polite, he can also be extremely intimidating. Like Rokudou, he was once a timid and extremely fearful of other people, resorting to bribing stronger individuals to protect him. He eventually joined the Onishima Alliance in order to be surrounded by strong individuals. After Ranna easily defeated the Alliance on her own, he fell in love with her strength and desired to have her join the alliance by gathering strong individuals to refortify its ranks,', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163503-yXPMpXJo0C3L.jpg', NULL, NULL, '山下大輝', NULL, 163503, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015929', 'AN1644', '火野本勝', 'Most likely nicknamed for military beret and camouflage in his outfit, "Colonel" is one of Rokudou''s friends from the beginning of the series. He shares Rokudou''s dream of living a peaceful school life, free of his delinquent bullies. Along with Rokudou and their friend "Manager", he huddles in a bathroom stall during school hours to vent his frustration with the way his life at Amori High is. He is the first to theorize that the ability Rokudou received from the scroll was that of making him po', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163493-wXYR9OuLZHzn.jpg', NULL, NULL, '浪川大輔', NULL, 163493, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015930', 'AN1644', '布留川葵', 'Aoi was a member of the Onjima Alliance, leading its motorcycle squad. He is normally warm and friendly, but can become violent and extremely competitive behind the wheel of his motorcycle. He was slowly being reformed by a motorcycle riding police officer until the officer was badly injured in an accident. He is a close associate to Himeno and raced against her and Rokudou, but lost. He left his gang behind and left Azami in charge of them. He has remained close with her, but often gets competi', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163504-lXmBvT5DXlXd.jpg', NULL, NULL, '七海ひろき', NULL, 163504, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015931', 'AN1644', '飯沼波瑠也', 'Iinuma was the main bully of Rokudou and his friends, subjecting them to cruel pranks at their expense. After Rokudou awakens his powers and inadvertently affected his girlfriend, Tsubaki, he challenged him to a fight. Despite being overwhelmingly stronger than him, Rokudou refused to run and took an intense beating before he asked Ranna to intervene in the fight. Impressed by his tenacity, Iinuma befriends Rokudou and becomes one of his closest allies, eventually becoming close enough to know a', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163498-fFJXwzXGCNzO.png', NULL, NULL, '石谷春貴', NULL, 163498, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015932', 'AN1644', '露草水絵', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b296994-xx5d1at23699.png', NULL, NULL, '関根瞳', NULL, 296994, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015933', 'AN1644', '椿', 'Originally one of Rokudou''s many bullies, Tsubaki is Iinuma''s girlfriend. After she falls under the spell of Rokudou''s powers, she becomes remorseful for the way she treats him, and apologizes to him while in the bathroom. Her attention to him draws the initial ire of Iinuma, though after the two become friends, Tsubaki regularly hangs out with Rokudou and his friends. She does not react to Rokudou''s power anymore.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163502-KDfpynu0nin3.png', NULL, NULL, '松岡美里', NULL, 163502, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
